const SchoolLogo = ({ size = 'md', animate = true }) => {
  const circleMap = {
    xl: { outer: 300, ring1: 286, ring2: 268, img: 250 },
    lg: { outer: 200, ring1: 190, ring2: 176, img: 164 },
    md: { outer: 56,  ring1: 52,  ring2: 48,  img: 42  },
    sm: { outer: 40,  ring1: 37,  ring2: 34,  img: 30  },
  };
  const s = circleMap[size] || circleMap.md;

  const kf = `
    @keyframes logo-spin    { from{transform:rotate(0deg)} to{transform:rotate(360deg)} }
    @keyframes logo-pulse   { 0%,100%{opacity:.6;transform:scale(1)} 50%{opacity:1;transform:scale(1.04)} }
    @keyframes logo-shimmer { 0%{transform:translateX(-120%) rotate(45deg)} 100%{transform:translateX(320%) rotate(45deg)} }
    @keyframes logo-glow    { 0%,100%{box-shadow:0 0 8px 2px rgba(212,175,55,.4),0 0 16px 4px rgba(13,148,136,.25)} 50%{box-shadow:0 0 20px 7px rgba(212,175,55,.75),0 0 34px 12px rgba(13,148,136,.45)} }
    @keyframes logo-wave    { 0%,100%{border-color:rgba(212,175,55,.5)} 50%{border-color:rgba(212,175,55,1)} }
    @keyframes banner-glow  { 0%,100%{box-shadow:0 2px 14px rgba(212,175,55,.35)} 50%{box-shadow:0 2px 26px rgba(212,175,55,.75)} }
    @keyframes ban-shine    { 0%{transform:translateX(-150%)} 100%{transform:translateX(250%)} }
  `;

  const circleEl = (
    <div style={{ position:'relative', display:'inline-flex', alignItems:'center', justifyContent:'center', width:s.outer, height:s.outer, flexShrink:0 }}>
      {animate && (size==='xl'||size==='lg') && (
        <div style={{ position:'absolute', width:s.outer, height:s.outer, borderRadius:'50%',
          border: size==='xl' ? '3px dashed rgba(212,175,55,.55)' : '2px dashed rgba(212,175,55,.4)',
          animation:'logo-spin 22s linear infinite' }} />
      )}
      <div style={{ position:'absolute', width:s.ring1, height:s.ring1, borderRadius:'50%',
        border: size==='xl' ? '3px solid rgba(212,175,55,.8)' : size==='lg' ? '2.5px solid rgba(212,175,55,.7)' : '1.5px solid rgba(212,175,55,.5)',
        animation: animate ? 'logo-wave 2.5s ease-in-out infinite, logo-glow 2.5s ease-in-out infinite' : 'none' }} />
      <div style={{ position:'absolute', width:s.ring2, height:s.ring2, borderRadius:'50%',
        border:'1.5px solid rgba(13,148,136,.45)',
        animation: animate ? 'logo-pulse 3s ease-in-out infinite' : 'none' }} />
      <div style={{ width:s.img, height:s.img, borderRadius:'50%', overflow:'hidden', position:'relative',
        boxShadow:(size==='xl'||size==='lg') ? '0 6px 28px rgba(0,0,0,.3)' : 'none' }}>
        <img src={SCHOOL_LOGO} alt="شعار المدرسة" style={{ width:'100%', height:'100%', objectFit:'cover', objectPosition:'center 90%', display:'block' }} />
        {animate && (size==='xl'||size==='lg') && (
          <div style={{ position:'absolute', inset:0,
            background:'linear-gradient(135deg,transparent 25%,rgba(255,255,255,.45) 50%,transparent 75%)',
            animation:'logo-shimmer 3.2s ease-in-out infinite', pointerEvents:'none' }} />
        )}
      </div>
    </div>
  );

  if (size === 'sm' || size === 'md') {
    return <><style>{kf}</style>{circleEl}</>;
  }

  const bw  = size==='xl' ? s.outer + 20 : s.outer + 10;
  const bfs = size==='xl' ? 15 : 12;
  const bpy = size==='xl' ? 10 : 7;
  const bannerStyle = (delay) => ({
    width:bw, textAlign:'center', direction:'rtl',
    background:'linear-gradient(135deg,#1a5c33,#0d7a47,#1a5c33)',
    borderRadius:14, padding:`${bpy}px 16px`,
    position:'relative', overflow:'hidden',
    animation: animate ? `banner-glow 2.5s ease-in-out infinite ${delay}` : 'none',
  });
  const shineStyle = (delay) => ({
    position:'absolute', top:0, left:0, right:0, bottom:0,
    background:'linear-gradient(90deg,transparent,rgba(255,255,255,.15),transparent)',
    animation:`ban-shine 2.8s ease-in-out infinite ${delay}`,
    pointerEvents:'none',
  });
  const textStyle = (fs) => ({
    color:'#fff', fontWeight:900, fontSize:fs,
    textShadow:'0 1px 4px rgba(0,0,0,.35)',
    position:'relative', letterSpacing:'.4px',
  });

  return (
    <>
      <style>{kf}</style>
      <div style={{ display:'inline-flex', flexDirection:'column', alignItems:'center', gap: size==='xl' ? 14 : 10 }}>
          <div style={bannerStyle('0s')}>
          {animate && <div style={shineStyle('0s')} />}
          <span style={textStyle(bfs)}>وزارة التعليم — الإدارة العامة للتعليم بجدة</span>
        </div>
        {circleEl}
        <div style={{ ...bannerStyle('1.2s'), width: bw * 0.85 }}>
          {animate && <div style={shineStyle('.6s')} />}
          <span style={textStyle(bfs + 1)}>تعليم ✦ تميّز ✦ انتماء</span>
        </div>
      </div>
    </>
  );
};
function Badge({ children, color = "teal" }) {
  const c = { teal: "bg-teal-100 text-teal-800", red: "bg-red-100 text-red-700", amber: "bg-amber-100 text-amber-800", blue: "bg-blue-100 text-blue-800", green: "bg-green-100 text-green-800", purple: "bg-purple-100 text-purple-800", gray: "bg-gray-100 text-gray-600" };
  return <span className={`px-2 py-0.5 rounded-full text-xs font-bold ${c[color] || c.teal}`}>{children}</span>;
}

function StatCard({ icon, label, value, color }) {
  return (
    <div className={`rounded-2xl p-4 ${color} shadow-sm flex items-center gap-4 transition-transform hover:scale-105`}>
      <div className="text-3xl">{icon}</div>
      <div><div className="text-2xl font-black">{value}</div><div className="text-sm opacity-80 font-medium">{label}</div></div>
    </div>
  );
}

function RichEditor({ value, onChange }) {
  const editorRef  = useRef(null);
  const wrapRef    = useRef(null);
  const fileRef    = useRef(null);
  const rowRef     = useRef(null);
  const selImgRef  = useRef(null);
  const dragRef    = useRef(null);
  const [showEmoji, setShowEmoji] = useState(false);
  const [showStickers, setShowStickers] = useState(false);
  const [showColors, setShowColors] = useState(false);
  const [showBgColors, setShowBgColors] = useState(false);
  const [showFonts, setShowFonts] = useState(false);
  const [imgSize, setImgSize] = useState("medium");
  const [overlay, setOverlay] = useState(null);
  const [customW, setCustomW] = useState("");

  const emojis = ["⭐","🎉","📢","📌","🔔","✅","❌","❗","⚠️","💡","📅","🏫","👨‍🏫","👨‍🎓","📖","🖋️","🎓","🏆","🥇","⚽","🔬","🎨","🎵","💪","👏","🤝","💐","🌟","✨","🔥","💯","❤️","💚","💙","🇸🇦","🌙","☀️","🌈","🎯","📝","🏅","🌺","🍀","🦁","🦅","🕌","🤲","🫶","😊","😄","👍","🙏"];
  const stickers = ["🏆 تهانينا!","⭐ ممتاز!","✅ تم بنجاح","📢 تنبيه مهم","🎉 مبروك!","💡 تذكير","⚠️ عاجل","📌 ملاحظة","🏫 من إدارة المدرسة","👨‍🏫 للمعلمين الكرام","👨‍🎓 للطلاب الأعزاء","🤝 بالتوفيق للجميع","🌟 إعلان هام","🎯 للاهتمام"];
  const textColors = ["#000000","#DC2626","#059669","#2563EB","#7C3AED","#D97706","#DB2777","#0D9488","#B45309","#1D4ED8","#065F46","#7F1D1D","#1E40AF","#166534"];
  const bgColors = ["transparent","#FEF3C7","#DCFCE7","#DBEAFE","#F3E8FF","#FFE4E6","#E0F2FE","#FEF9C3","#D1FAE5","#FCE7F3","#FFF7ED","#F0FDF4"];

  const selRef = useRef(null);
  const saveSel = () => { try { const sl = window.getSelection(); if (sl && sl.rangeCount && editorRef.current && editorRef.current.contains(sl.anchorNode)) selRef.current = sl.getRangeAt(0).cloneRange(); } catch {} };
  const restoreSel = () => { const ed = editorRef.current; if (!ed) return; ed.focus(); try { const sl = window.getSelection(); if (sl && (!sl.rangeCount || !ed.contains(sl.anchorNode))) { let r = selRef.current; if (!r || !ed.contains(r.startContainer)) { r = document.createRange(); r.selectNodeContents(ed); r.collapse(false); } sl.removeAllRanges(); sl.addRange(r); } } catch {} };
  const exec = (cmd, val = null) => { restoreSel(); document.execCommand(cmd, false, val); saveSel(); if (editorRef.current) onChange(editorRef.current.innerHTML); };
  const imgTag = (src, w) => `<img src="${src}" style="width:${w};max-width:100%;height:auto;border-radius:12px;margin:8px auto;display:block;cursor:pointer;" />`;
  const handleRow = async (e) => {
    const files = [...(e.target.files || [])].filter(f => f.type.startsWith("image/")).slice(0, 3); e.target.value = ""; if (!files.length) return;
    const urls = await Promise.all(files.map(f => readFileAsync(f, "dataurl")));
    const w = files.length === 1 ? "60%" : files.length === 2 ? "49%" : "32.5%";
    exec("insertHTML", `<div style="display:flex;gap:1%;justify-content:center;align-items:flex-start;margin:8px 0;flex-wrap:nowrap">${urls.map(u => `<img src="${u}" style="width:${w};max-width:${w};height:auto;border-radius:12px;object-fit:cover;cursor:pointer;" />`).join("")}</div><p><br></p>`);
  };
  const imgAlign = (mode) => { const img = selImgRef.current; if (!img) return; img.style.float = ""; img.style.margin = ""; img.style.display = "block";
    if (mode === "right") { img.style.float = "right"; img.style.margin = "4px 0 8px 14px"; img.style.display = "inline"; if (!/%|px/.test(img.style.width) || parseFloat(img.style.width) > 60) img.style.width = "45%"; }
    else if (mode === "left") { img.style.float = "left"; img.style.margin = "4px 14px 8px 0"; img.style.display = "inline"; if (!/%|px/.test(img.style.width) || parseFloat(img.style.width) > 60) img.style.width = "45%"; }
    else img.style.margin = "8px auto";
    onChange(editorRef.current.innerHTML); setTimeout(() => setOverlay(calcOverlay(img)), 30); };
  const imgMove = (dir) => { const img = selImgRef.current; if (!img) return; const blk = img.parentElement && img.parentElement !== editorRef.current && img.parentElement.children.length === 1 ? img.parentElement : img; const sib = dir < 0 ? blk.previousElementSibling : blk.nextElementSibling; if (!sib) return; if (dir < 0) sib.before(blk); else sib.after(blk); onChange(editorRef.current.innerHTML); setTimeout(() => setOverlay(calcOverlay(img)), 30); };
  const IMG_SIZES = {
    tiny:   { w: "150px", label: "صغير جداً",    icon: "⬛" },
    small:  { w: "30%",   label: "صغير",          icon: "🔹" },
    medium: { w: "50%",   label: "متوسط",          icon: "🔸" },
    large:  { w: "75%",   label: "كبير",            icon: "🟧" },
    full:   { w: "100%",  label: "كامل العرض",     icon: "🟥" },
  };

  // ─── حساب موضع الـ overlay فوق الصورة ───
  const calcOverlay = (img) => {
    if (!img || !wrapRef.current) return null;
    const wr = wrapRef.current.getBoundingClientRect();
    const ir = img.getBoundingClientRect();
    return { top: ir.top - wr.top + wrapRef.current.scrollTop,
             left: ir.left - wr.left, w: ir.width, h: ir.height };
  };

  // ─── الاستماع لنقرات داخل المحرر ───
  useEffect(() => {
    const ed = editorRef.current; if (!ed) return;
    const onClick = (e) => {
      if (e.target.tagName === "IMG") {
        selImgRef.current = e.target;
        setOverlay(calcOverlay(e.target));
        setCustomW(Math.round(e.target.getBoundingClientRect().width) + "");
      } else {
        selImgRef.current = null; setOverlay(null);
      }
    };
    ed.addEventListener("click", onClick);
    return () => ed.removeEventListener("click", onClick);
  }, []);

  // ─── تطبيق حجم على الصورة المحددة ───
  const applySize = (w) => {
    const img = selImgRef.current; if (!img) return;
    img.style.width = w; img.style.height = "auto";
    onChange(editorRef.current.innerHTML);
    setTimeout(() => setOverlay(calcOverlay(img)), 30);
  };

  // ─── سحب الحافة اليمنى أو اليسرى لتغيير الحجم ───
  const startDrag = (e, side) => {
    e.preventDefault(); e.stopPropagation();
    const img = selImgRef.current; if (!img) return;
    const startX = e.clientX;
    const startW = img.getBoundingClientRect().width;
    const isRtl  = side === "left"; // RTL: سحب اليسار = توسيع
    dragRef.current = true;
    const onMove = (ev) => {
      const dx = ev.clientX - startX;
      const newW = Math.max(60, startW + (isRtl ? -dx : dx));
      img.style.width = newW + "px"; img.style.height = "auto";
      setOverlay(calcOverlay(img));
    };
    const onUp = () => {
      onChange(editorRef.current.innerHTML);
      dragRef.current = false;
      document.removeEventListener("mousemove", onMove);
      document.removeEventListener("mouseup",   onUp);
    };
    document.addEventListener("mousemove", onMove);
    document.addEventListener("mouseup",   onUp);
  };

  // ─── سحب الزاوية (ركن) ───
  const startCornerDrag = (e, corner) => {
    e.preventDefault(); e.stopPropagation();
    const img = selImgRef.current; if (!img) return;
    const r = img.getBoundingClientRect();
    const startX = e.clientX, startY = e.clientY;
    const startW = r.width, startH = r.height;
    const onMove = (ev) => {
      const dx = ev.clientX - startX, dy = ev.clientY - startY;
      let nw, nh;
      if (corner === "se")      { nw = startW + dx; nh = startH + dy; }
      else if (corner === "sw") { nw = startW - dx; nh = startH + dy; }
      else if (corner === "ne") { nw = startW + dx; nh = startH - dy; }
      else                      { nw = startW - dx; nh = startH - dy; }
      nw = Math.max(60, nw); nh = Math.max(40, nh);
      img.style.width = nw + "px"; img.style.height = nh + "px";
      setOverlay(calcOverlay(img));
    };
    const onUp = () => {
      onChange(editorRef.current.innerHTML);
      document.removeEventListener("mousemove", onMove);
      document.removeEventListener("mouseup",   onUp);
    };
    document.addEventListener("mousemove", onMove);
    document.addEventListener("mouseup",   onUp);
  };

  const handleImage = (e) => {
    const file = e.target.files?.[0]; if (!file) return;
    const sz = IMG_SIZES[imgSize] || IMG_SIZES.medium;
    readFileAsync(file, "dataurl").then(dataUrl => { exec("insertHTML", imgTag(dataUrl, sz.w)); });
    e.target.value = "";
  };
  const handleInput = () => { if (editorRef.current) onChange(editorRef.current.innerHTML); };
  useEffect(() => { if (editorRef.current && !editorRef.current.innerHTML && value) editorRef.current.innerHTML = value; }, []);
  const closeAll = () => { setShowEmoji(false); setShowStickers(false); setShowColors(false); setShowBgColors(false); setShowFonts(false); };

  const ToolBtn = ({ onClick, title, children }) => (
    <button type="button" onClick={onClick} title={title}
      className="h-8 px-2 rounded-lg flex items-center justify-center text-xs hover:bg-teal-100 bg-gray-50 text-gray-700 font-medium transition-all whitespace-nowrap">
      {children}
    </button>
  );

  return (
    <div ref={wrapRef} className="border-2 border-gray-200 rounded-xl overflow-visible focus-within:border-teal-400 transition-all" style={{ position:"relative" }}>
      {/* ─── Image Resize Overlay ─── */}
      {overlay && selImgRef.current && (
        <div style={{
          position:"absolute", top:overlay.top, left:overlay.left,
          width:overlay.w, height:overlay.h, zIndex:100,
          pointerEvents:"none",
        }}>
          {/* حد الاختيار */}
          <div style={{ position:"absolute", inset:0, border:"2px dashed #0ea5e9", borderRadius:8, boxShadow:"0 0 0 1px rgba(14,165,233,0.3)" }} />
          {/* شريط أدوات الحجم يظهر فوق الصورة */}
          <div style={{
            position:"absolute", top:-44, left:"50%", transform:"translateX(-50%)",
            background:"#1e293b", borderRadius:10, padding:"4px 8px",
            display:"flex", alignItems:"center", gap:4, whiteSpace:"nowrap",
            boxShadow:"0 4px 20px rgba(0,0,0,0.4)", pointerEvents:"all",
          }}>
            {Object.entries(IMG_SIZES).map(([k,v]) => (
              <button key={k} onMouseDown={(e)=>{e.preventDefault();applySize(v.w);}}
                title={v.label}
                style={{ background:"#334155", border:"1px solid #475569", borderRadius:6,
                         padding:"2px 7px", fontSize:11, color:"#e2e8f0", cursor:"pointer",
                         fontFamily:"inherit" }}>
                {v.icon} {v.label}
              </button>
            ))}
            <div style={{ width:1, background:"#475569", height:18, margin:"0 2px" }} />
            <input
              type="number" min="50" max="2000"
              value={customW}
              onChange={e => setCustomW(e.target.value)}
              onKeyDown={e => { if (e.key==="Enter") { applySize(customW+"px"); e.preventDefault(); } }}
              onMouseDown={e => e.stopPropagation()}
              style={{ width:58, background:"#0f172a", border:"1px solid #475569",
                       borderRadius:6, padding:"2px 5px", fontSize:11, color:"#94a3b8",
                       textAlign:"center", fontFamily:"inherit" }}
              placeholder="px"
            />
            <button onMouseDown={(e)=>{e.preventDefault();applySize(customW+"px");}}
              style={{ background:"#0ea5e9", border:"none", borderRadius:6,
                       padding:"2px 8px", fontSize:11, color:"#fff", cursor:"pointer" }}>✓</button>
            <button onMouseDown={(e)=>{e.preventDefault();if(selImgRef.current){selImgRef.current.remove();onChange(editorRef.current.innerHTML);selImgRef.current=null;setOverlay(null);}}}
              style={{ background:"#ef4444", border:"none", borderRadius:6,
                       padding:"2px 7px", fontSize:11, color:"#fff", cursor:"pointer" }}>🗑️</button>
          </div>
          <div style={{ position:"absolute", bottom:-40, left:"50%", transform:"translateX(-50%)", background:"#1e293b", borderRadius:10, padding:"4px 6px", display:"flex", gap:4, whiteSpace:"nowrap", boxShadow:"0 4px 20px rgba(0,0,0,0.4)", pointerEvents:"all", zIndex:2 }}>
            {[["right","↦ يمين والنص بجانبها"],["center","وسط"],["left","يسار والنص بجانبها ↤"]].map(([m,l]) => <button key={m} onMouseDown={e=>{e.preventDefault();imgAlign(m);}} style={{ background:"#334155", border:"1px solid #475569", borderRadius:6, padding:"2px 7px", fontSize:11, color:"#e2e8f0", cursor:"pointer", fontFamily:"inherit" }}>{l}</button>)}
            <button onMouseDown={e=>{e.preventDefault();imgMove(-1);}} title="تحريك للأعلى" style={{ background:"#0ea5e9", border:"none", borderRadius:6, padding:"2px 8px", fontSize:12, color:"#fff", cursor:"pointer" }}>▲</button>
            <button onMouseDown={e=>{e.preventDefault();imgMove(1);}} title="تحريك للأسفل" style={{ background:"#0ea5e9", border:"none", borderRadius:6, padding:"2px 8px", fontSize:12, color:"#fff", cursor:"pointer" }}>▼</button>
          </div>
          {/* ─── مقابض تغيير الحجم ─── */}
          {/* حافة يمين */}
          <div onMouseDown={e=>startDrag(e,"right")} style={{
            position:"absolute", top:"50%", right:-6, width:12, height:26,
            background:"#0ea5e9", borderRadius:4, cursor:"ew-resize", transform:"translateY(-50%)",
            pointerEvents:"all", boxShadow:"0 2px 6px rgba(0,0,0,0.4)",
          }} />
          {/* حافة يسار */}
          <div onMouseDown={e=>startDrag(e,"left")} style={{
            position:"absolute", top:"50%", left:-6, width:12, height:26,
            background:"#0ea5e9", borderRadius:4, cursor:"ew-resize", transform:"translateY(-50%)",
            pointerEvents:"all", boxShadow:"0 2px 6px rgba(0,0,0,0.4)",
          }} />
          {/* حافة أسفل */}
          <div onMouseDown={e=>{ e.preventDefault(); const img=selImgRef.current; if(!img) return; const sY=e.clientY; const sH=img.getBoundingClientRect().height; const mv=ev=>{img.style.height=Math.max(40,sH+(ev.clientY-sY))+"px";setOverlay(calcOverlay(img));}; const up=()=>{onChange(editorRef.current.innerHTML);document.removeEventListener("mousemove",mv);document.removeEventListener("mouseup",up);}; document.addEventListener("mousemove",mv);document.addEventListener("mouseup",up); }} style={{
            position:"absolute", bottom:-6, left:"50%", width:26, height:12,
            background:"#0ea5e9", borderRadius:4, cursor:"ns-resize", transform:"translateX(-50%)",
            pointerEvents:"all", boxShadow:"0 2px 6px rgba(0,0,0,0.4)",
          }} />
          {/* ركن أسفل يمين */}
          <div onMouseDown={e=>startCornerDrag(e,"se")} style={{
            position:"absolute", bottom:-6, right:-6, width:14, height:14,
            background:"#7c3aed", borderRadius:3, cursor:"se-resize",
            pointerEvents:"all", boxShadow:"0 2px 6px rgba(0,0,0,0.4)",
          }} />
          {/* ركن أسفل يسار */}
          <div onMouseDown={e=>startCornerDrag(e,"sw")} style={{
            position:"absolute", bottom:-6, left:-6, width:14, height:14,
            background:"#7c3aed", borderRadius:3, cursor:"sw-resize",
            pointerEvents:"all", boxShadow:"0 2px 6px rgba(0,0,0,0.4)",
          }} />
          {/* ركن أعلى يمين */}
          <div onMouseDown={e=>startCornerDrag(e,"ne")} style={{
            position:"absolute", top:-6, right:-6, width:14, height:14,
            background:"#7c3aed", borderRadius:3, cursor:"ne-resize",
            pointerEvents:"all", boxShadow:"0 2px 6px rgba(0,0,0,0.4)",
          }} />
          {/* ركن أعلى يسار */}
          <div onMouseDown={e=>startCornerDrag(e,"nw")} style={{
            position:"absolute", top:-6, left:-6, width:14, height:14,
            background:"#7c3aed", borderRadius:3, cursor:"nw-resize",
            pointerEvents:"all", boxShadow:"0 2px 6px rgba(0,0,0,0.4)",
          }} />
        </div>
      )}

      <div className="bg-gray-50 p-2 flex flex-wrap gap-1 border-b border-gray-200">
        <ToolBtn onClick={() => exec("bold")} title="غامق"><b>غامق</b></ToolBtn>
        <ToolBtn onClick={() => exec("italic")} title="مائل"><i>مائل</i></ToolBtn>
        <ToolBtn onClick={() => exec("underline")} title="تحته خط"><u>خط</u></ToolBtn>
        <div className="w-px bg-gray-300 mx-1"></div>
        <select onChange={e => exec("fontSize", e.target.value)} defaultValue="3"
          className="h-8 px-1 rounded-lg bg-gray-50 border border-gray-200 text-xs cursor-pointer focus:outline-none">
          <option value="1">صغير جداً</option><option value="2">صغير</option><option value="3">متوسط</option>
          <option value="4">كبير</option><option value="5">كبير جداً</option><option value="6">ضخم</option><option value="7">ضخم جداً</option>
        </select>
        <div className="relative">
          <ToolBtn onClick={() => { closeAll(); setShowFonts(!showFonts); }} title="نوع الخط">🔤 الخط</ToolBtn>
          {showFonts && (
            <div className="absolute top-10 right-0 bg-white rounded-xl shadow-xl border border-gray-200 p-2 z-50 w-44">
              {FONTS.map(f => (
                <button key={f.value} onClick={() => { exec("fontName", f.value); setShowFonts(false); }}
                  className="w-full text-right px-3 py-2 rounded-lg hover:bg-teal-50 text-sm" style={{ fontFamily: f.value }}>{f.label}</button>
              ))}
            </div>
          )}
        </div>
        <div className="w-px bg-gray-300 mx-1"></div>
        <ToolBtn onClick={() => exec("justifyRight")} title="يمين">⬅ يمين</ToolBtn>
        <ToolBtn onClick={() => exec("justifyCenter")} title="وسط">↔ وسط</ToolBtn>
        <ToolBtn onClick={() => exec("justifyLeft")} title="يسار">➡ يسار</ToolBtn>
        <ToolBtn onClick={() => exec("justifyFull")} title="ضبط">☰ ضبط</ToolBtn>
        <ToolBtn onClick={() => exec("indent")} title="إزاحة النص للداخل">⇤ إزاحة</ToolBtn>
        <ToolBtn onClick={() => exec("outdent")} title="إرجاع الإزاحة">⇥ إرجاع</ToolBtn>
        <div className="w-px bg-gray-300 mx-1"></div>
        <div className="relative">
          <ToolBtn onClick={() => { closeAll(); setShowColors(!showColors); }} title="لون النص">🎨 لون</ToolBtn>
          {showColors && (
            <div className="absolute top-10 right-0 bg-white rounded-xl shadow-xl border border-gray-200 p-2 z-50 flex gap-1 flex-wrap w-44">
              {textColors.map(c => (
                <button key={c} onClick={() => { exec("foreColor", c); setShowColors(false); }}
                  className="w-7 h-7 rounded-full border-2 border-gray-200 hover:scale-110 transition-transform" style={{ backgroundColor: c }}></button>
              ))}
            </div>
          )}
        </div>
        <div className="relative">
          <ToolBtn onClick={() => { closeAll(); setShowBgColors(!showBgColors); }} title="خلفية">🖌 خلفية</ToolBtn>
          {showBgColors && (
            <div className="absolute top-10 right-0 bg-white rounded-xl shadow-xl border border-gray-200 p-2 z-50 flex gap-1 flex-wrap w-44">
              {bgColors.map(c => (
                <button key={c} onClick={() => { exec("hiliteColor", c); setShowBgColors(false); }}
                  className="w-7 h-7 rounded-full border-2 border-gray-200 hover:scale-110 transition-transform"
                  style={{ backgroundColor: c === "transparent" ? "#fff" : c }}>{c === "transparent" ? "✕" : ""}</button>
              ))}
            </div>
          )}
        </div>
        <div className="w-px bg-gray-300 mx-1"></div>
        {/* حجم الصورة عند الإضافة */}
        <div className="flex items-center gap-1">
          <span className="text-xs text-gray-400 font-bold">📷</span>
          <select value={imgSize} onChange={e => setImgSize(e.target.value)}
            className="h-8 px-1 rounded-lg bg-gray-50 border border-gray-200 text-xs cursor-pointer focus:outline-none"
            title="حجم الصورة عند الإضافة">
            {Object.entries(IMG_SIZES).map(([k,v]) => <option key={k} value={k}>{v.icon} {v.label}</option>)}
          </select>
        </div>
        <ToolBtn onClick={() => { saveSel(); fileRef.current?.click(); }} title="إضافة صورة">📷 صورة</ToolBtn>
        <input ref={fileRef} type="file" accept="image/*" className="hidden" onChange={handleImage} />
        <ToolBtn onClick={() => { saveSel(); rowRef.current?.click(); }} title="اختر صورتين أو ثلاثاً لتظهر متجاورة">🖼️🖼️ صور متجاورة</ToolBtn>
        <input ref={rowRef} type="file" accept="image/*" multiple className="hidden" onChange={handleRow} />
        <div className="relative">
          <ToolBtn onClick={() => { closeAll(); setShowEmoji(!showEmoji); }} title="إيموجي">😊 إيموجي</ToolBtn>
          {showEmoji && (
            <div className="absolute top-10 right-0 bg-white rounded-xl shadow-xl border border-gray-200 p-2 z-50 flex gap-1 flex-wrap w-64 max-h-48 overflow-y-auto">
              {emojis.map(e => (
                <button key={e} onClick={() => { exec("insertText", e); setShowEmoji(false); }}
                  className="w-9 h-9 rounded-lg hover:bg-gray-100 flex items-center justify-center text-xl">{e}</button>
              ))}
            </div>
          )}
        </div>
        <div className="relative">
          <ToolBtn onClick={() => { closeAll(); setShowStickers(!showStickers); }} title="ملصقات">🏷️ ملصق</ToolBtn>
          {showStickers && (
            <div className="absolute top-10 right-0 bg-white rounded-xl shadow-xl border border-gray-200 p-2 z-50 w-56 max-h-52 overflow-y-auto">
              {stickers.map(s => (
                <button key={s} onClick={() => {
                  exec("insertHTML", `<span style="display:inline-block;background:#f0fdf4;border:1px solid #86efac;border-radius:8px;padding:2px 10px;margin:2px;font-size:13px;">${s}</span>`);
                  setShowStickers(false);
                }} className="w-full text-right px-2 py-2 rounded-lg hover:bg-teal-50 text-sm">{s}</button>
              ))}
            </div>
          )}
        </div>
        <ToolBtn onClick={() => exec("insertUnorderedList")} title="قائمة">• قائمة</ToolBtn>
      </div>
      <div ref={editorRef} contentEditable dir="rtl" onInput={handleInput} onKeyUp={saveSel} onMouseUp={saveSel} onBlur={saveSel}
        className="min-h-36 p-4 text-sm leading-relaxed focus:outline-none"
        style={{ direction: "rtl", fontFamily: "'Noto Naskh Arabic', serif" }}
        data-placeholder="اكتب محتوى الإعلان هنا…"></div>
      <style>{`[contenteditable]:empty:before { content: attr(data-placeholder); color: #9CA3AF; pointer-events: none; }`}</style>
    </div>
  );
}

const LOGO_URL = hfxAbs(schoolLogoImg);
const SCHOOL_LOGO_URL = "data:image/svg+xml;base64,";


// ── 👁️ عداد زيارات الإعلان: يُحتسب الزائر مرة واحدة في اليوم لكل إعلان، مع تاريخ آخر زيارة
function AnnViews({ id, readOnly = false }) {
  const [S, setS] = React.useState(null);
  React.useEffect(() => { if (!id) return; let alive = true; const key = `school-visitor-ann-single-${id}`, lk = `school-visitor-last/ann-${id}`;
    (async () => { try {
      const [n0, l0] = await Promise.all([fetch(`${FIREBASE_URL}/school/${key}.json`).then(r => r.json()), fetch(`${FIREBASE_URL}/school/${lk}.json`).then(r => r.json())]);
      let n = +n0 || 0; const day = new Date().toDateString(); let seen = false; try { seen = localStorage.getItem("pam-av-" + id) === day; } catch {}
      if (!readOnly && !seen) { try { localStorage.setItem("pam-av-" + id, day); } catch {}
        const h = { "Content-Type": "application/json" }; n = n + 1;
        fetch(`${FIREBASE_URL}/school/${key}.json`, { method: "PUT", headers: h, body: JSON.stringify({ ".sv": { increment: 1 } }) }).catch(() => {});
        fetch(`${FIREBASE_URL}/school/${lk}.json`, { method: "PUT", headers: h, body: JSON.stringify({ ".sv": "timestamp" }) }).catch(() => {}); }
      if (alive) setS({ n, last: +l0 || 0 }); } catch { if (alive) setS({ n: 0, last: 0 }); } })();
    return () => { alive = false; }; }, [id]);
  if (!S) return null;
  const lastTxt = S.last ? (() => { const d = new Date(S.last); return `${maDay(d)} ${d.toLocaleDateString("ar-SA-u-ca-islamic-umalqura-nu-arab", { day: "numeric", month: "long" })} • ${d.toLocaleTimeString("ar-SA-u-nu-arab", { hour: "numeric", minute: "2-digit" })}`; })() : "";
  return <div dir="rtl" style={{ display: "inline-flex", alignItems: "center", gap: 12, flexWrap: "wrap", justifyContent: "center", background: "linear-gradient(135deg,#f0fdfa,#ecfeff)", border: "1.5px solid #99f6e4", borderRadius: 18, padding: "8px 18px", boxShadow: "0 6px 16px -10px rgba(13,148,136,.6)" }}>
    <span style={{ display: "inline-flex", alignItems: "center", gap: 8 }}><span style={{ fontSize: 22 }}>👁️</span><b style={{ fontSize: 24, fontWeight: 900, color: "#0f766e", lineHeight: 1 }}>{maAr(S.n.toLocaleString("en-US"))}</b><span style={{ fontSize: 13, fontWeight: 800, color: "#115e59" }}>زيارة</span></span>
    {lastTxt && <span style={{ fontSize: 12.5, fontWeight: 800, color: "#475569", borderInlineStart: "1.5px solid #99f6e4", paddingInlineStart: 12 }}>🕒 آخر زيارة: {lastTxt}</span>}
  </div>;
}

// ── عداد زوار بارز لأعلى الصفحات العامة ──
function BoldVisitorBadge({ pageKey }) {
  const [count, setCount] = React.useState(null);
  React.useEffect(() => {
    const key = `school-visitor-${pageKey}`;
    DB.get(key, 0).then(c => {
      const n = (c || 0) + 1;
      setCount(n);
      DB.set(key, n);
    });
  }, [pageKey]);
  if (count === null) return null;
  return (
    <div style={{
      display:"inline-flex", alignItems:"center", gap:8,
      background:"linear-gradient(135deg,rgba(255,255,255,.22),rgba(255,255,255,.10))",
      backdropFilter:"blur(8px)",
      border:"1.5px solid rgba(255,255,255,.35)",
      borderRadius:40, padding:"6px 18px",
      boxShadow:"0 4px 16px rgba(0,0,0,.12)"
    }}>
      <span style={{fontSize:18}}>👁️</span>
      <div style={{textAlign:"right"}}>
        <div style={{fontWeight:900, fontSize:20, color:"#fff", lineHeight:1,
          textShadow:"0 1px 4px rgba(0,0,0,.2)"}}>
          {count.toLocaleString("ar-SA-u-nu-latn")}
        </div>
        <div style={{fontSize:10, color:"rgba(255,255,255,.85)", fontWeight:700, marginTop:1}}>زيارة</div>
      </div>
    </div>
  );
}

// ── مكوّن تعليقات للإعلانات والأنشطة ──
function PublicComments({ itemKey, itemTitle }) {
  const DB_KEY = `school-comments-${itemKey}`;
  const [comments, setComments] = React.useState([]);
  const [name, setName] = React.useState("");
  const [text, setText] = React.useState("");
  const [saving, setSaving] = React.useState(false);
  const [showForm, setShowForm] = React.useState(false);
  const [loaded, setLoaded] = React.useState(false);
  const [showAll, setShowAll] = React.useState(false);

  React.useEffect(() => {
    DB.get(DB_KEY, []).then(d => {
      setComments(Array.isArray(d) ? d : []);
      setLoaded(true);
    });
  }, [DB_KEY]);

  const submit = async () => {
    if (!text.trim()) return;
    setSaving(true);
    const newC = {
      id: Date.now(),
      name: name.trim() || "زائر",
      text: text.trim(),
      date: new Date().toLocaleDateString("ar-SA"),
      time: new Date().toLocaleTimeString("ar-SA-u-nu-latn", {hour:"2-digit", minute:"2-digit"}),
    };
    const updated = [newC, ...comments];
    await DB.set(DB_KEY, updated);
    setComments(updated);
    setName(""); setText(""); setSaving(false); setShowForm(false);
  };

  const visible = showAll ? comments : comments.slice(0, 3);

  if (!loaded) return null;

  return (
    <div dir="rtl" style={{marginTop:16, borderTop:"1.5px solid #e2e8f0", paddingTop:14}}>
      {/* عنوان قسم التعليقات */}
      <div style={{display:"flex", alignItems:"center", justifyContent:"space-between", marginBottom:10}}>
        <div style={{display:"flex", alignItems:"center", gap:7}}>
          <span style={{fontSize:18}}>💬</span>
          <span style={{fontWeight:900, fontSize:14, color:"#0d3b6e"}}>التعليقات</span>
          {comments.length > 0 && (
            <span style={{background:"#0d9488", color:"#fff", borderRadius:"50%",
              width:20, height:20, display:"flex", alignItems:"center", justifyContent:"center",
              fontSize:11, fontWeight:900}}>{comments.length}</span>
          )}
        </div>
        <button onClick={() => setShowForm(p => !p)}
          style={{padding:"5px 14px", borderRadius:20, background:showForm?"#fee2e2":"linear-gradient(135deg,#0d9488,#0f766e)",
            color:showForm?"#dc2626":"#fff", fontWeight:700, fontSize:12,
            border:showForm?"1.5px solid #fca5a5":"none", cursor:"pointer",
            fontFamily:"'Cairo',sans-serif"}}>
          {showForm ? "✕ إلغاء" : "✍️ أضف تعليقاً"}
        </button>
      </div>

      {/* نموذج التعليق */}
      {showForm && (
        <div style={{background:"#f8fafc", borderRadius:14, padding:14, marginBottom:12,
          border:"1.5px solid #e2e8f0"}}>
          <input value={name} onChange={e => setName(e.target.value)}
            placeholder="اسمك (اختياري)"
            style={{width:"100%", padding:"8px 12px", borderRadius:10, border:"1.5px solid #e2e8f0",
              fontSize:13, fontFamily:"'Cairo',sans-serif", marginBottom:8, boxSizing:"border-box"}} />
          <textarea value={text} onChange={e => setText(e.target.value)}
            placeholder="اكتب تعليقك هنا..."
            rows={3}
            style={{width:"100%", padding:"8px 12px", borderRadius:10, border:"1.5px solid #e2e8f0",
              fontSize:13, fontFamily:"'Cairo',sans-serif", resize:"vertical",
              marginBottom:8, boxSizing:"border-box", lineHeight:1.8}} />
          <button onClick={submit} disabled={saving || !text.trim()}
            style={{padding:"8px 20px", borderRadius:10,
              background:saving||!text.trim()?"#94a3b8":"linear-gradient(135deg,#0d9488,#0f766e)",
              color:"#fff", fontWeight:700, fontSize:13, border:"none",
              cursor:saving||!text.trim()?"not-allowed":"pointer",
              fontFamily:"'Cairo',sans-serif"}}>
            {saving ? "⏳ جاري الإرسال..." : "إرسال التعليق 📤"}
          </button>
        </div>
      )}

      {/* قائمة التعليقات */}
      {comments.length === 0 ? (
        <div style={{textAlign:"center", padding:"20px 0", color:"#94a3b8", fontSize:13}}>
          <div style={{fontSize:32, marginBottom:6}}>💬</div>
          لا توجد تعليقات بعد — كن أول من يعلّق!
        </div>
      ) : (
        <>
          <div style={{display:"grid", gap:8}}>
            {visible.map(c => (
              <div key={c.id} style={{background:"#f8fafc", borderRadius:12,
                padding:"10px 14px", border:"1px solid #e2e8f0"}}>
                <div style={{display:"flex", alignItems:"center", gap:8, marginBottom:5}}>
                  <div style={{width:32, height:32, borderRadius:"50%",
                    background:"linear-gradient(135deg,#0d9488,#0d3b6e)",
                    color:"#fff", display:"flex", alignItems:"center",
                    justifyContent:"center", fontWeight:900, fontSize:14, flexShrink:0}}>
                    {c.name.charAt(0)}
                  </div>
                  <div>
                    <div style={{fontWeight:800, fontSize:13, color:"#1e293b"}}>{c.name}</div>
                    <div style={{fontSize:10, color:"#94a3b8"}}>{c.date} — {c.time}</div>
                  </div>
                </div>
                <p style={{fontSize:13, color:"#374151", lineHeight:1.8, margin:0, paddingRight:40}}>
                  {c.text}
                </p>
              </div>
            ))}
          </div>
          {comments.length > 3 && (
            <button onClick={() => setShowAll(p => !p)}
              style={{width:"100%", marginTop:8, padding:"8px 0",
                background:"#f1f5f9", borderRadius:10,
                color:"#0d9488", fontWeight:700, fontSize:12,
                border:"1.5px solid #e2e8f0", cursor:"pointer",
                fontFamily:"'Cairo',sans-serif"}}>
              {showAll ? "▲ عرض أقل" : `▼ عرض كل التعليقات (${comments.length})`}
            </button>
          )}
        </>
      )}
    </div>
  );
}

// ══════════════════════════════════════════════════════════
// AnnDatePicker — اختيار تاريخ الإعلان (هجري أم القرى / ميلادي)
// يسمح بأي تاريخ حتى لو كان سابقًا. يحفظ:
//   dateG : التاريخ الميلادي بصيغة yyyy-mm-dd
//   date  : النص المعروض "هجري — ميلادي"
// ══════════════════════════════════════════════════════════
const ANN_HIJRI_MONTHS = ["محرم","صفر","ربيع الأول","ربيع الآخر","جمادى الأولى","جمادى الآخرة","رجب","شعبان","رمضان","شوال","ذو القعدة","ذو الحجة"];
const _annHijriFmt = new Intl.DateTimeFormat("en-u-ca-islamic-umalqura", { day:"numeric", month:"numeric", year:"numeric", timeZone:"UTC" });
function annGToHijri(iso) {
  const d = new Date(iso + "T12:00:00Z");
  const p = {}; _annHijriFmt.formatToParts(d).forEach(x => { p[x.type] = x.value; });
  return { y: parseInt(p.year), m: parseInt(p.month), d: parseInt(p.day) };
}
function annHijriToG(hy, hm, hd) {
  // تقدير أولي ثم بحث دقيق حول التقدير
  const approx = Date.UTC(622, 6, 16) + ((hy - 1) * 354.367 + (hm - 1) * 29.5306 + (hd - 1)) * 86400000;
  for (let off = -30; off <= 30; off++) {
    const iso = new Date(approx + off * 86400000).toISOString().slice(0, 10);
    const h = annGToHijri(iso);
    if (h.y === hy && h.m === hm && h.d === hd) return iso;
  }
  return null; // اليوم غير موجود (مثل ٣٠ في شهر من ٢٩ يومًا)
}
function annDateLabel(iso) {
  const d = new Date(iso + "T12:00:00Z");
  const h = new Intl.DateTimeFormat("ar-SA-u-ca-islamic-umalqura-nu-arab", { day:"numeric", month:"long", year:"numeric", timeZone:"UTC" }).format(d).replace(/\s*هـ$/, "");
  const g = new Intl.DateTimeFormat("ar-SA-u-ca-gregory-nu-arab", { day:"numeric", month:"long", year:"numeric", timeZone:"UTC" }).format(d);
  const w = new Intl.DateTimeFormat("ar-SA", { weekday:"long", timeZone:"UTC" }).format(d);
  return `${w} ${h} هـ — ${g} م`;
}
function annTodayISO() {
  const n = new Date();
  return `${n.getFullYear()}-${String(n.getMonth()+1).padStart(2,"0")}-${String(n.getDate()).padStart(2,"0")}`;
}
const ANN_AUDIENCES = [
  { v:"أولياء الأمور", icon:"👨‍👩‍👦", c:"#0f766e" },
  { v:"المعلمون",     icon:"👨‍🏫",   c:"#1d4ed8" },
  { v:"الطلاب",       icon:"🎒",     c:"#b45309" },
  { v:"الجميع",       icon:"🏫",     c:"#7c3aed" },
];
// شارة الفئة المستهدفة — تظهر أعلى الإعلان
function AnnAudience({ ann, size = "md" }) {
  if (!ann || !ann.audience) return null;
  const a = ANN_AUDIENCES.find(x => x.v === ann.audience) || { icon:"📢", c:"#0f766e", v:ann.audience };
  const big = size === "lg", small = size === "sm";
  return (
    <div style={{ display:"inline-flex", alignItems:"center", gap:6, background:a.c, color:"#fff", borderRadius:999,
      padding: big ? "7px 18px" : small ? "2px 10px" : "4px 14px", fontWeight:900,
      fontSize: big ? 16 : small ? 11 : 13, marginBottom: big ? 12 : 6, fontFamily:"'Cairo',sans-serif" }}>
      <span>{a.icon}</span><span>موجّه إلى: {a.v}</span>
    </div>
  );
}
// سطر اليوم والتاريخ — يظهر تحت عنوان الإعلان
function AnnDateLine({ ann, size = "md", dark = false }) {
  if (!ann || !ann.date) return null;
  const big = size === "lg", small = size === "sm";
  return (
    <div style={{ display:"flex", alignItems:"center", gap:6, flexWrap:"wrap", fontWeight:800,
      fontSize: big ? 18 : small ? 11.5 : 14, color: dark ? "#e2e8f0" : "#0f766e",
      marginTop: small ? 3 : 6, marginBottom: big ? 12 : 8, lineHeight:1.6, fontFamily:"'Cairo',sans-serif" }}>
      <span>📅</span><span>{ann.date}</span>
    </div>
  );
}
function AnnDatePicker({ ann, setAnn }) {
  const [mode, setMode] = React.useState("hijri");
  const [err, setErr] = React.useState("");
  const iso = ann.dateG || "";
  const h = iso ? annGToHijri(iso) : annGToHijri(annTodayISO());
  const apply = (newIso) => { setErr(""); setAnn(p => ({ ...p, dateG: newIso, date: annDateLabel(newIso) })); };
  const setHijri = (y, m, d) => {
    const g = annHijriToG(y, m, d);
    if (!g) { setErr(`لا يوجد يوم ${d} في شهر ${ANN_HIJRI_MONTHS[m-1]} ${y}هـ`); return; }
    apply(g);
  };
  const box = { padding:"7px 8px", borderRadius:8, border:"1.5px solid #e2e8f0", fontSize:12, fontFamily:"'Cairo',sans-serif", outline:"none", background:"#fff" };
  const tab = (on) => ({ padding:"5px 14px", borderRadius:20, border:"none", cursor:"pointer", fontWeight:700, fontSize:12, fontFamily:"'Cairo',sans-serif", background: on ? "#0d9488" : "#f1f5f9", color: on ? "#fff" : "#475569" });
  const years = []; for (let y = 1420; y <= 1470; y++) years.push(y);
  return (
    <div dir="rtl" style={{ background:"#f8fafc", border:"1.5px solid #e2e8f0", borderRadius:12, padding:10, marginBottom:10 }}>
      <div style={{ display:"flex", alignItems:"center", gap:8, flexWrap:"wrap", marginBottom:8 }}>
        <span style={{ fontWeight:800, fontSize:12, color:"#0d3b6e" }}>🎯 الفئة المستهدفة:</span>
        <select value={ann.audience || ""} onChange={e => setAnn(p => ({ ...p, audience: e.target.value }))}
          style={{ ...box, fontWeight:700, minWidth:150 }}>
          <option value="">— اختر —</option>
          {ANN_AUDIENCES.map(a => <option key={a.v} value={a.v}>{a.icon} {a.v}</option>)}
        </select>
      </div>
      <div style={{ display:"flex", alignItems:"center", gap:8, flexWrap:"wrap", marginBottom:8 }}>
        <span style={{ fontWeight:800, fontSize:12, color:"#0d3b6e" }}>📅 تاريخ الإعلان:</span>
        <button type="button" style={tab(mode==="hijri")} onClick={()=>setMode("hijri")}>هجري</button>
        <button type="button" style={tab(mode==="greg")} onClick={()=>setMode("greg")}>ميلادي</button>
        <button type="button" style={{ ...tab(false), background:"#fff", border:"1.5px solid #e2e8f0" }} onClick={()=>apply(annTodayISO())}>اليوم</button>
      </div>
      {mode === "greg" ? (
        <input type="date" value={iso} onChange={e => e.target.value && apply(e.target.value)} style={{ ...box, width:"100%" }} />
      ) : (
        <div style={{ display:"grid", gridTemplateColumns:"70px 1fr 90px", gap:6 }}>
          <select value={h.d} onChange={e => setHijri(h.y, h.m, +e.target.value)} style={box}>
            {Array.from({length:30},(_,i)=>i+1).map(d => <option key={d} value={d}>{d}</option>)}
          </select>
          <select value={h.m} onChange={e => setHijri(h.y, +e.target.value, Math.min(h.d, 29))} style={box}>
            {ANN_HIJRI_MONTHS.map((n,i) => <option key={i} value={i+1}>{n}</option>)}
          </select>
          <select value={h.y} onChange={e => setHijri(+e.target.value, h.m, Math.min(h.d, 29))} style={box}>
            {years.map(y => <option key={y} value={y}>{y}</option>)}
          </select>
        </div>
      )}
      {err && <div style={{ color:"#dc2626", fontSize:11, marginTop:6, fontWeight:700 }}>{err}</div>}
      <div style={{ fontSize:12, color:"#0f766e", marginTop:8, fontWeight:700 }}>
        {iso ? annDateLabel(iso) : (ann.date ? `التاريخ الحالي: ${ann.date}` : "لم يُحدد — سيُستخدم تاريخ اليوم")}
      </div>
    </div>
  );
}

// ══════════════════════════════════════════════════════════
// تخزين الإعلانات: كل إعلان في عقدة مستقلة  school/school-ann-items/{id}
// (سابقاً كانت كل الإعلانات تُرفع دفعة واحدة، فتفشل عند وجود صور كبيرة ولا تصل للأجهزة الأخرى)
// ══════════════════════════════════════════════════════════
const ANN_NODE = "school-ann-items";
const ANN_META = "school-ann-meta";
let annLoadFailed = false; // {id:{at}} — يُعرف منه ما تغيّر فيُحمَّل فقط (بدل تحميل كل الإعلانات بصورها كل مرة)
const idbKV = {
  db: null,
  open() { if (!this.db) this.db = new Promise((res, rej) => { try { const r = indexedDB.open("pam-cache", 1); r.onupgradeneeded = () => r.result.createObjectStore("kv"); r.onsuccess = () => res(r.result); r.onerror = () => rej(r.error); } catch (e) { rej(e); } }); return this.db; },
  async get(k) { try { const db = await this.open(); return await new Promise(res => { const q = db.transaction("kv").objectStore("kv").get(k); q.onsuccess = () => res(q.result); q.onerror = () => res(undefined); }); } catch { return undefined; } },
  async set(k, v) { try { const db = await this.open(); await new Promise(res => { const t = db.transaction("kv", "readwrite"); t.objectStore("kv").put(v, k); t.oncomplete = res; t.onerror = res; }); } catch {} },
};
async function annPut(id, value) {
  const ok = await dbFirebasePut(`${ANN_NODE}/${id}`, value);
  const mv = { at: Date.now() };
  if (!ok) { try { dbQueue.add(`${ANN_NODE}/${id}`, value); dbQueue.add(`${ANN_META}/${id}`, mv); } catch {} }
  else { const ok2 = await dbFirebasePut(`${ANN_META}/${id}`, mv); if (!ok2) { try { dbQueue.add(`${ANN_META}/${id}`, mv); } catch {} } }
  return ok;
}
async function annDelete(id) {
  try { fetch(`${FIREBASE_URL}/school/${ANN_META}/${id}.json`, { method: "DELETE" }).catch(() => {}); const r = await fetch(`${FIREBASE_URL}/school/${ANN_NODE}/${id}.json`, { method: "DELETE" }); return r.ok; } catch { return false; }
}
async function annBuildMeta(arr) {
  const now = Date.now(); const m = {}; (arr || []).forEach(a => { if (a && a.id != null) m[String(a.id)] = { at: now }; });
  if (!Object.keys(m).length) return;
  await dbFirebasePut(ANN_META, m);
  await idbKV.set("ann-cache", { items: Object.fromEntries(arr.filter(a => a && a.id != null).map(a => [String(a.id), a])), at: m });
}
// تحميل الإعلانات: يُنزَّل فقط الجديد أو المعدَّل منذ آخر زيارة (مخزَّن على الجهاز)
async function annLoadAll() { return (await annLoadAllRaw()).filter(a => a && !annIsSample(a)); }
async function annLoadAllRaw() {
  let meta; try { const r = await fetch(`${FIREBASE_URL}/school/${ANN_META}.json`); meta = await r.json(); } catch { meta = undefined; }
  const c = (await idbKV.get("ann-cache")) || { items: {}, at: {} };
  if (meta === undefined) return Object.values(c.items || {});
  if (!meta || typeof meta !== "object") {
    let items = null; try { const r = await fetch(`${FIREBASE_URL}/school/${ANN_NODE}.json`); items = await r.json(); } catch {}
    const arr = items && typeof items === "object" ? Object.values(items).filter(x => x && x.id != null) : [];
    await annBuildMeta(arr); return arr;
  }
  try { const r = await fetch(`${FIREBASE_URL}/school/${ANN_NODE}.json?shallow=true`); const keys = await r.json(); if (keys && typeof keys === "object") { const now = Date.now(); const fix = {}; Object.keys(keys).forEach(id => { if (!meta[id]) { meta[id] = { at: now }; fix[`${ANN_META}/${id}`] = { at: now }; } }); if (Object.keys(fix).length) fbPatch(fix); } } catch {}
  const items = { ...(c.items || {}) }, at = { ...(c.at || {}) }; let ch = false;
  Object.keys(items).forEach(id => { if (!meta[id]) { delete items[id]; delete at[id]; ch = true; } });
  const need = Object.keys(meta).filter(id => !items[id] || !at[id] || at[id].at !== (meta[id] && meta[id].at));
  await Promise.all(need.map(async id => { try { const r = await fetch(`${FIREBASE_URL}/school/${ANN_NODE}/${id}.json`); const v = await r.json(); if (v && typeof v === "object") { items[id] = v; at[id] = meta[id]; } else { delete items[id]; } ch = true; } catch {} }));
  if (ch) await idbKV.set("ann-cache", { items, at });
  return Object.values(items);
}
async function annFetchOne(id) {
  try {
    const r = await fetch(`${FIREBASE_URL}/school/${ANN_NODE}/${id}.json`);
    const d = await r.json();
    if (d && typeof d === "object") return d;
  } catch {}
  try {
    const r = await fetch(`${FIREBASE_URL}/school/school-announcements.json`);
    const d = await r.json();
    const arr = Array.isArray(d) ? d : (d && typeof d === "object" ? Object.values(d) : []);
    return arr.find(a => a && String(a.id) === String(id)) || null;
  } catch { return null; }
}
// ══════════ الأنشطة: كل نشاط في عقدة مستقلة school/school-act-items/{id} ══════════
// (سابقاً: كل الأنشطة بصورها في عقدة واحدة — تفشل الكتابة مع الصور وقد تستبدل بيانات الخادم بنسخة ناقصة)
const ACT_NODE = "school-act-items", ACT_MIG = "school-act-migrated";
async function fetchJ(path, ms = 30000) { const c = new AbortController(); const t = setTimeout(() => c.abort(), ms); try { const r = await fetch(`${FIREBASE_URL}/school/${path}.json`, { signal: c.signal }); if (!r.ok) throw new Error("HTTP " + r.status); return await r.json(); } finally { clearTimeout(t); } }
const actArr = v => (Array.isArray(v) ? v : v && typeof v === "object" ? Object.values(v) : []).filter(a => a && a.id != null);
const actSort = L => L.sort((a, b) => (Number(b.id) || 0) - (Number(a.id) || 0));
// يُرجع {ok, list} — ok=false عند تعذّر الوصول للخادم (لا يُكتب شيء ولا تُستخدم بيانات افتراضية)
async function actLoad() {
  let items, mig;
  try { [items, mig] = await Promise.all([fetchJ(ACT_NODE, 40000), fetchJ(ACT_MIG, 15000)]); } catch { try { [items, mig] = await Promise.all([fetchJ(ACT_NODE, 60000), fetchJ(ACT_MIG, 20000)]); } catch { const c = await idbKV.get("act-cache"); return { ok: false, list: actSort(actArr(c)) }; } }
  const byId = new Map(actArr(items).map(a => [String(a.id), a]));
  if (!mig) { // ترحيل لمرة واحدة من العقدة القديمة + أي نسخة محلية لم تُرفع
    let leg = null; try { leg = await fetchJ("school-activities", 60000); } catch { const c = await idbKV.get("act-cache"); return { ok: false, list: actSort([...byId.values(), ...actArr(c).filter(a => !byId.has(String(a.id)))]) }; }
    const local = []; try { local.push(...actArr(JSON.parse(localStorage.getItem(DB_CACHE_PREFIX + "school-activities") || "null"))); } catch {} try { const q = JSON.parse(localStorage.getItem(DB_QUEUE_KEY) || "[]"); q.filter(i => i && i.key === "school-activities").forEach(i => local.push(...actArr(i.value))); } catch {}
    const src = [...actArr(leg), ...local]; const o = {};
    src.forEach(a => { if (!byId.has(String(a.id))) { byId.set(String(a.id), a); o[`${ACT_NODE}/${a.id}`] = a; } });
    if (!actArr(leg).length && !byId.size) DEFAULT_ACTIVITIES.forEach(a => { byId.set(String(a.id), a); o[`${ACT_NODE}/${a.id}`] = a; });
    o[ACT_MIG] = Date.now(); try { await fbPatch(o); } catch {}
    try { const q = JSON.parse(localStorage.getItem(DB_QUEUE_KEY) || "[]").filter(i => i && i.key !== "school-activities"); localStorage.setItem(DB_QUEUE_KEY, JSON.stringify(q)); } catch {}
  }
  const list = actSort([...byId.values()]); idbKV.set("act-cache", list); return { ok: true, list };
}
async function actPut(a) { const content = await annCompressHtml(a.description || ""); const v = { ...a, description: content }; if (JSON.stringify(v).length > 9000000) return "big"; const ok = await dbFirebasePut(`${ACT_NODE}/${a.id}`, v); if (!ok) { try { dbQueue.add(`${ACT_NODE}/${a.id}`, v); } catch {} } return ok; }
async function actDel(id) { try { const r = await fetch(`${FIREBASE_URL}/school/${ACT_NODE}/${id}.json`, { method: "DELETE" }); return r.ok; } catch { return false; } }

// تصغير الصور المضمّنة داخل نص الإعلان (base64) قبل الحفظ
async function annCompressHtml(html) {
  if (!html || typeof html !== "string" || !html.includes("data:image")) return html;
  const re = /data:image\/(png|jpe?g|webp|gif|bmp);base64,[A-Za-z0-9+/=]+/g;
  const found = [...new Set(html.match(re) || [])].filter(u => u.length > 200000 && !u.startsWith("data:image/gif"));
  let out = html;
  for (const src of found) {
    try {
      const img = await new Promise((res, rej) => { const im = new Image(); im.onload = () => res(im); im.onerror = rej; im.src = src; });
      const scale = Math.min(1, 1600 / Math.max(img.naturalWidth, img.naturalHeight));
      const cv = document.createElement("canvas");
      cv.width = Math.round(img.naturalWidth * scale); cv.height = Math.round(img.naturalHeight * scale);
      const cx = cv.getContext("2d"); cx.fillStyle = "#fff"; cx.fillRect(0, 0, cv.width, cv.height); cx.drawImage(img, 0, 0, cv.width, cv.height);
      const small = cv.toDataURL("image/jpeg", 0.82);
      if (small.length < src.length) out = out.split(src).join(small);
    } catch {}
  }
  return out;
}

// ── تهيئة نص الإعلان للعرض على الجوال: تصغير الخطوط الكبيرة، إزالة العروض الثابتة والمسافات الزائدة، ومنع انكسار التواريخ
function annFit(html) {
  if (!html || typeof html !== "string") return html || "";
  try {
    const doc = new DOMParser().parseFromString(`<div id="annr">${html}</div>`, "text/html");
    const root = doc.getElementById("annr"); if (!root) return html;
    root.querySelectorAll("*").forEach(el => {
      const st = el.style; const tag = el.tagName;
      if (st) {
        const fs = st.fontSize;
        if (fs) { let px = parseFloat(fs); if (/pt$/.test(fs)) px *= 1.333; else if (/r?em$/.test(fs)) px *= 16; else if (/%$/.test(fs)) px = px / 100 * 16; else if (!/px$/.test(fs)) px = 0; if (px > 0) { const cap = /^H[1-3]$/.test(tag) ? 26 : 21; st.fontSize = Math.round(Math.min(Math.max(px, 13), cap)) + "px"; } else st.fontSize = ""; }
        if (st.lineHeight) { const v = parseFloat(st.lineHeight); if (/px$/.test(st.lineHeight) ? v > 42 : v > 2.2) st.lineHeight = "1.9"; }
        ["width", "minWidth", "maxWidth", "textIndent", "letterSpacing", "wordSpacing", "whiteSpace", "position", "left", "right", "top", "bottom", "float"].forEach(k => { if (!(tag === "IMG" && k === "maxWidth")) st[k] = ""; });
        if (tag !== "IMG") st.height = "";
        ["marginLeft", "marginRight", "paddingLeft", "paddingRight"].forEach(k => { if (parseFloat(st[k]) > 18) st[k] = ""; });
      }
      if (tag === "IMG") { el.removeAttribute("width"); el.removeAttribute("height"); el.style.maxWidth = "100%"; el.style.height = "auto"; }
      else el.removeAttribute("width");
      if (tag === "FONT" && +el.getAttribute("size") > 4) el.setAttribute("size", "4");
      if ((el.getAttribute("dir") || "").toLowerCase() === "ltr" && /[؀-ۿ]/.test(el.textContent || "")) el.setAttribute("dir", "auto");
    });
    const tw = doc.createTreeWalker(root, 4); const nodes = []; while (tw.nextNode()) nodes.push(tw.currentNode);
    const re = /(\d{1,4}\s*[\/\-.]\s*\d{1,2}\s*[\/\-.]\s*\d{1,4}\s*(?:هـ|ه|م)?)/;
    nodes.forEach(t => {
      let v = t.nodeValue.replace(/ {2,}/g, " ").replace(/[ \t]{3,}/g, " ");
      if (re.test(v)) { const frag = doc.createDocumentFragment(); v.split(re).forEach((part, i) => { if (i % 2) { const sp = doc.createElement("span"); sp.className = "ann-nw"; sp.textContent = part; frag.appendChild(sp); } else if (part) frag.appendChild(doc.createTextNode(part)); }); t.parentNode.replaceChild(frag, t); }
      else if (v !== t.nodeValue) t.nodeValue = v;
    });
    annLinkify(doc, root);
    return root.innerHTML;
  } catch { return html; }
}
// 🔗 الروابط في الإعلانات والأنشطة: أي رابط مكتوب يصبح قابلاً للضغط ويفتح في نافذة جديدة
const ANN_URL_RE = /((?:https?:\/\/|www\.)[^\s<>"'«»]+[^\s<>"'«».,،؛:!?)\]])/i;
function annLinkify(doc, root) {
  root.querySelectorAll("a[href]").forEach(a => { const h = a.getAttribute("href") || ""; if (/^\s*javascript:/i.test(h)) { a.removeAttribute("href"); return; } a.setAttribute("target", "_blank"); a.setAttribute("rel", "noopener noreferrer"); a.classList.add("ann-link"); });
  const tw = doc.createTreeWalker(root, 4); const L = []; while (tw.nextNode()) { const t = tw.currentNode; if (!(t.parentElement && t.parentElement.closest("a")) && ANN_URL_RE.test(t.nodeValue)) L.push(t); }
  L.forEach(t => { const frag = doc.createDocumentFragment(); t.nodeValue.split(ANN_URL_RE).forEach((part, i) => { if (i % 2) { const a = doc.createElement("a"); const href = /^www\./i.test(part) ? "https://" + part : part; a.setAttribute("href", href); a.setAttribute("target", "_blank"); a.setAttribute("rel", "noopener noreferrer"); a.setAttribute("dir", "ltr"); a.className = "ann-link"; let label = part.replace(/^https?:\/\//i, "").replace(/^www\./i, ""); try { label = decodeURI(label); } catch {} a.textContent = "🔗 " + (label.length > 48 ? label.slice(0, 45) + "…" : label); a.title = href; frag.appendChild(a); } else if (part) frag.appendChild(doc.createTextNode(part)); }); t.parentNode.replaceChild(frag, t); });
}
