function SingleAnnouncementPage({ announcements, siteFont, annId }) {
  const cIcons = { "تعاميم": "📜", "إعلانات": "📢", "تدريب": "🎓", "اجتماعات": "🤝" };
  const priorityColor = { "عاجل": "bg-red-100 text-red-700", "مهم": "bg-amber-100 text-amber-700", "عادي": "bg-gray-100 text-gray-600" };
  const fromList = (announcements || []).find(a => a && String(a.id) === String(annId));
  const [fetched, setFetched] = React.useState(null);
  const [tries, setTries] = React.useState(fromList ? 2 : 0);
  React.useEffect(() => {
    if (fromList || tries >= 2) return;
    let alive = true;
    (async () => { const d = await annFetchOne(annId); if (!alive) return; if (d) setFetched(d); else setTimeout(() => alive && setTries(t => t + 1), 1500); if (d) setTries(2); })();
    return () => { alive = false; };
  }, [annId, tries, fromList]);
  const ann = fromList || fetched;
  if (!ann && tries < 2) return (
    <div dir="rtl" className="min-h-screen flex items-center justify-center" style={{ fontFamily: siteFont, background: "linear-gradient(135deg, #0d9488 0%, #065f46 50%, #064e3b 100%)" }}>
      <div className="bg-white rounded-3xl p-8 text-center shadow-2xl"><div className="text-4xl mb-2 animate-pulse">📢</div><div className="font-bold text-gray-500">جاري تحميل الإعلان…</div></div>
    </div>
  );
  return (
    <div dir="rtl" className="min-h-screen"
      style={{ fontFamily: siteFont, background: "linear-gradient(135deg, #0d9488 0%, #065f46 50%, #064e3b 100%)" }}>
      {/* شريط العنوان */}
      <div className="flex items-center justify-between px-6 py-4 bg-black bg-opacity-20">
        <p className="font-black text-white text-sm">🏫 مدرسة الأمير عبدالمجيد المتوسطة الأولى</p>
        <button onClick={() => { window.location.hash = ""; window.location.reload(); }}
          className="px-4 py-1.5 rounded-xl bg-white bg-opacity-20 text-white font-bold text-sm hover:bg-opacity-30 transition-all">
          ← الرئيسية
        </button>
      </div>
      {/* المحتوى */}
      <div className="w-full px-2 py-4">
        {!ann ? (
          <div className={cx.empty}>
            <div className="text-4xl mb-2">📭</div>
            <p className="font-bold">الإعلان غير موجود</p>
          </div>
        ) : (
          <div className={"bg-white rounded-2xl shadow-2xl overflow-hidden border-r-8 " + (ann.pinned ? "border-amber-400" : "border-teal-400")}
            style={{ backgroundColor: ann.bgColor || "#ffffff" }}>
            {/* رأس الإعلان */}
            <div className="px-8 pt-8 pb-4">
              <AnnAudience ann={ann} size="lg" />
              <div className="flex items-start gap-3 mb-3 flex-wrap">
                <span className="text-3xl">{cIcons[ann.category] || "📢"}</span>
                <h1 className={"font-black flex-1 leading-snug " + (ann.titleSize||"text-2xl")} style={{color: ann.titleColor||"#1f2937", textAlign: ann.titleAlign||"right"}}>{ann.title}</h1>
                {ann.pinned && <span className="text-xs bg-amber-100 text-amber-700 px-2 py-1 rounded-full font-bold">📌 مثبت</span>}
              </div>
              <AnnDateLine ann={ann} size="lg" />
              <div className="flex gap-2 flex-wrap">
                <span className={"text-xs px-3 py-1 rounded-full font-bold " + (priorityColor[ann.priority] || "bg-gray-100 text-gray-600")}>{ann.priority}</span>
                <span className="text-xs px-3 py-1 rounded-full font-bold bg-teal-50 text-teal-700">{ann.category}</span>
              </div>
            </div>
            {/* فاصل */}
            <div className="border-t border-gray-100 mx-8"></div>
            {/* محتوى الإعلان */}
            <style>{ANN_HTML_CSS}</style>
            <div className="px-4 sm:px-8 py-6 text-gray-700 leading-loose text-base annhtml"
              dangerouslySetInnerHTML={{ __html: annFit(ann.content) }}>
            </div>
            {/* عداد الزوار + التعليقات */}
            <div className="px-8 pb-8">
              <div className="flex justify-center mb-4">
                <AnnViews id={ann.id} />
              </div>
              <PublicComments itemKey={`ann-${ann.id}`} itemTitle={ann.title} />
            </div>
          </div>
        )}
      </div>
    </div>
  );
}

// ===== دوال مساعدة مشتركة =====
// قراءة ملف كـ base64 أو نص
function readFileAsync(file, mode = "base64") {
  return new Promise((res, rej) => {
    const r = new FileReader();
    r.onload = e => res(mode === "base64" ? e.target.result.split(",")[1] : e.target.result);
    r.onerror = () => rej(new Error("فشل قراءة الملف"));
    if (mode === "text") r.readAsText(file);
    else if (mode === "buffer") r.readAsArrayBuffer(file);
    else r.readAsDataURL(file);
  });
}
// تحميل مكتبة XLSX مرة واحدة
let _xlsxLoaded = false;
function loadXLSX() {
  return new Promise((res) => {
    if (window.XLSX) { _xlsxLoaded = true; return res(window.XLSX); }
    if (_xlsxLoaded && window.XLSX) return res(window.XLSX);
    const s = document.createElement("script");
    s.src = "https://cdnjs.cloudflare.com/ajax/libs/xlsx/0.18.5/xlsx.full.min.js";
    s.onload = () => { _xlsxLoaded = true; res(window.XLSX); };
    document.head.appendChild(s);
  });
}

// ================================================================
// تحميل ملف Excel نموذجي للطلاب (3 مراحل)
// ================================================================
async function downloadStudentsTemplate() {
  await loadXLSX();
  const wb = window.XLSX.utils.book_new();
  const levels = [
    { name:"أول متوسط", sections:["أ","ب","ج","د","هـ"] },
    { name:"ثاني متوسط", sections:["أ","ب","ج","د","هـ"] },
    { name:"ثالث متوسط", sections:["أ","ب","ج","د","هـ"] },
  ];
  levels.forEach(lvl => {
    const header = [["اسم الطالب","رقم الهوية الوطنية","الفصل","ملاحظات"]];
    const examples = lvl.sections.slice(0,3).flatMap(s =>
      [1,2,3].map(n => [`اسم طالب ${n}`,`10XXXXXXXXX`,`الصف ${lvl.name} / ${s}`,``])
    );
    const ws = window.XLSX.utils.aoa_to_sheet([...header, ...examples]);
    ws["!cols"] = [{wch:30},{wch:18},{wch:22},{wch:20}];
    window.XLSX.utils.book_append_sheet(wb, ws, lvl.name);
  });
  window.XLSX.writeFile(wb, "نموذج_استيراد_الطلاب.xlsx");
}
// فتح نافذة طباعة
function printWindow(html) {
  const w = window.open("", "_blank");
  if (!w) return;
  w.document.write(html);
  w.document.close();
}


