// نموذج تقييم أسبوعي جديد
function newEval() {
  return {
    id: Date.now() + Math.random() * 1000 | 0,
    dateH: "",
    day: "الأحد",
    subject: "",
    level: "",
    categories: {},
    attachments: [], // صور أو PDF مرفقة
  };
}

// ضغط وتحويل الصورة إلى base64
// للمرفقات — تصغير وضغط (توفير مساحة Firebase)
async function compressImageToBase64(file, maxW = 900) {
  return new Promise((resolve) => {
    if (file.type === "application/pdf") {
      const reader = new FileReader();
      reader.onload = (e) => resolve({ type: file.type, name: file.name, data: e.target.result });
      reader.readAsDataURL(file);
      return;
    }
    const img = new Image();
    const url = URL.createObjectURL(file);
    img.onload = () => {
      const scale = Math.min(1, maxW / img.width);
      const canvas = document.createElement("canvas");
      canvas.width = img.width * scale;
      canvas.height = img.height * scale;
      canvas.getContext("2d").drawImage(img, 0, 0, canvas.width, canvas.height);
      URL.revokeObjectURL(url);
      resolve({ type: file.type, name: file.name, data: canvas.toDataURL("image/jpeg", 0.75) });
    };
    img.src = url;
  });
}

// لصور ملف الطالب — الحجم الأصلي الكامل بدون أي تصغير
async function readImageFullRes(file) {
  return new Promise((resolve) => {
    const reader = new FileReader();
    reader.onload = (e) => resolve({
      type: file.type,
      name: file.name,
      data: e.target.result,            // base64 كامل بدون ضغط
      originalSize: file.size,
    });
    reader.readAsDataURL(file);
  });
}

// ─── Lightbox (مكبّر الصور) ─── يُعرض فوق كل شيء
function ImageLightbox({ src, name, onClose }) {
  useEffect(() => {
    const close = (e) => { if (e.key === "Escape") onClose(); };
    window.addEventListener("keydown", close);
    return () => window.removeEventListener("keydown", close);
  }, []);
  return (
    <div
      onClick={onClose}
      style={{
        position:"fixed", inset:0, background:"rgba(0,0,0,0.92)",
        zIndex:99999, display:"flex", flexDirection:"column",
        alignItems:"center", justifyContent:"center", padding:16, cursor:"zoom-out",
      }}>
      <img
        src={src} alt={name}
        onClick={e => e.stopPropagation()}
        style={{
          maxWidth:"95vw", maxHeight:"88vh",
          objectFit:"contain", borderRadius:12,
          boxShadow:"0 8px 60px rgba(0,0,0,0.7)",
          cursor:"default",
        }}
      />
      <div style={{color:"#cbd5e1",marginTop:10,fontSize:13,fontWeight:700}}>{name}</div>
      <button
        onClick={onClose}
        style={{
          position:"fixed", top:16, left:16,
          background:"rgba(255,255,255,0.15)", border:"none",
          borderRadius:"50%", width:40, height:40,
          color:"#fff", fontSize:22, cursor:"pointer",
          display:"flex", alignItems:"center", justifyContent:"center",
        }}>✕</button>
    </div>
  );
}

// مكوّن التقييم الأسبوعي للطالب
function StudentEvalCard({ student, onUpdate, onDelete, onSendNote, messages }) {
  const [expanded, setExpanded] = useState(false);
  const [addingEval, setAddingEval] = useState(false);
  const [draft, setDraft] = useState(newEval());
  const [openCats, setOpenCats] = useState({});
  const [showNoteForm, setShowNoteForm] = useState(false);
  const [noteText, setNoteText] = useState("");
  const [noteSent, setNoteSent] = useState(false);
  const [showShareLink, setShowShareLink] = useState(false);
  const [linkCopied, setLinkCopied] = useState(false);
  const [noteAttachments, setNoteAttachments] = useState([]);
  const [lightbox, setLightbox] = useState(null); // {src, name}

  const siteUrl = (typeof window !== "undefined" ? window.location.origin : "https://school-website1-sigma.vercel.app");
  const shareUrl = student.nationalId ? `${siteUrl}/#parent-${student.nationalId}` : "";

  const copyShareLink = () => {
    if (!shareUrl) return;
    navigator.clipboard.writeText(shareUrl).then(() => {
      setLinkCopied(true);
      setTimeout(() => setLinkCopied(false), 2500);
    });
  };

  const sendShareViaWhatsApp = () => {
    if (!student.parentPhone) { alert("أضف رقم جوال ولي الأمر أولاً"); return; }
    const phone = student.parentPhone.trim().replace(/^0/, "966");
    const msg = encodeURIComponent(
      `السلام عليكم ورحمة الله وبركاته
ولي أمر الطالب / ${student.name}

يمكنك متابعة مستوى ابنك والاطلاع على ملاحظات المعلم ومراسلته مباشرةً عبر الرابط التالي:
${shareUrl}

مع تحيات إدارة مدرسة الأمير عبدالمجيد المتوسطة الأولى`
    );
    window.open("https://wa.me/" + phone + "?text=" + msg, "_blank");
  };

  const sendShareViaSMS = () => {
    if (!student.parentPhone) { alert("أضف رقم جوال ولي الأمر أولاً"); return; }
    const phone = student.parentPhone.trim();
    const msg = encodeURIComponent(
      `مدرسة الأمير عبدالمجيد - رابط متابعة الطالب ${student.name}: ${shareUrl}`
    );
    window.open("sms:" + phone + "?body=" + msg);
  };

  const handleNoteAttachment = async (e) => {
    const file = e.target.files[0];
    if (!file) return;
    if (file.size > 5 * 1024 * 1024) { alert("حجم الملف كبير جداً (الحد الأقصى 5 ميجا)"); return; }
    const att = await compressImageToBase64(file);
    setNoteAttachments(p => [...p, att]);
    e.target.value = "";
  };

  const handleEvalAttachment = async (e) => {
    const file = e.target.files[0];
    if (!file) return;
    if (file.size > 5 * 1024 * 1024) { alert("حجم الملف كبير جداً (الحد الأقصى 5 ميجا)"); return; }
    const att = await compressImageToBase64(file);
    setDraft(p => ({ ...p, attachments: [...(p.attachments || []), att] }));
    e.target.value = "";
  };

  const handleSendNote = async (sendMethod) => {
    if (!noteText.trim()) { alert("اكتب الملاحظة أولاً"); return; }
    if (onSendNote) await onSendNote(student, noteText.trim(), noteAttachments);
    setNoteText(""); setNoteAttachments([]); setShowNoteForm(false);
    setNoteSent(true); setTimeout(() => setNoteSent(false), 4000);
    const parentLink = shareUrl || (typeof window !== "undefined" ? window.location.origin : "https://school-website1-sigma.vercel.app");
    const waMsg = encodeURIComponent(
      `السلام عليكم ورحمة الله وبركاته
ولي أمر الطالب / ${student.name}

نُفيدكم بوجود ملاحظة من معلم ابنكم.
يمكن الاطلاع عليها والرد مباشرةً عبر الرابط:
${parentLink}

مع تحيات إدارة مدرسة الأمير عبدالمجيد المتوسطة الأولى`
    );
    if (sendMethod === "sms") {
      if (student.parentPhone) {
        window.open("sms:" + student.parentPhone.trim() + "?body=" + encodeURIComponent(
          `مدرسة الأمير عبدالمجيد - يوجد ملاحظة من المعلم للطالب ${student.name}. الرابط: ${parentLink}`
        ));
      }
    } else if (student.parentPhone && student.parentPhone.trim()) {
      const phone = student.parentPhone.trim().replace(/^0/, "966");
      window.open("https://wa.me/" + phone + "?text=" + waMsg, "_blank");
    }
  };

  const openWhatsApp = () => {
    if (!student.parentPhone || !student.parentPhone.trim()) {
      alert("أضف رقم جوال ولي الأمر أولاً في بيانات الطالب");
      return;
    }
    const phone = student.parentPhone.trim().replace(/^0/, "966");
    const link = shareUrl || (typeof window !== "undefined" ? window.location.origin : "https://school-website1-sigma.vercel.app");
    const msg = encodeURIComponent(
      `السلام عليكم ورحمة الله وبركاته
ولي أمر الطالب / ${student.name}

يمكنك متابعة مستوى ابنك والتواصل مع المعلم من خلال الرابط المباشر:
${link}

مع تحيات إدارة مدرسة الأمير عبدالمجيد المتوسطة الأولى`
    );
    window.open("https://wa.me/" + phone + "?text=" + msg, "_blank");
  };

  const evals = student.evals || [];
  const lastEval = evals[evals.length - 1];
  const lastLevel = lastEval ? EVAL_LEVELS.find(l => l.value === lastEval.level) : null;

  // طباعة ملف الطالب الكامل
  const handleStudentPrint = (stu, notes) => {
    const evs = stu.evals || [];
    const photos = stu.photos || [];
    const pdfs = stu.pdfs || [];

    // ملخص آخر مستوى لكل مادة
    const subjRows = SUBJECTS.map(subj => {
      const last = [...evs].reverse().find(e=>e.subject===subj.key);
      if(!last) return "";
      const lv = EVAL_LEVELS.find(l=>l.value===last.level)||EVAL_LEVELS[0];
      return `<div class="subj-cell" style="border-color:${subj.color}44">
        <div class="subj-head" style="background:${subj.bg};color:${subj.color}">${subj.icon} ${subj.label}</div>
        <div class="subj-lv" style="background:${lv.bg||'#f5f5f5'};color:${lv.color||'#333'}">${lv.label||"—"}</div>
        <div class="subj-cnt">${evs.filter(e=>e.subject===subj.key).length} تقييم</div>
      </div>`;
    }).join("");

    // سجل التقييمات
    const evalRows = [...evs].reverse().map(ev=>{
      const lv = EVAL_LEVELS.find(l=>l.value===ev.level)||EVAL_LEVELS[0];
      const subj = SUBJECTS.find(s=>s.key===ev.subject);
      const cats = EVAL_CATEGORIES.map(cat=>{
        const d=ev.categories?.[cat.key];
        if(!d?.text&&!d?.face) return "";
        return `<div class="cat-row" style="background:${d.color||'#f9fafb'}">
          <span class="cat-icon">${cat.icon}</span>
          <span class="cat-label">${cat.label}:</span>
          <span class="cat-text">${d.text||""}</span>
          ${d.face?`<span class="cat-face">${d.face}</span>`:""}
        </div>`;
      }).join("");
      const attHtml = (ev.attachments||[]).map(att=>
        att.type&&att.type.startsWith("image")
          ? `<img src="${att.data}" class="ev-img"/>`
          : `<div class="pdf-link">📄 ${att.name}</div>`
      ).join("");
      return `<div class="eval-card" style="border-right:5px solid ${lv.bg||'#e5e7eb'}">
        <div class="eval-head" style="background:${lv.bg||'#f5f5f5'};color:${lv.color||'#333'}">
          ${subj?`<span class="subj-badge" style="background:${subj.bg};color:${subj.color};border:1px solid ${subj.color}44">${subj.icon} ${subj.label}</span>`:""}
          <strong>${lv.label||"—"}</strong>
          <span class="ev-date">${ev.day||""} ${ev.dateH||""}</span>
        </div>
        ${cats}${attHtml}
      </div>`;
    }).join("");

    // ملاحظات المعلم وردود ولي الأمر
    const notesHtml = notes.length===0
      ? `<div class="no-notes">لا توجد ملاحظات</div>`
      : [...notes].reverse().map(note=>{
          const atts = (note.attachments||[]).map(att=>
            att.type&&att.type.startsWith("image")
              ? `<img src="${att.data}" class="note-img"/>`
              : `<div class="pdf-link">📄 ${att.name}</div>`
          ).join("");
          const replyHtml = note.reply
            ? `<div class="parent-reply">
                <div class="reply-label">💬 ردّ ولي الأمر — ${note.repliedAt}</div>
                <div class="reply-text">${note.reply}</div>
              </div>`
            : `<div class="no-reply">⏳ لم يردّ ولي الأمر بعد</div>`;
          return `<div class="note-card ${note.reply?'replied':''}">
            <div class="note-meta">
              <span class="note-sender">👨‍🏫 المعلم</span>
              <span class="note-date">${note.date} · ${note.time||""}</span>
            </div>
            <div class="note-text">${note.text}</div>
            ${atts}
            ${replyHtml}
          </div>`;
        }).join("");

    // الصور
    const photosHtml = photos.length===0 ? ""
      : `<div class="section-title">🖼️ صور الطالب</div>
         <div class="photos-grid">${photos.map(p=>`<img src="${p.data}" class="student-photo" alt="${p.name}"/>`).join("")}</div>`;

    // ملفات PDF
    const pdfsHtml = pdfs.length===0 ? ""
      : `<div class="section-title">📄 المستندات</div>
         <div class="pdfs-list">${pdfs.map(p=>`<div class="pdf-item">📄 ${p.name}</div>`).join("")}</div>`;

    const lastLv = lastLevel ? lastLevel : {label:"—",bg:"#f5f5f5",color:"#333"};

    const w = window.open("","_blank");
    w.document.write(`<!DOCTYPE html><html dir="rtl"><head><meta charset="utf-8">
    <title>ملف الطالب — ${stu.name}</title>
    <style>
      @import url('https://fonts.googleapis.com/css2?family=Tajawal:wght@400;700;800;900&display=swap');
      *{margin:0;padding:0;box-sizing:border-box}
      body{font-family:'Tajawal',Arial,sans-serif;direction:rtl;background:#fff;color:#1e293b;font-size:14px;padding:24px}
      /* ─── رأس الصفحة ─── */
      .header{background:linear-gradient(135deg,#1B3A6B,#2E6DA4);color:#fff;border-radius:16px;padding:20px 24px;margin-bottom:20px;display:flex;align-items:center;gap:16px}
      .header-icon{font-size:48px}
      .header-school{font-size:14px;opacity:.85;margin-bottom:4px}
      .header-name{font-size:24px;font-weight:900;margin-bottom:4px}
      .header-meta{font-size:13px;opacity:.8}
      .level-badge{display:inline-block;padding:6px 18px;border-radius:999px;font-weight:900;font-size:16px;margin-top:8px}
      /* ─── بطاقة المعلومات ─── */
      .info-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:12px;margin-bottom:20px}
      .info-box{background:#f8fafc;border:1px solid #e2e8f0;border-radius:12px;padding:12px;text-align:center}
      .info-label{font-size:11px;color:#64748b;font-weight:700;margin-bottom:4px}
      .info-val{font-size:15px;font-weight:900;color:#1e293b}
      /* ─── عنوان قسم ─── */
      .section-title{font-size:16px;font-weight:900;color:#1B3A6B;margin:20px 0 10px;padding:8px 14px;background:#f0f7ff;border-radius:10px;border-right:4px solid #1B3A6B}
      /* ─── شبكة المواد ─── */
      .subj-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:10px;margin-bottom:4px}
      .subj-cell{border-radius:12px;overflow:hidden;border:2px solid #e5e7eb}
      .subj-head{padding:6px 8px;font-size:12px;font-weight:900}
      .subj-lv{padding:8px;text-align:center;font-weight:900;font-size:13px}
      .subj-cnt{text-align:center;font-size:11px;color:#6b7280;padding:4px}
      /* ─── التقييمات ─── */
      .eval-card{margin-bottom:14px;border-radius:12px;overflow:hidden;border:1px solid #e2e8f0}
      .eval-head{padding:10px 14px;display:flex;align-items:center;gap:8px;font-size:14px;font-weight:700;flex-wrap:wrap}
      .subj-badge{padding:3px 10px;border-radius:999px;font-size:12px;font-weight:900}
      .ev-date{font-size:12px;margin-right:auto;opacity:.75}
      .cat-row{display:flex;align-items:center;gap:6px;padding:8px 14px;border-top:1px solid rgba(0,0,0,.05);font-size:13px}
      .cat-icon{font-size:16px;flex-shrink:0}
      .cat-label{font-weight:900;color:#374151}
      .cat-text{color:#4b5563;flex:1}
      .cat-face{font-size:18px}
      .ev-img{max-width:100%;max-height:320px;object-fit:contain;display:block;margin:10px 14px;border-radius:10px;border:2px solid #e5e7eb;box-shadow:0 2px 8px rgba(0,0,0,.08)}
      /* ─── ملاحظات المعلم ─── */
      .note-card{margin-bottom:16px;border-radius:14px;overflow:hidden;border:2px solid #fde68a}
      .note-card.replied{border-color:#93c5fd}
      .note-meta{background:#fef3c7;padding:10px 14px;display:flex;align-items:center;justify-content:space-between}
      .note-sender{font-weight:900;font-size:14px;color:#92400e}
      .note-date{font-size:12px;color:#a16207}
      .note-text{padding:14px;font-size:15px;line-height:1.7;color:#1e293b;background:#fffbeb}
      .note-img{max-width:100%;max-height:360px;object-fit:contain;display:block;margin:12px 14px;border-radius:12px;border:2px solid #fde68a;box-shadow:0 2px 10px rgba(0,0,0,.08)}
      .parent-reply{background:linear-gradient(135deg,#eff6ff,#dbeafe);border-top:2px solid #93c5fd;padding:14px}
      .reply-label{font-size:13px;font-weight:900;color:#1d4ed8;margin-bottom:6px}
      .reply-text{font-size:15px;color:#1e3a8a;line-height:1.7;font-weight:700}
      .no-reply{background:#f9fafb;border-top:1px dashed #d1d5db;padding:10px 14px;font-size:12px;color:#9ca3af;font-style:italic}
      .no-notes{color:#9ca3af;font-size:14px;padding:16px;text-align:center}
      /* ─── الصور ─── */
      .photos-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(260px,1fr));gap:16px;margin-bottom:12px}
      .student-photo{width:100%;max-height:340px;object-fit:contain;border-radius:14px;border:3px solid #e2e8f0;box-shadow:0 4px 16px rgba(0,0,0,.12);background:#f8fafc}
      /* ─── PDF ─── */
      .pdfs-list{display:flex;flex-direction:column;gap:8px;margin-bottom:8px}
      .pdf-item,.pdf-link{background:#fef2f2;border:1px solid #fecaca;border-radius:10px;padding:10px 14px;font-size:13px;font-weight:700;color:#991b1b}
      /* ─── توقيعات ─── */
      .sigs{display:flex;gap:40px;margin-top:28px;padding-top:20px;border-top:2px dashed #e5e7eb;font-size:13px}
      .sig{text-align:center;flex:1}
      .sig-label{color:#6b7280;font-weight:700;margin-bottom:24px}
      .sig-line{border-top:1px solid #374151;padding-top:6px;font-weight:900}
      .footer{text-align:center;margin-top:20px;font-size:11px;color:#9ca3af}
      @page{size:A4;margin:1.5cm}
      @media print{body{padding:0}}
    </style>
    </head><body>

    <!-- رأس الصفحة -->
    <div class="header">
      <div class="header-icon">👨‍🎓</div>
      <div>
        <div class="header-school">مدرسة الأمير عبدالمجيد المتوسطة الأولى — إدارة تعليم جدة</div>
        <div class="header-name">${stu.name || "—"}</div>
        <div class="header-meta">رقم الهوية: ${stu.nationalId||"—"} · جوال ولي الأمر: ${stu.parentPhone||"—"}</div>
        ${lastLv&&lastLv.value?`<span class="level-badge" style="background:${lastLv.bg};color:${lastLv.color}">آخر مستوى: ${lastLv.label}</span>`:""}
      </div>
    </div>

    ${photosHtml}
    ${pdfsHtml}

    <!-- ملخص المواد -->
    ${subjRows?`<div class="section-title">📊 آخر مستوى لكل مادة</div><div class="subj-grid">${subjRows}</div>`:""}

    <!-- التقييمات -->
    ${evs.length?`<div class="section-title">📋 سجل التقييمات الأسبوعية (${evs.length} تقييم)</div>${evalRows}`:""}

    <!-- ملاحظات المعلم وردود ولي الأمر -->
    <div class="section-title">📨 ملاحظات المعلم وردود ولي الأمر (${notes.length})</div>
    ${notesHtml}

    <!-- التوقيعات -->
    <div class="sigs">
      <div class="sig"><div class="sig-label">توقيع المعلم</div><div class="sig-line">__________________</div></div>
      <div class="sig"><div class="sig-label">توقيع مدير المدرسة</div><div class="sig-line">فازع القرني</div></div>
      <div class="sig"><div class="sig-label">توقيع ولي الأمر</div><div class="sig-line">__________________</div></div>
      <div class="sig"><div class="sig-label">التاريخ</div><div class="sig-line">__________________</div></div>
    </div>
    <div class="footer">بوابة مدرسة الأمير عبدالمجيد الإلكترونية © ١٤٤٧هـ</div>

    <script>window.onload=()=>{ window.print(); }</script>
    </body></html>`);
    w.document.close();
  };

  const toggleCat = (key) => setOpenCats(p => ({ ...p, [key]: !p[key] }));

  const updateDraftCat = (key, field, val) => {
    setDraft(p => ({ ...p, categories: { ...p.categories, [key]: { ...(p.categories[key] || {}), [field]: val } } }));
  };

  const saveEval = () => {
    if (!draft.subject) { alert("اختر المادة الدراسية أولاً"); return; }
    if (!draft.level) { alert("اختر المستوى أولاً"); return; }
    const updated = { ...student, evals: [...evals, { ...draft, id: Date.now() }] };
    onUpdate(updated);
    setAddingEval(false);
    setDraft(newEval());
    setOpenCats({});
  };

  const deleteEval = (eid) => {
    if (!confirm("حذف هذا التقييم؟")) return;
    onUpdate({ ...student, evals: evals.filter(e => e.id !== eid) });
  };

  return (
    <>
    <div className="bg-white rounded-2xl border border-gray-100 shadow-sm overflow-hidden mb-3">
      {/* رأس الطالب */}
      <div className="flex items-center justify-between px-4 py-3 cursor-pointer hover:bg-gray-50 transition-all"
        style={{ borderRight: `4px solid ${lastLevel ? lastLevel.bg : "#e5e7eb"}` }}
        onClick={() => setExpanded(p => !p)}>
        <div className="flex items-center gap-3">
          <div className="w-9 h-9 rounded-full flex items-center justify-center font-black text-sm"
            style={{ background: "#1B3A6B", color: "#fff" }}>{student.num}</div>
          <div>
            <div className="font-black text-gray-800">{student.name || <span className="text-gray-300 font-normal">اسم الطالب</span>}</div>
            {student.nationalId && <div className="text-xs text-gray-400">{student.nationalId}</div>}
          </div>
        </div>
        <div className="flex items-center gap-2">
          {lastLevel && lastLevel.value && (
            <span className="px-3 py-1 rounded-full text-xs font-black" style={{ background: lastLevel.bg, color: lastLevel.color }}>
              {lastLevel.label}
            </span>
          )}
          {/* مؤشر المواد — عدد المواد المقيّمة */}
          {(() => {
            const subjSet = new Set(evals.filter(e=>e.subject).map(e=>e.subject));
            if (subjSet.size === 0) return null;
            return (
              <span className="text-xs bg-purple-100 text-purple-700 px-2 py-1 rounded-full font-bold">
                📚 {subjSet.size} مادة
              </span>
            );
          })()}
          <span className="text-xs text-gray-400 bg-gray-100 px-2 py-1 rounded-full font-bold">{evals.length} تقييم</span>
          {/* أيقونة جوال ولي الأمر */}
          <span
            onClick={e => { e.stopPropagation(); onUpdate({ ...student, _showPhone: !student._showPhone }); }}
            title={student.parentPhone ? "جوال ولي الأمر: " + student.parentPhone : "أضف جوال ولي الأمر"}
            className="cursor-pointer text-base select-none"
            style={{ filter: student.parentPhone ? "none" : "grayscale(1) opacity(0.4)" }}>
            📱
          </span>
          {/* زر الرابط المباشر */}
          {student.nationalId && (
            <button onClick={e => { e.stopPropagation(); setShowShareLink(p => !p); setExpanded(true); }}
              title="رابط مخصص لولي الأمر"
              className={"text-sm px-2 py-1 rounded-lg font-black transition-all " + (showShareLink ? "bg-blue-600 text-white" : "bg-blue-50 text-blue-600 hover:bg-blue-100")}>
              🔗
            </button>
          )}
          <button onClick={e => { e.stopPropagation(); onDelete(student.id); }}
            className="text-red-300 hover:text-red-500 text-sm px-1 font-bold">✕</button>
          <span className="text-gray-400 text-lg">{expanded ? "▲" : "▼"}</span>
        </div>
      </div>

      {/* لوحة الرابط المباشر */}
      {showShareLink && student.nationalId && (
        <div className="border-t border-blue-100 bg-gradient-to-l from-blue-50 to-indigo-50 px-4 py-3 space-y-2">
          <div className="flex items-center gap-2 mb-1">
            <span className="text-base">🔗</span>
            <span className="font-black text-blue-800 text-sm">رابط ولي الأمر المخصص — {student.name}</span>
          </div>
          {/* عرض الرابط */}
          <div className="flex items-center gap-2 bg-white border border-blue-200 rounded-xl px-3 py-2">
            <span className="flex-1 text-xs text-blue-700 font-mono truncate">{shareUrl}</span>
            <button onClick={copyShareLink}
              className={"text-xs font-black px-3 py-1.5 rounded-lg transition-all " + (linkCopied ? "bg-green-500 text-white" : "bg-blue-600 text-white hover:bg-blue-700")}>
              {linkCopied ? "✅ تم النسخ" : "📋 نسخ"}
            </button>
          </div>
          <p className="text-xs text-blue-600 opacity-75">📌 يفتح هذا الرابط مباشرةً على بيانات الطالب بدون الحاجة لإدخال رقم الهوية</p>
          {/* أزرار الإرسال */}
          <div className="flex gap-2 flex-wrap">
            <button onClick={sendShareViaWhatsApp}
              className="flex-1 flex items-center justify-center gap-1.5 py-2.5 rounded-xl bg-green-500 hover:bg-green-600 text-white text-xs font-black transition-all">
              📲 إرسال عبر واتساب
            </button>
            <button onClick={sendShareViaSMS}
              className="flex-1 flex items-center justify-center gap-1.5 py-2.5 rounded-xl bg-indigo-500 hover:bg-indigo-600 text-white text-xs font-black transition-all">
              📱 إرسال رسالة نصية
            </button>
          </div>
          {!student.parentPhone && (
            <p className="text-xs text-amber-600 font-bold text-center">⚠️ أضف رقم جوال ولي الأمر أدناه لتفعيل الإرسال</p>
          )}
        </div>
      )}

      {/* تفاصيل الطالب */}
      {expanded && (
        <div className="border-t border-gray-100">
          {/* تعديل الاسم والهوية */}
          <div className="flex gap-2 px-4 pt-3">
            <input type="text" value={student.name} placeholder="اسم الطالب"
              onChange={e => onUpdate({ ...student, name: e.target.value })}
              className="flex-1 px-3 py-2 rounded-xl border-2 border-gray-200 text-sm font-medium focus:border-blue-400 focus:outline-none"
              style={{ fontFamily: "inherit", color: "#1B3A6B" }} />
            <input type="text" value={student.nationalId || ""} placeholder="رقم الهوية"
              onChange={e => onUpdate({ ...student, nationalId: e.target.value })}
              className="w-36 px-3 py-2 rounded-xl border-2 border-gray-200 text-sm text-center focus:border-blue-400 focus:outline-none"
              style={{ fontFamily: "inherit" }} />
          </div>
          {/* جوال ولي الأمر — يظهر دائماً */}
          <div className="flex items-center gap-2 px-4 pt-2 pb-1">
            <span className="text-base">📱</span>
            <input type="tel" value={student.parentPhone || ""}
              placeholder="جوال ولي الأمر (05xxxxxxxx)"
              onChange={e => onUpdate({ ...student, parentPhone: e.target.value })}
              className="flex-1 px-3 py-2 rounded-xl border-2 text-sm text-center focus:outline-none"
              style={{ fontFamily: "inherit",
                borderColor: student.parentPhone ? "#22c55e" : "#e5e7eb",
                background: student.parentPhone ? "#f0fdf4" : "#fff",
                color: student.parentPhone ? "#166534" : "#374151",
                fontWeight: student.parentPhone ? "700" : "400"
              }} />
            {student.parentPhone && (
              <button onClick={() => openWhatsApp()}
                className="shrink-0 bg-green-500 hover:bg-green-600 text-white text-xs font-black px-3 py-2 rounded-xl flex items-center gap-1 transition-all">
                📲 واتساب
              </button>
            )}
          </div>
          {/* ملخص مستوى كل مادة */}
          {evals.some(e=>e.subject) && (
            <div className="px-4 pt-3 pb-2">
              <div className="text-xs font-black text-gray-500 mb-2">📊 آخر مستوى لكل مادة</div>
              <div className="grid grid-cols-3 gap-1.5">
                {SUBJECTS.map(subj => {
                  const subjEvals = [...evals].reverse().filter(e=>e.subject===subj.key);
                  const last = subjEvals[0];
                  if (!last) return null;
                  const lv = EVAL_LEVELS.find(l=>l.value===last.level) || EVAL_LEVELS[0];
                  return (
                    <div key={subj.key} className="rounded-xl overflow-hidden border"
                      style={{borderColor:subj.color+"44"}}>
                      <div className="flex items-center gap-1 px-2 py-1" style={{background:subj.bg}}>
                        <span className="text-xs">{subj.icon}</span>
                        <span className="text-xs font-black truncate" style={{color:subj.color}}>{subj.label}</span>
                      </div>
                      <div className="px-2 py-1 text-center font-black text-xs" style={{background:lv.bg||"#f5f5f5",color:lv.color||"#333"}}>
                        {lv.label || "—"}
                      </div>
                      <div className="text-center text-xs text-gray-400 pb-1">{subjEvals.length} تقييم</div>
                    </div>
                  );
                })}
              </div>
            </div>
          )}

          {/* قائمة التقييمات السابقة */}
          {evals.length > 0 && (
            <div className="px-4 pt-3 space-y-3">
              {evals.map(ev => {
                const lv = EVAL_LEVELS.find(l => l.value === ev.level) || EVAL_LEVELS[0];
                return (
                  <div key={ev.id} className="rounded-xl border border-gray-100 overflow-hidden">
                    {/* رأس التقييم */}
                    <div className="flex items-center justify-between px-3 py-2" style={{ background: lv.bg || "#f5f5f5" }}>
                      <div className="flex items-center gap-2 flex-wrap">
                        {ev.subject && (() => {
                          const subj = SUBJECTS.find(s=>s.key===ev.subject);
                          return subj ? (
                            <span className="flex items-center gap-1 px-2 py-0.5 rounded-full text-xs font-black"
                              style={{background:subj.bg, color:subj.color, border:`1px solid ${subj.color}44`}}>
                              {subj.icon} {subj.label}
                            </span>
                          ) : null;
                        })()}
                        <span className="font-black text-sm" style={{ color: lv.color }}>{lv.label}</span>
                        {ev.dateH && <span className="text-xs opacity-70" style={{ color: lv.color }}>📅 {ev.day} {ev.dateH}</span>}
                      </div>
                      <button onClick={() => deleteEval(ev.id)} className="text-xs opacity-50 hover:opacity-100 px-2 py-0.5 rounded-lg hover:bg-red-100 hover:text-red-600 transition-all">🗑️</button>
                    </div>
                    {/* ملاحظات الفئات */}
                    {EVAL_CATEGORIES.map(cat => {
                      const catData = ev.categories?.[cat.key];
                      if (!catData?.text && !catData?.face) return null;
                      return (
                        <div key={cat.key} className="flex items-start gap-2 px-3 py-2 border-t border-gray-50"
                          style={{ background: catData.color || "#fff" }}>
                          <span className="text-base flex-shrink-0">{cat.icon}</span>
                          <div className="flex-1">
                            <span className="text-xs font-black text-gray-600">{cat.label}:</span>
                            <span className="text-xs text-gray-700 mr-1">{catData.text}</span>
                          </div>
                          {catData.face && <span className="text-base">{catData.face}</span>}
                        </div>
                      );
                    })}
                    {/* مرفقات التقييم */}
                    {ev.attachments && ev.attachments.length > 0 && (
                      <div className="px-3 py-2 border-t border-gray-50 space-y-2">
                        <div className="text-xs font-black text-gray-500 mb-1">📎 مرفقات</div>
                        {ev.attachments.map((att, i) => (
                          att.type && att.type.startsWith("image") ? (
                            <img key={i} src={att.data} alt={att.name} className="max-w-full rounded-xl border border-gray-200" style={{maxHeight:180,objectFit:"contain"}} />
                          ) : (
                            <a key={i} href={att.data} download={att.name} target="_blank" rel="noreferrer"
                              className="flex items-center gap-2 bg-red-50 border border-red-200 rounded-xl px-3 py-2 text-xs font-bold text-red-700 hover:bg-red-100 transition-all">
                              📄 {att.name}
                            </a>
                          )
                        ))}
                      </div>
                    )}
                  </div>
                );
              })}
            </div>
          )}

          {/* نموذج تقييم جديد */}
          {addingEval ? (
            <div className="m-4 bg-blue-50 rounded-2xl p-4 border-2 border-blue-200">
              <div className="font-black text-blue-800 mb-3 text-sm">➕ تقييم أسبوعي جديد</div>

              {/* اختيار المادة */}
              <div className="mb-3">
                <label className={cx.label}>📚 المادة الدراسية *</label>
                <div className="grid grid-cols-3 gap-1.5">
                  {SUBJECTS.map(subj => (
                    <button key={subj.key} onClick={() => setDraft(p => ({ ...p, subject: subj.key }))}
                      className={"flex items-center gap-1.5 px-3 py-2 rounded-xl text-xs font-black border-2 transition-all " +
                        (draft.subject === subj.key ? "border-current shadow-sm" : "border-gray-200 bg-white hover:border-gray-300")}
                      style={draft.subject === subj.key ? {background:subj.bg, color:subj.color, borderColor:subj.color} : {color:"#6b7280"}}>
                      <span className="text-sm">{subj.icon}</span>
                      <span className="truncate">{subj.label}</span>
                    </button>
                  ))}
                </div>
                {!draft.subject && <div className="text-xs text-red-500 font-bold mt-1">اختر المادة أولاً</div>}
              </div>

              {/* التاريخ واليوم والمستوى */}
              <div className="grid grid-cols-3 gap-2 mb-3">
                <div>
                  <label className={cx.label}>اليوم</label>
                  <select value={draft.day} onChange={e => setDraft(p => ({ ...p, day: e.target.value }))}
                    className="w-full px-2 py-2 rounded-xl border-2 border-gray-200 text-sm focus:outline-none focus:border-blue-400">
                    {HIJRI_DAYS.map(d => <option key={d} value={d}>{d}</option>)}
                  </select>
                </div>
                <div>
                  <label className={cx.label}>التاريخ الهجري</label>
                  <input type="text" placeholder="مثال: 15/09/1447" value={draft.dateH}
                    onChange={e => setDraft(p => ({ ...p, dateH: e.target.value }))}
                    className="w-full px-2 py-2 rounded-xl border-2 border-gray-200 text-sm text-center focus:outline-none focus:border-blue-400" />
                </div>
                <div>
                  <label className={cx.label}>المستوى *</label>
                  <select value={draft.level} onChange={e => setDraft(p => ({ ...p, level: e.target.value }))}
                    className="w-full px-2 py-2 rounded-xl border-2 border-gray-200 text-sm font-bold focus:outline-none focus:border-blue-400"
                    style={draft.level ? { background: EVAL_LEVELS.find(l=>l.value===draft.level)?.bg, color: EVAL_LEVELS.find(l=>l.value===draft.level)?.color } : {}}>
                    {EVAL_LEVELS.map(l => <option key={l.value} value={l.value}>{l.label}</option>)}
                  </select>
                </div>
              </div>

              {/* فئات الملاحظات */}
              <div className="space-y-2 mb-3">
                {EVAL_CATEGORIES.map(cat => {
                  const catData = draft.categories[cat.key] || {};
                  const isOpen = openCats[cat.key];
                  return (
                    <div key={cat.key} className="bg-white rounded-xl border border-gray-200 overflow-hidden">
                      <button className="w-full flex items-center justify-between px-3 py-2.5 hover:bg-gray-50 transition-all"
                        onClick={() => toggleCat(cat.key)}>
                        <div className="flex items-center gap-2">
                          <span className="text-lg">{cat.icon}</span>
                          <span className="font-black text-gray-700 text-sm">{cat.label}</span>
                          {catData.face && <span className="text-base">{catData.face}</span>}
                          {catData.text && <span className="text-xs text-gray-400 truncate max-w-32">{catData.text}</span>}
                        </div>
                        <span className="text-gray-400 text-xs">{isOpen ? "▲" : "▼"}</span>
                      </button>
                      {isOpen && (
                        <div className="px-3 pb-3 space-y-2 border-t border-gray-100"
                          style={{ background: catData.color || "#fff" }}>
                          {/* الوجه التعبيري */}
                          <div className="pt-2">
                            <div className="text-xs font-bold text-gray-500 mb-1.5">الوجه التعبيري:</div>
                            <div className="flex gap-1.5 flex-wrap">
                              {EVAL_FACES.map(f => (
                                <button key={f} onClick={() => updateDraftCat(cat.key, "face", f === catData.face ? "" : f)}
                                  className="w-8 h-8 rounded-lg text-base flex items-center justify-center transition-all"
                                  style={{ background: catData.face === f ? "#dbeafe" : "#f3f4f6", border: catData.face === f ? "2px solid #3b82f6" : "2px solid transparent" }}>
                                  {f || "✕"}
                                </button>
                              ))}
                            </div>
                          </div>
                          {/* لون الخلفية */}
                          <div>
                            <div className="text-xs font-bold text-gray-500 mb-1.5">لون الخلفية:</div>
                            <div className="flex gap-1.5 flex-wrap">
                              {EVAL_COLORS.map(c => (
                                <button key={c.value} onClick={() => updateDraftCat(cat.key, "color", c.value)}
                                  className="px-2.5 py-1 rounded-lg text-xs font-bold border-2 transition-all"
                                  style={{ background: c.value || "#f3f4f6", borderColor: catData.color === c.value ? "#3b82f6" : "transparent" }}>
                                  {c.label}
                                </button>
                              ))}
                            </div>
                          </div>
                          {/* الملاحظة */}
                          <div>
                            <div className="text-xs font-bold text-gray-500 mb-1.5">الملاحظة:</div>
                            <textarea value={catData.text || ""} rows={2}
                              onChange={e => updateDraftCat(cat.key, "text", e.target.value)}
                              placeholder={`اكتب ملاحظة عن ${cat.label}...`}
                              className="w-full px-3 py-2 rounded-xl border-2 border-gray-200 text-sm focus:outline-none focus:border-blue-400 resize-none"
                              style={{ fontFamily: "inherit" }} />
                          </div>
                        </div>
                      )}
                    </div>
                  );
                })}
              </div>

              {/* المرفقات */}
              <div className="mb-3">
                <label className={cx.label}>📎 إضافة صورة أو ملف PDF (اختياري)</label>
                <label className="flex items-center gap-2 w-full py-2.5 px-4 rounded-xl border-2 border-dashed border-purple-300 text-purple-700 text-xs font-black cursor-pointer hover:bg-purple-50 transition-all">
                  <span>📁 اختر صورة أو PDF</span>
                  <input type="file" accept="image/*,.pdf" className="hidden" onChange={handleEvalAttachment} />
                </label>
                {(draft.attachments || []).length > 0 && (
                  <div className="mt-2 space-y-2">
                    {draft.attachments.map((att, i) => (
                      <div key={i} className="flex items-center gap-2 bg-purple-50 border border-purple-200 rounded-xl px-3 py-2">
                        {att.type && att.type.startsWith("image") ? (
                          <img src={att.data} alt={att.name} className="h-12 w-16 object-cover rounded-lg" />
                        ) : (
                          <span className="text-2xl">📄</span>
                        )}
                        <span className="flex-1 text-xs text-purple-800 font-bold truncate">{att.name}</span>
                        <button onClick={() => setDraft(p => ({ ...p, attachments: p.attachments.filter((_, j) => j !== i) }))}
                          className="text-red-400 hover:text-red-600 text-xs font-black px-1">✕</button>
                      </div>
                    ))}
                  </div>
                )}
              </div>

              <div className="flex gap-2">
                <button onClick={saveEval} className="flex-1 py-2.5 rounded-xl bg-blue-600 text-white text-sm font-black hover:bg-blue-700">💾 حفظ التقييم</button>
                <button onClick={() => { setAddingEval(false); setDraft(newEval()); setOpenCats({}); }}
                  className="px-4 py-2.5 rounded-xl bg-gray-100 text-gray-600 text-sm font-bold hover:bg-gray-200">إلغاء</button>
              </div>
            </div>
          ) : (
            <div className="px-4 py-3">
              <button onClick={() => setAddingEval(true)}
                className="w-full py-2.5 rounded-xl border-2 border-dashed border-blue-300 text-blue-600 text-sm font-black hover:border-blue-500 hover:bg-blue-50 transition-all">
                ➕ إضافة تقييم أسبوعي
              </button>
            </div>
          )}

          {/* ===== ملف الطالب: 3 صور + 2 PDF ===== */}
          <div className="px-4 pt-3 pb-2">
            <div className="flex items-center justify-between mb-2">
              <div className="text-xs font-black text-gray-600">🖼️ ملف الطالب — الصور والمستندات</div>
              <button onClick={() => handleStudentPrint(student, (messages||[]).filter(m=>m.type==="teacher_note"&&m.studentId===student.nationalId))}
                className="flex items-center gap-1 text-xs font-black px-3 py-1.5 rounded-xl bg-gray-800 text-white hover:bg-gray-900 transition-all">
                🖨️ طباعة ملف الطالب
              </button>
            </div>

            {/* الصور — حد أقصى 3 */}
            <div className="mb-2">
              <div className="text-xs font-bold text-gray-500 mb-1.5">📷 الصور (حد أقصى 3)</div>
              <div className="flex gap-2 flex-wrap">
                {(student.photos||[]).map((ph,i)=>(
                  <div key={i} className="relative group">
                    <img src={ph.data} alt={ph.name}
                      onClick={()=>setLightbox({src:ph.data,name:ph.name})}
                      className="w-24 h-24 object-cover rounded-xl border-2 border-gray-200 shadow-sm cursor-zoom-in hover:border-blue-400 hover:shadow-md transition-all" />
                    <button onClick={()=>onUpdate({...student,photos:(student.photos||[]).filter((_,j)=>j!==i)})}
                      className="absolute -top-1.5 -right-1.5 w-5 h-5 rounded-full bg-red-500 text-white text-xs font-black flex items-center justify-center opacity-0 group-hover:opacity-100 transition-all shadow">✕</button>
                    <div className="text-xs text-gray-400 text-center mt-0.5 truncate max-w-24">{ph.name}</div>
                  </div>
                ))}
                {(student.photos||[]).length < 3 && (
                  <label className="w-24 h-24 rounded-xl border-2 border-dashed border-purple-300 flex flex-col items-center justify-center cursor-pointer hover:bg-purple-50 transition-all text-purple-500">
                    <span className="text-2xl">+</span>
                    <span className="text-xs font-bold mt-0.5">صورة</span>
                    <input type="file" accept="image/*" className="hidden" onChange={async e=>{
                      const f=e.target.files[0]; if(!f) return;
                      if(f.size>6*1024*1024){alert("الصورة كبيرة جداً، الحد 6 ميجا");return;}
                      const att=await readImageFullRes(f); // الحجم الأصلي كاملاً
                      onUpdate({...student,photos:[...(student.photos||[]),att]});
                      e.target.value="";
                    }}/>
                  </label>
                )}
              </div>
            </div>

            {/* ملفات PDF — حد أقصى 2 */}
            <div>
              <div className="text-xs font-bold text-gray-500 mb-1.5">📄 ملفات PDF (حد أقصى 2)</div>
              <div className="space-y-1.5">
                {(student.pdfs||[]).map((pdf,i)=>(
                  <div key={i} className="flex items-center gap-2 bg-red-50 border border-red-200 rounded-xl px-3 py-2">
                    <span className="text-xl">📄</span>
                    <span className="flex-1 text-xs font-bold text-red-800 truncate">{pdf.name}</span>
                    <a href={pdf.data} download={pdf.name} target="_blank" rel="noreferrer"
                      className="text-xs bg-red-100 hover:bg-red-200 text-red-700 px-2 py-1 rounded-lg font-bold transition-all">⬇️</a>
                    <button onClick={()=>onUpdate({...student,pdfs:(student.pdfs||[]).filter((_,j)=>j!==i)})}
                      className="text-red-400 hover:text-red-600 text-xs font-black px-1">✕</button>
                  </div>
                ))}
                {(student.pdfs||[]).length < 2 && (
                  <label className="flex items-center gap-2 py-2 px-3 rounded-xl border-2 border-dashed border-red-300 text-red-600 text-xs font-black cursor-pointer hover:bg-red-50 transition-all">
                    <span>📎 إضافة PDF</span>
                    <input type="file" accept=".pdf,application/pdf" className="hidden" onChange={async e=>{
                      const f=e.target.files[0]; if(!f) return;
                      if(f.size>8*1024*1024){alert("الملف كبير جداً، الحد 8 ميجا");return;}
                      const att=await compressImageToBase64(f);
                      onUpdate({...student,pdfs:[...(student.pdfs||[]),att]});
                      e.target.value="";
                    }}/>
                  </label>
                )}
              </div>
            </div>
          </div>

          {/* ===== ملاحظات ولي الأمر ===== */}
          {onSendNote && (() => {
            const sentNotes = (messages || []).filter(m => m.type === "teacher_note" && m.studentId === student.nationalId);
            const unread = sentNotes.filter(m => !m.reply).length;
            return (
              <div className="px-4 pb-4 space-y-2">
                {/* سجل الملاحظات السابقة */}
                {sentNotes.length > 0 && (
                  <div className="bg-white border border-amber-200 rounded-2xl overflow-hidden mb-2">
                    <div className="flex items-center justify-between px-3 py-2 bg-amber-50 border-b border-amber-100">
                      <span className="text-xs font-black text-amber-800">📨 ملاحظات مُرسلة ({sentNotes.length})</span>
                      {unread > 0 && (
                        <span className="text-xs bg-amber-500 text-white px-2 py-0.5 rounded-full font-bold animate-pulse">
                          {unread} بدون رد
                        </span>
                      )}
                    </div>
                    <div className="divide-y divide-amber-50 max-h-56 overflow-y-auto">
                      {[...sentNotes].reverse().map(note => (
                        <div key={note.id} className="px-3 py-2">
                          {/* نص الملاحظة */}
                          <div className="flex items-start justify-between gap-2 mb-1">
                            <p className="text-xs text-gray-700 flex-1">{note.text}</p>
                            <span className="text-xs text-gray-400 whitespace-nowrap">{note.date}</span>
                          </div>
                          {/* حالة القراءة والرد */}
                          {note.reply ? (
                            <div className="mt-1 bg-blue-50 border border-blue-200 rounded-xl px-2 py-1.5">
                              <div className="text-xs font-black text-blue-600 mb-0.5">💬 رد ولي الأمر — {note.repliedAt}</div>
                              <p className="text-xs text-blue-800">{note.reply}</p>
                            </div>
                          ) : (
                            <div className="flex items-center gap-2 mt-1 flex-wrap">
                              <span className="text-xs text-gray-400 bg-gray-100 px-2 py-0.5 rounded-full">⏳ لم يرد بعد</span>
                              {student.parentPhone && (
                                <button onClick={openWhatsApp}
                                  className="text-xs bg-green-500 hover:bg-green-600 text-white px-2 py-0.5 rounded-full font-bold flex items-center gap-1 transition-all">
                                  <span>📲</span> تذكير واتساب
                                </button>
                              )}
                            </div>
                          )}
                        </div>
                      ))}
                    </div>
                  </div>
                )}
                {/* تنبيه إرسال */}
                {noteSent && (
                  <div className="flex items-center gap-2 bg-green-50 border border-green-200 text-green-700 text-xs font-bold px-3 py-2 rounded-xl animate-pulse">
                    ✅ تم إرسال الملاحظة لولي الأمر بنجاح
                  </div>
                )}
                {/* نموذج إرسال */}
                {!showNoteForm ? (
                  <div className="flex gap-2">
                    <button onClick={() => setShowNoteForm(true)}
                      className="flex-1 py-2.5 rounded-xl border-2 border-dashed border-amber-400 text-amber-700 text-sm font-black hover:border-amber-500 hover:bg-amber-50 transition-all flex items-center justify-center gap-2">
                      📨 إرسال ملاحظة جديدة
                    </button>
                    <button onClick={openWhatsApp} title="إشعار واتساب مباشر"
                      className="py-2.5 px-3 rounded-xl border-2 border-dashed border-green-400 text-green-700 text-sm font-black hover:border-green-500 hover:bg-green-50 transition-all flex items-center justify-center gap-1">
                      📲 واتساب
                    </button>
                  </div>
                ) : (
                  <div className="bg-amber-50 border-2 border-amber-300 rounded-2xl p-4 space-y-3">
                    <div className="flex items-center gap-2">
                      <span className="text-lg">📨</span>
                      <span className="font-black text-amber-800 text-sm">ملاحظة لولي أمر: {student.name}</span>
                    </div>
                    {lastLevel && lastLevel.value && (
                      <div className="flex items-center gap-2 bg-white rounded-xl px-3 py-2 border border-amber-200">
                        <span className="text-xs text-gray-500">آخر مستوى:</span>
                        <span className="px-2 py-0.5 rounded-full text-xs font-black" style={{background:lastLevel.bg,color:lastLevel.color}}>{lastLevel.label}</span>
                      </div>
                    )}
                    <textarea
                      value={noteText}
                      onChange={e => setNoteText(e.target.value)}
                      rows={3}
                      placeholder="اكتب ملاحظتك لولي الأمر..."
                      className="w-full px-3 py-2.5 rounded-xl border-2 border-amber-200 focus:border-amber-400 focus:outline-none text-sm resize-none bg-white"
                      style={{fontFamily:"inherit"}}
                    />
                    {/* إضافة مرفق للملاحظة */}
                    <div>
                      <label className="flex items-center gap-2 py-2 px-3 rounded-xl border-2 border-dashed border-amber-300 text-amber-700 text-xs font-black cursor-pointer hover:bg-amber-100 transition-all">
                        <span>📎 إرفاق صورة أو PDF</span>
                        <input type="file" accept="image/*,.pdf" className="hidden" onChange={handleNoteAttachment} />
                      </label>
                      {noteAttachments.length > 0 && (
                        <div className="mt-2 space-y-1.5">
                          {noteAttachments.map((att, i) => (
                            <div key={i} className="flex items-center gap-2 bg-white border border-amber-200 rounded-xl px-3 py-1.5">
                              {att.type && att.type.startsWith("image") ? (
                                <img src={att.data} alt={att.name} className="h-10 w-14 object-cover rounded-lg" />
                              ) : <span className="text-xl">📄</span>}
                              <span className="flex-1 text-xs font-bold text-amber-800 truncate">{att.name}</span>
                              <button onClick={() => setNoteAttachments(p => p.filter((_, j) => j !== i))}
                                className="text-red-400 hover:text-red-600 font-black text-xs">✕</button>
                            </div>
                          ))}
                        </div>
                      )}
                    </div>
                    {/* أزرار الإرسال */}
                    <div className="grid grid-cols-2 gap-2">
                      <button onClick={() => handleSendNote("whatsapp")}
                        className="py-2.5 rounded-xl bg-green-500 hover:bg-green-600 text-white text-xs font-black transition-all flex items-center justify-center gap-1">
                        📲 واتساب
                      </button>
                      <button onClick={() => handleSendNote("sms")}
                        className="py-2.5 rounded-xl bg-indigo-500 hover:bg-indigo-600 text-white text-xs font-black transition-all flex items-center justify-center gap-1">
                        📱 رسالة نصية
                      </button>
                    </div>
                    <button onClick={() => { setShowNoteForm(false); setNoteText(""); setNoteAttachments([]); }}
                      className="w-full py-2 rounded-xl bg-gray-100 text-gray-600 text-sm font-bold hover:bg-gray-200">
                      إلغاء
                    </button>
                  </div>
                )}
              </div>
            );
          })()}
        </div>
      )}
    </div>
    {/* Lightbox مكبّر الصور */}
    {lightbox && <ImageLightbox src={lightbox.src} name={lightbox.name} onClose={()=>setLightbox(null)} />}
    </>
  );
}

function ClassTable({ cls, onUpdateClass, onSave, onSendNote, messages }) {
  const [search, setSearch] = useState("");
  const [editInfo, setEditInfo] = useState(false);
  const [showImport, setShowImport] = useState(false);
  const [info, setInfo] = useState({ level: cls.level, section: cls.section, teacher: cls.teacher, semester: cls.semester });

  useEffect(() => {
    const t = setTimeout(() => onSave(cls), 800);
    return () => clearTimeout(t);
  }, [cls.students]);

  const updateName = (sid, name) => onUpdateClass({ ...cls, students: cls.students.map(s => s.id === sid ? { ...s, name } : s) });
  const updateNationalId = (sid, nationalId) => onUpdateClass({ ...cls, students: cls.students.map(s => s.id === sid ? { ...s, nationalId } : s) });
  const updateStudent = (updated) => onUpdateClass({ ...cls, students: cls.students.map(s => s.id === updated.id ? updated : s) });
  const removeStudent = (sid) => {
    if (!confirm("حذف الطالب وجميع تقييماته؟")) return;
    onUpdateClass({ ...cls, students: cls.students.filter(s => s.id !== sid).map((s, i) => ({ ...s, num: i + 1 })) });
  };
  const handleExcelImport = (importedStudents) => {
    const start = cls.students.length;
    onUpdateClass({ ...cls, students: [...cls.students, ...importedStudents.map((s, i) => ({ ...s, num: start + i + 1 }))] });
  };
  const addStudent = () => onUpdateClass({ ...cls, students: [...cls.students, newStudent(cls.students.length + 1)] });
  const addMany = (count) => {
    const start = cls.students.length;
    onUpdateClass({ ...cls, students: [...cls.students, ...Array.from({ length: count }, (_, i) => newStudent(start + i + 1))] });
  };
  const saveInfo = () => {
    const updated = { ...cls, ...info, name: `${info.level} / ${info.section}` };
    onUpdateClass(updated); onSave(updated); setEditInfo(false);
  };

  const filtered = search ? cls.students.filter(s => s.name.includes(search)) : cls.students;

  const handlePrint = () => {
    const rows = cls.students.map(s => {
      const evals = s.evals || [];
      const last = evals[evals.length - 1];
      const lv = EVAL_LEVELS.find(l => l.value === last?.level) || EVAL_LEVELS[0];
      const cats = EVAL_CATEGORIES.map(cat => {
        const d = last?.categories?.[cat.key];
        return d?.text ? `${cat.icon} ${cat.label}: ${d.text}` : null;
      }).filter(Boolean).join(" | ");
      return `<tr>
        <td>${s.num}</td>
        <td style="text-align:right;padding-right:8px">${s.name||"—"}</td>
        <td style="background:${lv.bg||'#fff'};color:${lv.color||'#333'};font-weight:700">${lv.label==="— المستوى —"?"—":lv.label}</td>
        <td style="font-size:10px;text-align:right;padding:4px 8px">${last?.dateH||""} ${last?.day||""}</td>
        <td style="font-size:9px;text-align:right;padding:4px 8px">${cats}</td>
      </tr>`;
    }).join("");
    w.document.write(`<!DOCTYPE html><html dir="rtl"><head><meta charset="utf-8">
    <title>سجل التقييم الأسبوعي — ${cls.name}</title>
    <style>*{margin:0;padding:0;box-sizing:border-box}body{font-family:'Tajawal',Arial,sans-serif;padding:20px;direction:rtl;font-size:12px}
    h1{text-align:center;color:#1B3A6B;font-size:16px;margin-bottom:4px}.sub{text-align:center;color:#666;font-size:10px;margin-bottom:12px}
    table{width:100%;border-collapse:collapse}th,td{border:1px solid #ddd;padding:6px;text-align:center}
    th{background:#1B3A6B;color:#fff}tr:nth-child(odd){background:#f4f7fb}
    .footer{text-align:center;margin-top:20px;font-size:9px;color:#999}
    @page{size:A4;margin:1.5cm}</style></head><body>
    <h1>🏫 سجل التقييم الأسبوعي — ${cls.name||cls.level+" / "+cls.section}</h1>
    <div class="sub">مدرسة الأمير عبدالمجيد المتوسطة الأولى — الفصل ${cls.semester||"—"} — ${cls.teacher||""}</div>
    <table><thead><tr><th>م</th><th>اسم الطالب</th><th>آخر مستوى</th><th>التاريخ</th><th>الملاحظات</th></tr></thead>
    <tbody>${rows}</tbody></table>
    <div style="display:flex;gap:40px;margin-top:20px;font-size:10px">
      <div>توقيع المعلم: __________________</div>
      <div>توقيع مدير المدرسة: __________________</div>
      <div>التاريخ: __________________</div>
    </div>
    <div class="footer">بوابة مدرسة الأمير عبدالمجيد الإلكترونية © ١٤٤٧هـ</div>
    </body></html>`);
  };

  return (
    <div>
      {/* بيانات الفصل */}
      <div className="bg-white rounded-2xl shadow-sm border border-blue-100 mb-4 overflow-hidden">
        <div className="flex items-center justify-between px-4 py-3" style={{ background: "#1B3A6B" }}>
          <span className="font-bold text-white text-sm">📋 بيانات الفصل والمعلم</span>
          <button onClick={() => setEditInfo(!editInfo)} className="text-xs bg-white bg-opacity-20 hover:bg-opacity-30 text-white px-3 py-1 rounded-lg font-bold">
            {editInfo ? "✕ إلغاء" : "✏️ تعديل"}
          </button>
        </div>
        {editInfo ? (
          <div className="p-4 grid grid-cols-2 gap-3 sm:grid-cols-4">
            <div><label className={cx.label}>المستوى</label>
              <select value={info.level} onChange={e => setInfo(p => ({ ...p, level: e.target.value }))} className={cx.input}>
                {LEVELS.map(l => <option key={l} value={l}>{l}</option>)}
              </select></div>
            <div><label className={cx.label}>الشعبة</label>
              <select value={info.section} onChange={e => setInfo(p => ({ ...p, section: e.target.value }))} className={cx.input}>
                {SECTIONS.map(s => <option key={s} value={s}>{s}</option>)}
              </select></div>
            <div><label className={cx.label}>اسم المعلم</label>
              <input type="text" value={info.teacher} placeholder="اكتب الاسم" onChange={e => setInfo(p => ({ ...p, teacher: e.target.value }))} className={cx.input} /></div>
            <div><label className={cx.label}>الفصل الدراسي</label>
              <select value={info.semester} onChange={e => setInfo(p => ({ ...p, semester: e.target.value }))} className={cx.input}>
                <option>الأول</option><option>الثاني</option><option>الثالث</option>
              </select></div>
            <div className="col-span-2 sm:col-span-4">
              <button onClick={saveInfo} className="bg-blue-600 text-white px-6 py-2 rounded-xl text-sm font-bold hover:bg-blue-700">💾 حفظ</button>
            </div>
          </div>
        ) : (
          <div className="flex flex-wrap gap-4 px-4 py-3 text-sm">
            <span className="text-gray-600">🎓 <b>{cls.level} / {cls.section}</b></span>
            <span className="text-gray-600">👨‍🏫 <b>{cls.teacher || "—"}</b></span>
            <span className="text-gray-600">📅 الفصل <b>{cls.semester || "—"}</b></span>
            <span className="text-gray-600">👨‍🎓 <b>{cls.students.filter(s => s.name).length}</b> طالب</span>
          </div>
        )}
      </div>

      {/* أدوات */}
      <div className="flex gap-2 mb-4 flex-wrap">
        <input type="text" placeholder="🔍 بحث عن طالب..." value={search} onChange={e => setSearch(e.target.value)}
          className="flex-1 min-w-40 px-4 py-2.5 rounded-xl border-2 border-gray-200 focus:border-blue-400 focus:outline-none text-sm bg-white" />
        <button onClick={addStudent} className="bg-blue-600 text-white px-4 py-2.5 rounded-xl text-sm font-bold hover:bg-blue-700">+ طالب</button>
        <button onClick={() => addMany(5)} className="bg-blue-100 text-blue-700 px-4 py-2.5 rounded-xl text-sm font-bold">+ 5</button>
        <button onClick={() => addMany(43)} className="bg-indigo-100 text-indigo-700 px-4 py-2.5 rounded-xl text-sm font-bold">+ كامل</button>
        <button onClick={() => setShowImport(true)} className="bg-green-600 text-white px-4 py-2.5 rounded-xl text-sm font-bold hover:bg-green-700">📊 إكسل</button>
        <button onClick={handlePrint} className="bg-gray-100 hover:bg-gray-200 text-gray-700 px-4 py-2.5 rounded-xl text-sm font-bold">🖨️ طباعة</button>
      </div>
      {showImport && <ExcelImportModal onImport={handleExcelImport} onClose={() => setShowImport(false)} />}

      {/* قائمة الطلاب */}
      {cls.students.length === 0 ? (
        <div className="bg-white rounded-2xl p-12 text-center border-2 border-dashed border-blue-200">
          <div className="text-5xl mb-3">👨‍🎓</div>
          <div className="font-bold text-gray-500 mb-3">لا يوجد طلاب في هذا الفصل بعد</div>
          <div className="flex gap-2 justify-center flex-wrap">
            <button onClick={addStudent} className="bg-blue-600 text-white px-5 py-2.5 rounded-xl text-sm font-bold">+ إضافة طالب</button>
            <button onClick={() => addMany(43)} className="bg-indigo-600 text-white px-5 py-2.5 rounded-xl text-sm font-bold">+ إضافة فصل كامل</button>
          </div>
        </div>
      ) : (
        <div>
          {/* بطاقات التقييم الأسبوعي */}
          <div className="mb-2 flex items-center justify-between">
            <div className="font-black text-gray-700 text-sm">📊 التقييمات الأسبوعية ({filtered.length} طالب)</div>
            <div className="flex gap-1.5 flex-wrap">
              {EVAL_LEVELS.slice(1).map(l => (
                <span key={l.value} className="px-2.5 py-1 rounded-full text-xs font-bold" style={{ background: l.bg, color: l.color }}>{l.label}</span>
              ))}
            </div>
          </div>
          {filtered.map(s => (
            <StudentEvalCard key={s.id} student={s} onUpdate={updateStudent} onDelete={removeStudent} onSendNote={onSendNote} messages={messages} />
          ))}
        </div>
      )}
    </div>
  );
}

function StudentsPage({ classList, setClassList, saveClass, deleteClass, teacherMode, teacherName, onSendNote, messages }) {
  const [activeId, setActiveId] = useState(null);
  const [showAddClass, setShowAddClass] = useState(false);
  const [newLevel, setNewLevel] = useState("الصف الأول");
  const [newSection, setNewSection] = useState("أ");
  const [searchQuery, setSearchQuery] = useState("");

  const activeClass = classList.find(c => c.id === activeId) || null;

  // تحميل الفصل الجاهز من ملف الإكسل
  const loadPreloadedClass = async () => {
    const already = classList.find(c => c.id === PRELOADED_CLASS.id);
    if (already) { setActiveId(PRELOADED_CLASS.id); return; }
    const updated = [...classList, PRELOADED_CLASS];
    setClassList(updated);
    await saveClass(PRELOADED_CLASS);
    await DB.set("school-class-list", updated.map(c => ({ id: c.id, name: c.name, level: c.level, section: c.section, teacher: c.teacher, semester: c.semester })));
    setActiveId(PRELOADED_CLASS.id);
  };

  const addNewClass = () => {
    const exists = classList.find(c => c.level === newLevel && c.section === newSection);
    if (exists) { alert("هذا الفصل موجود بالفعل!"); return; }
    const id = `cls-${Date.now()}`;
    const cls = { ...newClass(id), level: newLevel, section: newSection, name: `${newLevel} / ${newSection}` };
    const updated = [...classList, cls];
    setClassList(updated);
    saveClass(cls);
    DB.set("school-class-list", updated.map(c => ({ id: c.id, name: c.name, level: c.level, section: c.section, teacher: c.teacher, semester: c.semester })));
    setActiveId(id);
    setShowAddClass(false);
  };

  const handleUpdateClass = (updated) => {
    setClassList(prev => prev.map(c => c.id === updated.id ? updated : c));
  };

  const handleSaveClass = (cls) => {
    saveClass(cls);
    DB.set("school-class-list", classList.map(c =>
      c.id === cls.id
        ? { id: cls.id, name: cls.name, level: cls.level, section: cls.section, teacher: cls.teacher, semester: cls.semester }
        : { id: c.id, name: c.name, level: c.level, section: c.section, teacher: c.teacher, semester: c.semester }
    ));
  };

  const handleDeleteClass = (id) => {
    if (!confirm("هل تريد حذف هذا الفصل وجميع بياناته؟")) return;
    const updated = classList.filter(c => c.id !== id);
    setClassList(updated);
    deleteClass(id);
    DB.set("school-class-list", updated.map(c => ({ id: c.id, name: c.name, level: c.level, section: c.section, teacher: c.teacher, semester: c.semester })));
    if (activeId === id) setActiveId(updated[0]?.id || null);
  };

  // إحصائيات إجمالية
  const totalStudents = classList.reduce((acc, c) => acc + c.students.filter(s => s.name).length, 0);
  const levelGroups = LEVELS.map(l => ({
    label: l, count: classList.filter(c => c.level === l).reduce((a, c) => a + c.students.filter(s => s.name).length, 0)
  }));

  const filteredClasses = searchQuery ? classList.filter(c =>
    c.level.includes(searchQuery) || c.section.includes(searchQuery) || c.teacher?.includes(searchQuery)
  ) : classList;

  return (
    <div>
      {/* العنوان */}
      <div className="rounded-b-2xl p-6 mb-5 text-white text-center shadow-xl"
        style={{ background: "linear-gradient(135deg, #1B3A6B 0%, #2E6DA4 60%, #1a8fe3 100%)" }}>
        <div className="text-4xl mb-2">👨‍🎓</div>
        <h2 className="text-2xl font-black mb-1">سجل تقييم الطلاب</h2>
        <p className="opacity-80 text-sm">للعام الدراسي ١٤٤٧هـ — مدرسة الأمير عبدالمجيد المتوسطة الأولى</p>
        <div className="flex justify-center gap-4 mt-3 text-sm opacity-90">
          <span>📚 {classList.length} فصل</span>
          <span>👨‍🎓 {totalStudents} طالب</span>
        </div>
        {!teacherMode && classList.length > 0 && (
          <div className="flex justify-center mt-3">
            <button onClick={() => {
              if (!window.confirm("⚠️ سيتم مسح جميع الفصول والطلاب والمستويات بشكل نهائي. هل أنت متأكد؟")) return;
              setClassList([]);
              if (saveClass) saveClass(null);
              if (deleteClass) classList.forEach(c => deleteClass(c.id));
              alert("✅ تم مسح جميع بيانات الطلاب");
            }}
              className="bg-red-700 bg-opacity-60 hover:bg-opacity-80 text-white rounded-xl px-4 py-2 text-sm font-bold border border-red-400 border-opacity-50">
              🗑️ مسح جميع البيانات
            </button>
          </div>
        )}
      </div>

      {/* زر تحميل الفصل الجاهز */}
      {!classList.find(c => c.id === PRELOADED_CLASS.id) && (
        <div className="bg-amber-50 border-2 border-amber-300 rounded-2xl p-5 mb-5 text-center">
          <div className="text-3xl mb-2">📥</div>
          <div className="font-black text-amber-800 text-lg mb-1">لديك فصل جاهز من ملف الإكسل!</div>
          <div className="text-amber-700 text-sm mb-4">الصف الأول / أ — 25 طالباً بأسمائهم وأرقام هوياتهم</div>
          <button onClick={loadPreloadedClass}
            className="bg-amber-500 hover:bg-amber-600 text-white px-8 py-3 rounded-xl font-black text-base shadow-md hover:shadow-lg transition-all">
            📥 تحميل الفصل الأول / أ (25 طالب)
          </button>
        </div>
      )}

      {/* إحصائيات المستويات */}
      {classList.length > 0 && (
        <div className="grid grid-cols-3 gap-3 mb-5">
          {levelGroups.map((l, i) => (
            <div key={i} className="bg-white rounded-2xl p-3 text-center shadow-sm border border-blue-100">
              <div className="text-lg font-black text-blue-800">{l.count}</div>
              <div className="text-xs text-gray-500 font-bold">{l.label}</div>
              <div className="text-xs text-gray-400">{classList.filter(c => c.level === l.label).length} فصول</div>
            </div>
          ))}
        </div>
      )}

      <div className="flex gap-4">
        {/* القائمة الجانبية للفصول */}
        <div className="w-56 flex-shrink-0">
          <div className="bg-white rounded-2xl shadow-sm border border-gray-100 overflow-hidden sticky top-20">
            <div className="px-3 py-3 font-bold text-white text-sm flex items-center justify-between" style={{ background: "#1B3A6B" }}>
              <span>📚 الفصول ({classList.length})</span>
            </div>
            {/* بحث */}
            <div className="p-2 border-b border-gray-100">
              <input type="text" placeholder="بحث..." value={searchQuery} onChange={e => setSearchQuery(e.target.value)}
                className="w-full px-3 py-1.5 rounded-lg border border-gray-200 text-xs focus:outline-none focus:border-blue-400" />
            </div>
            <div className="max-h-96 overflow-y-auto">
              {filteredClasses.length === 0 && (
                <div className="text-center text-xs text-gray-400 py-6">لا توجد فصول</div>
              )}
              {LEVELS.map(level => {
                const levelCls = filteredClasses.filter(c => c.level === level);
                if (levelCls.length === 0) return null;
                return (
                  <div key={level}>
                    <div className="px-3 py-1.5 text-xs font-black text-blue-700 bg-blue-50 border-b border-blue-100">{level}</div>
                    {levelCls.map(cls => (
                      <div key={cls.id}
                        className={`flex items-center justify-between px-3 py-2.5 cursor-pointer border-b border-gray-50 group transition-colors ${activeId === cls.id ? "bg-blue-600 text-white" : "hover:bg-blue-50"}`}
                        onClick={() => setActiveId(cls.id)}>
                        <div>
                          <div className={`text-xs font-bold ${activeId === cls.id ? "text-white" : "text-gray-800"}`}>
                            شعبة {cls.section}
                          </div>
                          <div className={`text-xs ${activeId === cls.id ? "text-blue-200" : "text-gray-400"}`}>
                            {cls.students.filter(s => s.name).length} طالب
                          </div>
                        </div>
                        <button onClick={e => { e.stopPropagation(); handleDeleteClass(cls.id); }}
                          className={`text-xs w-6 h-6 rounded-lg flex items-center justify-center opacity-0 group-hover:opacity-100 transition-opacity ${activeId === cls.id ? "bg-blue-500 text-white hover:bg-red-400" : "bg-red-50 text-red-400 hover:bg-red-100"}`}>
                          ✕
                        </button>
                      </div>
                    ))}
                  </div>
                );
              })}
            </div>
            {/* إضافة فصل */}
            <div className="p-2 border-t border-gray-100">
              {!showAddClass ? (
                <div className="flex gap-1.5 mb-1.5">
                  <button onClick={() => setShowAddClass(true)}
                    className="flex-1 bg-blue-600 text-white py-2 rounded-xl text-xs font-bold hover:bg-blue-700">
                    + إضافة فصل
                  </button>
                  <button onClick={downloadStudentsTemplate}
                    className="flex-1 bg-green-600 text-white py-2 rounded-xl text-xs font-bold hover:bg-green-700"
                    title="تحميل ملف Excel نموذجي بالمراحل الثلاث">
                    📥 نموذج Excel
                  </button>
                </div>
              ) : (
                <div className="space-y-2">
                  <select value={newLevel} onChange={e => setNewLevel(e.target.value)}
                    className="w-full px-2 py-1.5 rounded-lg border border-gray-200 text-xs focus:outline-none">
                    {LEVELS.map(l => <option key={l} value={l}>{l}</option>)}
                  </select>
                  <select value={newSection} onChange={e => setNewSection(e.target.value)}
                    className="w-full px-2 py-1.5 rounded-lg border border-gray-200 text-xs focus:outline-none">
                    {SECTIONS.map(s => <option key={s} value={s}>شعبة {s}</option>)}
                  </select>
                  <div className="flex gap-1">
                    <button onClick={addNewClass} className="flex-1 bg-blue-600 text-white py-1.5 rounded-lg text-xs font-bold">إضافة</button>
                    <button onClick={() => setShowAddClass(false)} className="flex-1 bg-gray-100 text-gray-600 py-1.5 rounded-lg text-xs font-bold">إلغاء</button>
                  </div>
                </div>
              )}
            </div>
          </div>
        </div>

        {/* محتوى الفصل المختار */}
        <div className="flex-1 min-w-0">
          {!activeClass ? (
            <div className="bg-white rounded-2xl p-16 text-center border-2 border-dashed border-blue-200">
              <div className="text-6xl mb-4">📚</div>
              <div className="font-black text-gray-500 text-lg mb-2">اختر فصلاً أو أضف فصلاً جديداً</div>
              <p className="text-gray-400 text-sm mb-5">يمكنك إضافة فصول لكل مستوى بشكل منفصل وحفظ بيانات كل فصل مستقلاً</p>
              <button onClick={() => setShowAddClass(true)}
                className="bg-blue-600 text-white px-6 py-3 rounded-xl font-bold hover:bg-blue-700">
                + إضافة أول فصل
              </button>
            </div>
          ) : (
            <div>
              <div className="flex items-center gap-3 mb-4">
                <div className="text-2xl font-black text-blue-900">{activeClass.level} / {activeClass.section}</div>
                {activeClass.teacher && <span className="bg-blue-100 text-blue-700 px-3 py-1 rounded-full text-xs font-bold">👨‍🏫 {activeClass.teacher}</span>}
                {activeClass.semester && <span className="bg-gray-100 text-gray-600 px-3 py-1 rounded-full text-xs font-bold">📅 الفصل {activeClass.semester}</span>}
              </div>
              <ClassTable
                cls={activeClass}
                onUpdateClass={handleUpdateClass}
                onSave={handleSaveClass}
                onSendNote={onSendNote}
                messages={messages}
              />
            </div>
          )}
        </div>
      </div>
    </div>
  );
}

// ===== صفحة رسائل وآراء أولياء الأمور =====
const MSG_RECIPIENTS = ["مدير المدرسة", "المعلم المسؤول", "الموجه الطلابي", "الجميع"];
const MSG_TYPES = [
  { value: "suggestion", label: "اقتراح", icon: "💡", color: "#dbeafe" },
  { value: "complaint",  label: "شكوى",  icon: "📣", color: "#fee2e2" },
  { value: "inquiry",    label: "استفسار",icon: "❓", color: "#fef9c3" },
  { value: "praise",     label: "إشادة", icon: "🌟", color: "#d1fae5" },
  { value: "message",    label: "رسالة",  icon: "✉️", color: "#ede9fe" },
];

function MessagesPage({ messages, setMessages, saveMessages, isParent, parentName }) {
  const [showForm, setShowForm] = useState(false);
  const [form, setForm] = useState({ recipient: "مدير المدرسة", type: "suggestion", name: parentName || "", phone: "", text: "" });
  const [saved, setSaved] = useState(false);
  const [filterType, setFilterType] = useState("all");
  const [filterRecipient, setFilterRecipient] = useState("all");
  const [searchQ, setSearchQ] = useState("");
  const [replyId, setReplyId] = useState(null);
  const [replyText, setReplyText] = useState("");

  const sendMsg = () => {
    if (!form.text.trim()) { alert("الرجاء كتابة نص الرسالة"); return; }
    const msg = { id: Date.now(), ...form, date: new Date().toLocaleDateString("ar-SA"), time: new Date().toLocaleTimeString("ar-SA", { hour: "2-digit", minute: "2-digit" }), read: false, reply: "" };
    const updated = [msg, ...messages];
    setMessages(updated);
    saveMessages(updated);
    setForm({ recipient: "مدير المدرسة", type: "suggestion", name: parentName || "", phone: "", text: "" });
    setShowForm(false);
    setSaved(true);
    setTimeout(() => setSaved(false), 3000);
  };

  const markRead = (id) => {
    const updated = messages.map(m => m.id === id ? { ...m, read: true } : m);
    setMessages(updated); saveMessages(updated);
  };

  const sendReply = (id) => {
    if (!replyText.trim()) return;
    const updated = messages.map(m => m.id === id ? { ...m, reply: replyText, repliedAt: new Date().toLocaleDateString("ar-SA"), read: true } : m);
    setMessages(updated); saveMessages(updated);
    setReplyId(null); setReplyText("");
  };

  const deleteMsg = (id) => {
    if (!confirm("حذف هذه الرسالة؟")) return;
    const updated = messages.filter(m => m.id !== id);
    setMessages(updated); saveMessages(updated);
  };

  const filtered = messages.filter(m => {
    if (filterType !== "all" && m.type !== filterType) return false;
    if (filterRecipient !== "all" && m.recipient !== filterRecipient) return false;
    if (searchQ && !m.text.includes(searchQ) && !m.name.includes(searchQ)) return false;
    return true;
  });

  const unread = messages.filter(m => !m.read).length;

  return (
    <div dir="rtl">
      {/* بانر الشراكة */}
      <div className="rounded-b-2xl overflow-hidden mb-6 shadow-xl" style={{ background: "linear-gradient(135deg, #1e3a5f 0%, #2563eb 60%, #0ea5e9 100%)" }}>
        <div className="p-8 text-white">
          <div className="flex flex-col md:flex-row items-center gap-6">
            <div className="text-7xl flex-shrink-0">🤝</div>
            <div className="text-center md:text-right flex-1">
              <h2 className="text-2xl font-black mb-2">شراكة الأسرة والمدرسة</h2>
              <p className="text-blue-100 leading-relaxed text-sm">
                تؤمن مدرسة الأمير عبدالمجيد المتوسطة الأولى بأن نجاح الطالب يبدأ من شراكة حقيقية بين الأسرة والمدرسة.
                هذه المنصة جسر تواصل مفتوح بين أولياء الأمور والمدرسة — شاركونا آراءكم ومقترحاتكم واستفساراتكم،
                فأنتم شركاؤنا في بناء جيل واعٍ ومتميز.
              </p>
              <div className="flex flex-wrap gap-3 mt-4 justify-center md:justify-start">
                {["🎯 نستمع لكم", "💬 نردّ على رسائلكم", "🌱 نبني معاً", "🏆 أبناؤكم أولويتنا"].map(t => (
                  <span key={t} className="bg-white bg-opacity-20 px-3 py-1.5 rounded-full text-xs font-bold">{t}</span>
                ))}
              </div>
            </div>
          </div>
        </div>
        <div className="bg-white bg-opacity-10 px-6 py-3 flex flex-wrap gap-4 justify-between items-center">
          <div className="flex gap-2 flex-wrap">
            {/* زر دعوة أولياء الأمور */}
            {!isParent && (
              <button onClick={() => {
                const link = (typeof window !== "undefined" ? window.location.origin : "https://school-website1-sigma.vercel.app");
                const msg = encodeURIComponent(
                  `🏫 *مدرسة الأمير عبدالمجيد المتوسطة الأولى*\n\n` +
                  `✉️ *بوابة التواصل مع الأسرة*\n\n` +
                  `أعزاءنا أولياء الأمور،\n` +
                  `يسعدنا إطلاق بوابة التواصل المدرسي حيث يمكنكم إرسال آرائكم ومقترحاتكم واستفساراتكم مباشرةً لإدارة المدرسة.\n\n` +
                  `👈 اضغط الرابط وأدخل رقم هوية الطالب:\n${link}\n\n` +
                  `_ثم اختر تبويب "رسالة" ✉️_`
                );
                window.open(`https://wa.me/?text=${msg}`, "_blank");
              }}
                className="bg-green-500 hover:bg-green-600 text-white px-4 py-2 rounded-xl font-black text-xs flex items-center gap-1.5 shadow">
                <span className="text-base">📲</span> دعوة أولياء الأمور عبر واتساب
              </button>
            )}
            {saved && <span className="bg-green-400 text-white px-4 py-1.5 rounded-full text-sm font-black">✅ تم إرسال رسالتك بنجاح!</span>}
          </div>
        </div>
      </div>

      {/* زر إرسال رسالة */}
      {!showForm && (
        <button onClick={() => setShowForm(true)}
          className="w-full mb-5 py-4 rounded-2xl text-white font-black text-base shadow-lg hover:shadow-xl transition-all"
          style={{ background: "linear-gradient(135deg, #2563eb, #0ea5e9)" }}>
          ✉️ إرسال رسالة / رأي / مقترح جديد
        </button>
      )}

      {/* نموذج الإرسال */}
      {showForm && (
        <div className="bg-white rounded-3xl shadow-xl border border-blue-100 p-6 mb-6">
          <div className="flex items-center justify-between mb-5">
            <h3 className="font-black text-gray-800 text-lg">✉️ رسالة جديدة</h3>
            <button onClick={() => setShowForm(false)} className="text-gray-400 hover:text-gray-600 text-xl font-bold">✕</button>
          </div>
          <div className="space-y-4">
            {/* نوع الرسالة */}
            <div>
              <label className="text-xs font-black text-gray-600 mb-2 block">نوع الرسالة</label>
              <div className="flex gap-2 flex-wrap">
                {MSG_TYPES.map(t => (
                  <button key={t.value} onClick={() => setForm(p => ({ ...p, type: t.value }))}
                    className="px-3 py-2 rounded-xl text-sm font-bold border-2 transition-all"
                    style={{ background: form.type === t.value ? t.color : "#f9fafb", borderColor: form.type === t.value ? "#2563eb" : "#e5e7eb", color: form.type === t.value ? "#1e3a5f" : "#9ca3af" }}>
                    {t.icon} {t.label}
                  </button>
                ))}
              </div>
            </div>
            {/* الجهة المرسل إليها */}
            <div>
              <label className="text-xs font-black text-gray-600 mb-2 block">الرسالة موجهة إلى</label>
              <select value={form.recipient} onChange={e => setForm(p => ({ ...p, recipient: e.target.value }))}
                className="w-full px-4 py-3 rounded-xl border-2 border-gray-200 text-sm focus:border-blue-400 focus:outline-none font-bold"
                style={{ fontFamily: "inherit" }}>
                {MSG_RECIPIENTS.map(r => <option key={r} value={r}>{r}</option>)}
              </select>
            </div>
            {/* الاسم والجوال */}
            <div className="grid grid-cols-2 gap-3">
              <div>
                <label className="text-xs font-black text-gray-600 mb-1 block">الاسم (اختياري)</label>
                <input value={form.name} onChange={e => setForm(p => ({ ...p, name: e.target.value }))}
                  placeholder="اسم ولي الأمر"
                  className="w-full px-3 py-2.5 rounded-xl border-2 border-gray-200 text-sm focus:border-blue-400 focus:outline-none"
                  style={{ fontFamily: "inherit" }} />
              </div>
              <div>
                <label className="text-xs font-black text-gray-600 mb-1 block">رقم التواصل (اختياري)</label>
                <input value={form.phone} onChange={e => setForm(p => ({ ...p, phone: e.target.value }))}
                  placeholder="05xxxxxxxx" dir="ltr"
                  className="w-full px-3 py-2.5 rounded-xl border-2 border-gray-200 text-sm focus:border-blue-400 focus:outline-none text-right"
                  style={{ fontFamily: "inherit" }} />
              </div>
            </div>
            {/* نص الرسالة */}
            <div>
              <label className="text-xs font-black text-gray-600 mb-1 block">نص الرسالة / الرأي / الاقتراح *</label>
              <textarea value={form.text} onChange={e => setForm(p => ({ ...p, text: e.target.value }))}
                rows={5} placeholder="اكتب رسالتك هنا..."
                className="w-full px-4 py-3 rounded-xl border-2 border-gray-200 text-sm focus:border-blue-400 focus:outline-none resize-none"
                style={{ fontFamily: "inherit" }} />
            </div>
            <div className="flex gap-3">
              <button onClick={sendMsg}
                className="flex-1 py-3 rounded-xl text-white font-black hover:shadow-lg transition-all"
                style={{ background: "linear-gradient(135deg, #2563eb, #0ea5e9)" }}>
                📤 إرسال الرسالة
              </button>
              <button onClick={() => setShowForm(false)} className="px-6 py-3 rounded-xl bg-gray-100 text-gray-600 font-bold hover:bg-gray-200">إلغاء</button>
            </div>
          </div>
        </div>
      )}

      {/* فلاتر وبحث — للإدارة فقط */}
      {!isParent && messages.length > 0 && (
        <div className="bg-white rounded-2xl border border-gray-100 p-4 mb-4 shadow-sm">
          <div className="flex flex-wrap gap-3 items-center">
            <input value={searchQ} onChange={e => setSearchQ(e.target.value)} placeholder="🔍 بحث..."
              className="flex-1 min-w-32 px-3 py-2 rounded-xl border-2 border-gray-200 text-sm focus:outline-none focus:border-blue-400" />
            <select value={filterType} onChange={e => setFilterType(e.target.value)}
              className="px-3 py-2 rounded-xl border-2 border-gray-200 text-sm focus:outline-none" style={{ fontFamily: "inherit" }}>
              <option value="all">جميع الأنواع</option>
              {MSG_TYPES.map(t => <option key={t.value} value={t.value}>{t.icon} {t.label}</option>)}
            </select>
            <select value={filterRecipient} onChange={e => setFilterRecipient(e.target.value)}
              className="px-3 py-2 rounded-xl border-2 border-gray-200 text-sm focus:outline-none" style={{ fontFamily: "inherit" }}>
              <option value="all">جميع الجهات</option>
              {MSG_RECIPIENTS.map(r => <option key={r} value={r}>{r}</option>)}
            </select>
          </div>
        </div>
      )}

      {/* قائمة الرسائل */}
      {filtered.length === 0 ? (
        <div className="bg-white rounded-2xl p-10 text-center border-2 border-dashed border-blue-100">
          <div className="text-5xl mb-3">📬</div>
          <div className="font-bold text-gray-400">لا توجد رسائل بعد — كن أول من يشارك!</div>
        </div>
      ) : (
        <div className="space-y-3">
          {filtered.map(msg => {
            // ملاحظات المعلم — عرض خاص
            if (msg.type === "teacher_note") return (
              <div key={msg.id} className="bg-white rounded-2xl border-2 shadow-sm overflow-hidden transition-all"
                style={{ borderColor: msg.read ? "#fcd34d" : "#f59e0b" }}>
                <div className="flex items-center justify-between px-4 py-3" style={{ background: "linear-gradient(135deg,#fef3c7,#fde68a)" }}>
                  <div className="flex items-center gap-2">
                    <span className="text-xl">📨</span>
                    <span className="font-black text-amber-800 text-sm">ملاحظة معلم</span>
                    <span className="text-xs text-amber-700 bg-white bg-opacity-70 px-2 py-0.5 rounded-full font-bold">→ {msg.studentName || "طالب"}</span>
                    {!msg.read && <span className="bg-amber-500 text-white text-xs px-2 py-0.5 rounded-full font-bold animate-pulse">جديد</span>}
                  </div>
                  <div className="flex items-center gap-2 text-xs text-amber-700">
                    <span>{msg.time} | {msg.date}</span>
                    {!isParent && (
                      <>
                        {!msg.read && <button onClick={() => markRead(msg.id)} className="text-amber-700 hover:text-amber-900 font-bold px-2 py-0.5 rounded-lg hover:bg-amber-100">✓ قراءة</button>}
                        <button onClick={() => deleteMsg(msg.id)} className="text-red-400 hover:text-red-600 px-1">🗑️</button>
                      </>
                    )}
                  </div>
                </div>
                <div className="px-4 py-3">
                  <div className="text-xs font-bold text-gray-500 mb-2">👨‍🏫 المعلم → طالب: {msg.studentName}{msg.studentId && ` (${msg.studentId})`}</div>
                  <p className="text-sm text-gray-800 leading-relaxed bg-amber-50 border border-amber-200 rounded-xl px-3 py-2">{msg.text}</p>
                  {msg.reply && (
                    <div className="mt-3 bg-blue-50 border border-blue-200 rounded-xl p-3">
                      <div className="text-xs font-black text-blue-700 mb-1">💬 رد ولي الأمر — {msg.repliedAt}</div>
                      <p className="text-sm text-blue-800">{msg.reply}</p>
                    </div>
                  )}
                </div>
              </div>
            );

            const t = MSG_TYPES.find(x => x.value === msg.type) || MSG_TYPES[4];
            return (
              <div key={msg.id} className="bg-white rounded-2xl border shadow-sm overflow-hidden transition-all"
                style={{ borderColor: msg.read ? "#e5e7eb" : "#bfdbfe", borderWidth: msg.read ? 1 : 2 }}>
                {/* رأس الرسالة */}
                <div className="flex items-center justify-between px-4 py-3" style={{ background: t.color }}>
                  <div className="flex items-center gap-2">
                    <span className="text-xl">{t.icon}</span>
                    <span className="font-black text-gray-800 text-sm">{t.label}</span>
                    <span className="text-xs text-gray-500 bg-white bg-opacity-60 px-2 py-0.5 rounded-full">→ {msg.recipient}</span>
                    {!msg.read && <span className="bg-blue-600 text-white text-xs px-2 py-0.5 rounded-full font-bold">جديد</span>}
                  </div>
                  <div className="flex items-center gap-2 text-xs text-gray-500">
                    <span>{msg.time} | {msg.date}</span>
                    {!isParent && (
                      <>
                        {!msg.read && <button onClick={() => markRead(msg.id)} className="text-blue-600 hover:text-blue-800 font-bold px-2 py-0.5 rounded-lg hover:bg-blue-50">✓ قراءة</button>}
                        <button onClick={() => deleteMsg(msg.id)} className="text-red-400 hover:text-red-600 px-1">🗑️</button>
                      </>
                    )}
                  </div>
                </div>
                {/* محتوى الرسالة */}
                <div className="px-4 py-3">
                  {msg.name && <div className="text-xs font-bold text-gray-500 mb-1">👤 {msg.name}{msg.phone && ` | 📞 ${msg.phone}`}</div>}
                  <p className="text-sm text-gray-800 leading-relaxed">{msg.text}</p>
                  {/* الرد */}
                  {msg.reply && (
                    <div className="mt-3 bg-teal-50 border border-teal-200 rounded-xl p-3">
                      <div className="text-xs font-black text-teal-700 mb-1">↩️ رد الإدارة — {msg.repliedAt}</div>
                      <p className="text-sm text-teal-800">{msg.reply}</p>
                    </div>
                  )}
                  {/* نموذج الرد للإدارة */}
                  {!isParent && !msg.reply && replyId === msg.id && (
                    <div className="mt-3 flex gap-2">
                      <input value={replyText} onChange={e => setReplyText(e.target.value)}
                        placeholder="اكتب الرد هنا..."
                        className="flex-1 px-3 py-2 rounded-xl border-2 border-teal-300 text-sm focus:outline-none focus:border-teal-500"
                        style={{ fontFamily: "inherit" }} />
                      <button onClick={() => sendReply(msg.id)} className="bg-teal-600 text-white px-4 py-2 rounded-xl text-sm font-bold hover:bg-teal-700">إرسال</button>
                      <button onClick={() => setReplyId(null)} className="bg-gray-100 text-gray-500 px-3 py-2 rounded-xl text-sm font-bold">✕</button>
                    </div>
                  )}
                  {!isParent && !msg.reply && replyId !== msg.id && (
                    <button onClick={() => { setReplyId(msg.id); setReplyText(""); }}
                      className="mt-2 text-xs text-teal-600 font-bold hover:underline">↩️ ردّ على هذه الرسالة</button>
                  )}
                </div>
              </div>
            );
          })}
        </div>
      )}
    </div>
  );
}

// ===== نظام الاستبيانات — مقياس ليكرت الخماسي =====
// ================================================================

const LIKERT_OPTIONS = ["أوافق بشدة","أوافق","محايد","غير موافق","غير موافق بشدة"];
const LIKERT_COLORS  = ["#16a34a","#4ade80","#f59e0b","#f97316","#dc2626"];
const LIKERT_ICONS   = ["✅✅","✅","➖","❌","❌❌"];
const SURVEY_TARGETS = ["معلمون","طلاب","أولياء أمور"];

// Firebase يحذف المصفوفات الفارغة: استبيان بلا فئات مستهدفة أو بلا أسئلة يصل بدونها — نوحّد الشكل قبل العرض
const svArr = v => Array.isArray(v) ? v.filter(x => x != null) : (v && typeof v === "object" ? Object.values(v).filter(x => x != null) : []);
const svNorm = L => svArr(L).filter(x => x && typeof x === "object").map(x => ({ title: "", dateH: "", createdAt: "", color: "#1e3a5f", ...x, targets: svArr(x.targets), questions: svArr(x.questions).filter(q => q && typeof q === "object") }));
function mkSurvey() {
  const today = new Date();
  try {
    const h = gregorianToHijri(today.getFullYear(), today.getMonth()+1, today.getDate());
    return {
      id: Date.now(),
      title: "",
      dateH: `${String(h.d).padStart(2,"0")} / ${String(h.m).padStart(2,"0")} / ${h.y}`,
      targets: [],
      questions: [],
      createdAt: today.toLocaleDateString("ar-SA"),
      color: "#1e3a5f",
    };
  } catch {
    return {
      id: Date.now(), title: "", dateH: "____ / ____ / 1447",
      targets: [], questions: [], createdAt: today.toLocaleDateString("ar-SA"), color: "#1e3a5f",
    };
  }
}

function mkQuestion() {
  return { id: Date.now() + Math.random() * 999 | 0, text: "" };
}

// ================================================================
// ===== صانع الاستبيان (نموذج الإنشاء/التعديل) =====
// ================================================================
function SurveyBuilder({ survey, onSave, onCancel }) {
  const [s, setS] = useState({ ...survey, questions: survey.questions.map(q=>({...q})) });
  const colors = ["#1e3a5f","#065f46","#5b21b6","#991b1b","#92400e","#1d4ed8","#134e4a","#4c0519"];

  const addQ = () => setS(p => ({ ...p, questions: [...p.questions, mkQuestion()] }));
  const delQ = (id) => setS(p => ({ ...p, questions: p.questions.filter(q=>q.id!==id) }));
  const updQ = (id, text) => setS(p => ({ ...p, questions: p.questions.map(q=>q.id===id?{...q,text}:q) }));
  const moveQ = (idx, dir) => {
    const qs = [...s.questions];
    const to = idx + dir;
    if (to < 0 || to >= qs.length) return;
    [qs[idx], qs[to]] = [qs[to], qs[idx]];
    setS(p => ({ ...p, questions: qs }));
  };

  return (
    <div dir="rtl" style={{ fontFamily:"'Cairo','Noto Naskh Arabic',sans-serif", background:"#f8fafc", minHeight:"100vh", padding:"16px" }}>
      {/* رأس */}
      <div style={{ background:`linear-gradient(135deg, ${s.color} 0%, ${s.color}cc 100%)`, borderRadius:16, padding:"16px 20px", marginBottom:16, display:"flex", alignItems:"center", justifyContent:"space-between" }}>
        <div>
          <div style={{ color:"#fff", fontWeight:900, fontSize:16 }}>📋 {s.id === survey.id && s.title ? "تعديل الاستبيان" : "استبيان جديد"}</div>
          <div style={{ color:"rgba(255,255,255,.7)", fontSize:11, marginTop:2 }}>مدرسة الأمير عبدالمجيد المتوسطة الأولى</div>
        </div>
        <button onClick={onCancel} style={{ background:"rgba(255,255,255,.15)", border:"none", borderRadius:8, color:"#fff", fontWeight:800, fontSize:12, padding:"6px 14px", cursor:"pointer", fontFamily:"'Cairo',sans-serif" }}>✕ إلغاء</button>
      </div>

      <div style={{ background:"#fff", borderRadius:14, padding:16, marginBottom:12, boxShadow:"0 2px 8px rgba(0,0,0,.06)" }}>
        {/* عنوان الاستبيان */}
        <label style={{ fontSize:12, fontWeight:700, color:"#475569", display:"block", marginBottom:5 }}>📌 عنوان الاستبيان *</label>
        <input value={s.title} onChange={e=>setS(p=>({...p,title:e.target.value}))}
          placeholder="مثال: استبانة قياس رضا المعلمين"
          style={{ width:"100%", padding:"10px 14px", borderRadius:10, border:"2px solid #e2e8f0", fontFamily:"'Cairo',sans-serif", fontSize:14, outline:"none", boxSizing:"border-box", marginBottom:12 }} />

        {/* التاريخ */}
        <label style={{ fontSize:12, fontWeight:700, color:"#475569", display:"block", marginBottom:5 }}>📅 التاريخ الهجري</label>
        <input value={s.dateH} onChange={e=>setS(p=>({...p,dateH:e.target.value}))}
          placeholder="مثال: 15 / 10 / 1447"
          style={{ width:"100%", padding:"10px 14px", borderRadius:10, border:"2px solid #e2e8f0", fontFamily:"'Cairo',sans-serif", fontSize:14, outline:"none", boxSizing:"border-box", marginBottom:12 }} />

        {/* الفئة المستهدفة */}
        <label style={{ fontSize:12, fontWeight:700, color:"#475569", display:"block", marginBottom:8 }}>👥 الفئة المستهدفة</label>
        <div style={{ display:"flex", gap:12, flexWrap:"wrap", marginBottom:12 }}>
          {SURVEY_TARGETS.map(t => (
            <label key={t} style={{ display:"flex", alignItems:"center", gap:6, cursor:"pointer", fontSize:13, fontWeight:700 }}>
              <input type="checkbox" checked={s.targets.includes(t)}
                onChange={e => setS(p => ({ ...p, targets: e.target.checked ? [...p.targets,t] : p.targets.filter(x=>x!==t) }))}
                style={{ width:16, height:16, cursor:"pointer" }} />
              {t}
            </label>
          ))}
        </div>

        {/* اللون */}
        <label style={{ fontSize:12, fontWeight:700, color:"#475569", display:"block", marginBottom:6 }}>🎨 لون الاستبيان</label>
        <div style={{ display:"flex", gap:8, flexWrap:"wrap" }}>
          {colors.map(c => (
            <button key={c} onClick={()=>setS(p=>({...p,color:c}))}
              style={{ width:30, height:30, borderRadius:"50%", background:c, border: s.color===c?"3px solid #1e293b":"2px solid #e2e8f0", cursor:"pointer" }} />
          ))}
        </div>
      </div>

      {/* الأسئلة */}
      <div style={{ background:"#fff", borderRadius:14, padding:16, marginBottom:12, boxShadow:"0 2px 8px rgba(0,0,0,.06)" }}>
        <div style={{ display:"flex", alignItems:"center", justifyContent:"space-between", marginBottom:12 }}>
          <span style={{ fontWeight:900, fontSize:14, color:"#1e293b" }}>❓ الأسئلة ({s.questions.length})</span>
          <button onClick={addQ}
            style={{ background:s.color, color:"#fff", border:"none", borderRadius:10, padding:"7px 14px", fontSize:12, fontWeight:800, cursor:"pointer", fontFamily:"'Cairo',sans-serif" }}>
            ➕ إضافة سؤال
          </button>
        </div>
        {s.questions.length === 0 && (
          <div style={{ textAlign:"center", padding:"24px 0", color:"#94a3b8", fontSize:13 }}>لا توجد أسئلة بعد — اضغط «إضافة سؤال»</div>
        )}
        {s.questions.map((q, idx) => (
          <div key={q.id} style={{ background:"#f8fafc", borderRadius:10, padding:"12px", marginBottom:8, border:"1.5px solid #e2e8f0" }}>
            <div style={{ display:"flex", alignItems:"center", gap:8, marginBottom:6 }}>
              <span style={{ background:s.color, color:"#fff", borderRadius:"50%", width:22, height:22, display:"flex", alignItems:"center", justifyContent:"center", fontSize:11, fontWeight:900, flexShrink:0 }}>{idx+1}</span>
              <input value={q.text} onChange={e=>updQ(q.id, e.target.value)}
                placeholder={`نص السؤال ${idx+1}...`}
                style={{ flex:1, padding:"7px 10px", borderRadius:8, border:"1.5px solid #e2e8f0", fontFamily:"'Cairo',sans-serif", fontSize:13, outline:"none" }} />
              <button onClick={()=>moveQ(idx,-1)} disabled={idx===0} style={{ background:"none", border:"none", fontSize:14, cursor:idx===0?"default":"pointer", opacity:idx===0?.3:1 }}>▲</button>
              <button onClick={()=>moveQ(idx,1)} disabled={idx===s.questions.length-1} style={{ background:"none", border:"none", fontSize:14, cursor:idx===s.questions.length-1?"default":"pointer", opacity:idx===s.questions.length-1?.3:1 }}>▼</button>
              <button onClick={()=>delQ(q.id)} style={{ background:"#fee2e2", border:"none", borderRadius:6, color:"#dc2626", fontSize:12, padding:"3px 8px", cursor:"pointer" }}>🗑️</button>
            </div>
            <div style={{ fontSize:11, color:"#94a3b8", paddingRight:30 }}>مقياس: أوافق بشدة • أوافق • محايد • غير موافق • غير موافق بشدة</div>
          </div>
        ))}
      </div>

      <button onClick={()=>{ if(!s.title.trim()){alert("أدخل عنوان الاستبيان أولاً");return;} if(s.questions.length===0){alert("أضف سؤالاً واحداً على الأقل");return;} onSave(s); }}
        style={{ width:"100%", padding:"13px", borderRadius:12, border:"none", background:s.color, color:"#fff", fontWeight:900, fontSize:15, cursor:"pointer", fontFamily:"'Cairo',sans-serif" }}>
        💾 حفظ الاستبيان
      </button>
    </div>
  );
}

// ================================================================
// ===== صفحة ملء الاستبيان (طباعة + إجابة) =====
// ================================================================
function SurveyRespond({ survey, onClose }) {
  const [answers, setAnswers] = useState({});
  const [participantName, setParticipantName] = useState("");
  const [participantPhone, setParticipantPhone] = useState("");

  const handlePrint = () => {
    const html = `<!DOCTYPE html><html dir="rtl"><head><meta charset="utf-8"><title>${survey.title}</title>
    <style>
      @import url('https://fonts.googleapis.com/css2?family=Cairo:wght@400;700;900&display=swap');
      *{margin:0;padding:0;box-sizing:border-box}
      body{font-family:'Cairo',sans-serif;direction:rtl;background:#fff;color:#1e293b;padding:0}
      .page{max-width:700px;margin:0 auto;padding:20px;border:3px solid ${survey.color};border-radius:12px;min-height:297mm}
      .header{text-align:center;padding:20px 0 16px;border-bottom:3px solid ${survey.color};margin-bottom:20px}
      .school-name{font-size:22px;font-weight:900;color:${survey.color};margin-bottom:4px}
      .survey-title{font-size:18px;font-weight:900;color:#1e293b;margin:10px 0 4px}
      .quote{font-size:12px;color:#64748b;font-style:italic;margin-bottom:12px;line-height:1.8}
      .meta-row{display:flex;justify-content:center;gap:20px;flex-wrap:wrap;margin-bottom:8px}
      .meta-item{font-size:12px;color:#475569}
      .target-row{display:flex;justify-content:center;gap:20px;margin:10px 0}
      .target-item{display:flex;align-items:center;gap:6px;font-size:12px}
      .checkbox-sq{width:14px;height:14px;border:1.5px solid #475569;display:inline-block;border-radius:2px}
      .checked-sq{background:${survey.color};border-color:${survey.color}}
      .participant{background:#f8fafc;border:1px solid #e2e8f0;border-radius:8px;padding:10px 14px;margin-bottom:16px;font-size:12px}
      .q-block{margin-bottom:18px;page-break-inside:avoid}
      .q-num{display:inline-block;background:${survey.color};color:#fff;border-radius:50%;width:22px;height:22px;text-align:center;line-height:22px;font-size:11px;font-weight:900;margin-left:6px}
      .q-text{font-size:13px;font-weight:700;margin-bottom:8px;display:flex;align-items:center}
      .likert-table{width:100%;border-collapse:collapse;font-size:11.5px}
      .likert-table th,.likert-table td{border:1px solid #e2e8f0;padding:6px 8px;text-align:center}
      .likert-table th{background:#f0f4f8;font-weight:800;color:#1e293b}
      .likert-table td:first-child{text-align:right;font-weight:700;color:#374151;padding-right:10px}
      .circle{width:14px;height:14px;border:1.5px solid #94a3b8;border-radius:50%;display:inline-block}
      .secret{text-align:center;font-size:11px;color:#94a3b8;margin-top:20px;padding-top:12px;border-top:1px dashed #e2e8f0}
      .footer{text-align:center;font-size:10px;color:#94a3b8;margin-top:12px}
      @media print{@page{size:A4;margin:1.5cm}body{padding:0}.page{border:2px solid ${survey.color};padding:16px}}
    </style></head><body>
    <div class="page">
      <div class="header">
        <div class="school-name">🏫 مدرسة الأمير عبدالمجيد المتوسطة الأولى</div>
        <div class="survey-title">📋 ${survey.title}</div>
        <div class="quote">« رأيك يُسهم في تحسين بيئة التعلم وتجويد العمل المدرسي — شكراً لمشاركتك »</div>
        <div class="meta-row">
          <span class="meta-item">📅 التاريخ: ${survey.dateH} هـ</span>
        </div>
        <div class="target-row">
          ${SURVEY_TARGETS.map(t=>`<div class="target-item"><div class="checkbox-sq ${survey.targets.includes(t)?"checked-sq":""}"></div><span>${t}</span></div>`).join("")}
        </div>
      </div>
      <div class="participant">
        <div style="font-weight:700;margin-bottom:6px">معلومات المشارك <span style="font-weight:400;color:#94a3b8">(اختياري — سرية تامة)</span></div>
        <div style="display:flex;gap:20px;flex-wrap:wrap">
          <span>الاسم: _______________________</span>
          <span>رقم الجوال: ___________________</span>
        </div>
      </div>
      ${survey.questions.map((q,i)=>`
        <div class="q-block">
          <div class="q-text"><span class="q-num">${i+1}</span>${q.text}</div>
          <table class="likert-table">
            <tr>
              <th>العبارة</th>
              ${LIKERT_OPTIONS.map(o=>`<th>${o}</th>`).join("")}
            </tr>
            <tr>
              <td>${q.text}</td>
              ${LIKERT_OPTIONS.map(()=>`<td><div class="circle"></div></td>`).join("")}
            </tr>
          </table>
        </div>`).join("")}
      <div class="secret">🔒 هذه الاستبانة سرية ولا يطلع عليها إلا المعنيون في إدارة المدرسة</div>
      <div class="footer">مدرسة الأمير عبدالمجيد المتوسطة الأولى — إدارة تعليم جدة — ${new Date().getFullYear()} م</div>
    </div>
    <script>window.onload=()=>window.print()</script>
    </body></html>`;
    printWindow(html);
  };

  return (
    <div dir="rtl" style={{ fontFamily:"'Cairo','Noto Naskh Arabic',sans-serif", background:"#f8fafc", minHeight:"100vh" }}>
      {/* رأس الاستبيان */}
      <div style={{ background:`linear-gradient(135deg,${survey.color},${survey.color}bb)`, padding:"20px 16px", textAlign:"center" }}>
        <div style={{ fontSize:13, color:"rgba(255,255,255,.8)", marginBottom:4 }}>🏫 مدرسة الأمير عبدالمجيد المتوسطة الأولى</div>
        <div style={{ fontSize:20, fontWeight:900, color:"#fff", marginBottom:6 }}>{survey.title}</div>
        <div style={{ fontSize:11.5, color:"rgba(255,255,255,.75)", lineHeight:1.7 }}>
          « رأيك يُسهم في تحسين بيئة التعلم وتجويد العمل المدرسي »
        </div>
        <div style={{ display:"flex", justifyContent:"center", gap:16, marginTop:10, flexWrap:"wrap" }}>
          {SURVEY_TARGETS.map(t=>(
            <label key={t} style={{ display:"flex", alignItems:"center", gap:5, color:"#fff", fontSize:12, cursor:"pointer" }}>
              <div style={{ width:14, height:14, border:"2px solid rgba(255,255,255,.8)", borderRadius:3, background:survey.targets.includes(t)?"rgba(255,255,255,.9)":"transparent", flexShrink:0 }}></div>
              {t}
            </label>
          ))}
        </div>
        <div style={{ color:"rgba(255,255,255,.75)", fontSize:11.5, marginTop:8 }}>📅 {survey.dateH} هـ</div>
      </div>

      <div style={{ maxWidth:640, margin:"0 auto", padding:"14px 12px 60px" }}>

        {/* معلومات المشارك */}
        <div style={{ background:"#fff", borderRadius:12, padding:14, marginBottom:14, boxShadow:"0 2px 8px rgba(0,0,0,.06)" }}>
          <div style={{ fontWeight:800, fontSize:13, color:"#1e293b", marginBottom:10 }}>
            👤 معلومات المشارك <span style={{ fontWeight:400, color:"#94a3b8", fontSize:11 }}>(اختياري)</span>
          </div>
          <div style={{ display:"grid", gridTemplateColumns:"1fr 1fr", gap:10 }}>
            <div>
              <label style={{ fontSize:11, color:"#64748b", fontWeight:700, display:"block", marginBottom:4 }}>الاسم</label>
              <input value={participantName} onChange={e=>setParticipantName(e.target.value)}
                placeholder="اكتب اسمك..."
                style={{ width:"100%", padding:"8px 10px", borderRadius:8, border:"1.5px solid #e2e8f0", fontFamily:"'Cairo',sans-serif", fontSize:13, outline:"none", boxSizing:"border-box" }} />
            </div>
            <div>
              <label style={{ fontSize:11, color:"#64748b", fontWeight:700, display:"block", marginBottom:4 }}>رقم الجوال</label>
              <input value={participantPhone} onChange={e=>setParticipantPhone(e.target.value)}
                placeholder="05xxxxxxxx"
                style={{ width:"100%", padding:"8px 10px", borderRadius:8, border:"1.5px solid #e2e8f0", fontFamily:"'Cairo',sans-serif", fontSize:13, outline:"none", boxSizing:"border-box", direction:"ltr", textAlign:"right" }} />
            </div>
          </div>
          <div style={{ marginTop:10, background:"#f8fafc", borderRadius:8, padding:"7px 12px", fontSize:11, color:"#94a3b8", display:"flex", alignItems:"center", gap:6 }}>
            🔒 هذه الاستبانة سرية ولا يطلع عليها إلا المعنيون في إدارة المدرسة
          </div>
        </div>

        {/* الأسئلة */}
        {survey.questions.map((q, idx) => (
          <div key={q.id} style={{ background:"#fff", borderRadius:12, padding:14, marginBottom:12, boxShadow:"0 2px 8px rgba(0,0,0,.06)" }}>
            <div style={{ display:"flex", alignItems:"flex-start", gap:8, marginBottom:12 }}>
              <div style={{ background:survey.color, color:"#fff", borderRadius:"50%", width:24, height:24, display:"flex", alignItems:"center", justifyContent:"center", fontSize:12, fontWeight:900, flexShrink:0 }}>{idx+1}</div>
              <div style={{ fontSize:14, fontWeight:800, color:"#1e293b", lineHeight:1.6 }}>{q.text}</div>
            </div>
            <div style={{ display:"grid", gridTemplateColumns:"repeat(5,1fr)", gap:4 }}>
              {LIKERT_OPTIONS.map((opt, oi) => {
                const selected = answers[q.id] === opt;
                return (
                  <button key={opt} onClick={()=>setAnswers(p=>({...p,[q.id]:opt}))}
                    style={{ padding:"8px 4px", borderRadius:8, border:`2px solid ${selected ? LIKERT_COLORS[oi] : "#e2e8f0"}`, background:selected ? LIKERT_COLORS[oi]+"22" : "#f8fafc", cursor:"pointer", fontFamily:"'Cairo',sans-serif", display:"flex", flexDirection:"column", alignItems:"center", gap:3, transition:"all .15s" }}>
                    <div style={{ fontSize:14 }}>{LIKERT_ICONS[oi]}</div>
                    <div style={{ fontSize:9.5, fontWeight:800, color:selected ? LIKERT_COLORS[oi] : "#64748b", textAlign:"center", lineHeight:1.3 }}>{opt}</div>
                  </button>
                );
              })}
            </div>
          </div>
        ))}

        {/* أزرار */}
        <div style={{ display:"flex", gap:10, marginTop:4 }}>
          <button onClick={handlePrint}
            style={{ flex:1, padding:"12px", borderRadius:12, border:"none", background:"#7c3aed", color:"#fff", fontWeight:900, fontSize:14, cursor:"pointer", fontFamily:"'Cairo',sans-serif" }}>
            🖨️ طباعة الاستبيان
          </button>
          <button onClick={onClose}
            style={{ padding:"12px 20px", borderRadius:12, border:"1.5px solid #e2e8f0", background:"#fff", color:"#64748b", fontWeight:700, fontSize:13, cursor:"pointer", fontFamily:"'Cairo',sans-serif" }}>
            ← رجوع
          </button>
        </div>
      </div>
    </div>
  );
}

// ================================================================
// ===== صفحة الاستبيانات الرئيسية =====
// ================================================================
function SurveysPage({ surveys: surveys0, setSurveys, saveSurveys }) {
  const surveys = svNorm(surveys0);
  const [mode, setMode]         = useState("list");
  const [editing, setEditing]   = useState(null);
  const [previewing, setPreviewing] = useState(null);

  const saveSurvey = (s) => {
    const exists = surveys.find(x=>x.id===s.id);
    const updated = exists ? surveys.map(x=>x.id===s.id?s:x) : [s,...surveys];
    setSurveys(updated); saveSurveys(updated); setMode("list"); setEditing(null);
  };
  const deleteSurvey = (id) => {
    if (!confirm("حذف هذا الاستبيان نهائياً؟")) return;
    const updated = surveys.filter(s=>s.id!==id);
    setSurveys(updated); saveSurveys(updated);
  };

  if (mode === "build") return <SurveyBuilder survey={editing||mkSurvey()} onSave={saveSurvey} onCancel={()=>{setMode("list");setEditing(null);}} />;
  if (mode === "preview" && previewing) return <SurveyRespond survey={previewing} onClose={()=>{setMode("list");setPreviewing(null);}} />;

  return (
    <div dir="rtl">
      {/* رأس الصفحة */}
      <div className="rounded-b-2xl p-6 mb-5 text-white shadow-xl" style={{ background:"linear-gradient(135deg,#1e3a5f,#1d4ed8)" }}>
        <div className="flex flex-col sm:flex-row items-center justify-between gap-4">
          <div className="text-center sm:text-right">
            <div className="text-4xl mb-1">📊</div>
            <h2 className="text-2xl font-black">الاستبيانات</h2>
            <p className="opacity-80 text-sm mt-1">إنشاء استبيانات مقياس ليكرت الخماسي وطباعتها</p>
          </div>
          <button onClick={()=>{ setEditing(null); setMode("build"); }}
            className="bg-white text-blue-800 px-5 py-2.5 rounded-xl text-sm font-bold hover:bg-blue-50 shadow">
            ➕ استبيان جديد
          </button>
        </div>
      </div>

      {/* القائمة */}
      <div className="space-y-3">
        {surveys.length === 0 && (
          <div className="text-center py-16 text-gray-400">
            <div className="text-5xl mb-3">📋</div>
            <div className="font-bold text-sm">لا توجد استبيانات بعد</div>
            <div className="text-xs mt-1">اضغط «استبيان جديد» للبدء</div>
          </div>
        )}
        {surveys.map(s => (
          <div key={s.id} className="bg-white rounded-2xl shadow-sm hover:shadow-md transition-all overflow-hidden" style={{ borderRight:`5px solid ${s.color}` }}>
            <div className="p-4">
              <div className="flex items-start justify-between gap-3">
                <div className="flex-1">
                  <h3 className="font-black text-base text-gray-800">{s.title || "استبيان بدون عنوان"}</h3>
                  <div className="flex gap-3 flex-wrap mt-1 text-xs text-gray-400">
                    <span>📅 {s.dateH} هـ</span>
                    {s.targets.length > 0 && <span>👥 {s.targets.join("، ")}</span>}
                    <span>❓ {s.questions.length} سؤال</span>
                    <span>🗓️ {s.createdAt}</span>
                  </div>
                </div>
                <div className="flex gap-1 flex-wrap justify-end">
                  <button onClick={()=>{ setPreviewing(s); setMode("preview"); }}
                    className="text-xs px-3 py-1.5 rounded-lg bg-blue-50 text-blue-700 font-bold hover:bg-blue-100">
                    👁️ معاينة
                  </button>
                  <button onClick={()=>{ setEditing(s); setMode("build"); }}
                    className="text-xs px-3 py-1.5 rounded-lg bg-amber-50 text-amber-700 font-bold hover:bg-amber-100">
                    ✏️ تعديل
                  </button>
                  <button onClick={()=>deleteSurvey(s.id)}
                    className="text-xs px-3 py-1.5 rounded-lg bg-red-50 text-red-600 font-bold hover:bg-red-100">
                    🗑️
                  </button>
                </div>
              </div>
              {/* معاينة أسئلة */}
              {s.questions.length > 0 && (
                <div className="mt-3 space-y-1">
                  {s.questions.slice(0,3).map((q,i)=>(
                    <div key={q.id} className="text-xs text-gray-500 flex gap-2">
                      <span className="font-bold" style={{color:s.color}}>{i+1}.</span>
                      <span className="truncate">{q.text||"سؤال فارغ"}</span>
                    </div>
                  ))}
                  {s.questions.length > 3 && <div className="text-xs text-gray-400">... و{s.questions.length-3} أسئلة أخرى</div>}
                </div>
              )}
            </div>
          </div>
        ))}
      </div>
    </div>
  );
}

// ═══════════════════════════════════════════════════════════════
// 🎨 استوديو التصميم — إعلان أو تقرير نشاط بالصور (لصق Ctrl+V / سحب وإفلات / تحريك / تكبير وتصغير / تدوير)
