function BroadcastPage() {
  const defaultItems = [
    { id: 1, title: "الافتتاح", icon: "🎙️", content: "بسم الله الرحمن الرحيم", type: "text" },
    { id: 2, title: "آية قرآنية", icon: "📖", content: "", type: "text" },
    { id: 3, title: "حديث شريف", icon: "🌿", content: "", type: "text" },
    { id: 4, title: "كلمة الإذاعة", icon: "🎤", content: "", type: "text" },
    { id: 5, title: "الأخبار والإعلانات", icon: "📢", content: "", type: "text" },
    { id: 6, title: "نشاط ثقافي", icon: "💡", content: "", type: "text" },
    { id: 7, title: "الخاتمة", icon: "🤲", content: "والسلام عليكم ورحمة الله وبركاته", type: "text" },
  ];
  const [items, setItems] = useState(defaultItems);
  const [date, setDate] = useState(new Date().toLocaleDateString("ar-SA-u-nu-arab", {weekday:"long", year:"numeric", month:"long", day:"numeric"}));
  const [schoolName] = useState("مدرسة الأمير عبدالمجيد المتوسطة الأولى");
  const [saved, setSaved] = useState(false);

  useEffect(() => {
    DB.get("school-broadcast", null).then(d => { if (d) setItems(d); });
  }, []);

  const save = () => {
    DB.set("school-broadcast", items);
    setSaved(true);
    setTimeout(() => setSaved(false), 2000);
  };

  const reset = () => { setItems(defaultItems); };

  const update = (id, val) => setItems(items.map(i => i.id === id ? {...i, content: val} : i));

  const print = () => {
    printWindow(`<!DOCTYPE html><html dir="rtl"><head>
      <meta charset="utf-8"/>
      <title>إذاعة المدرسة</title>
      <style>
        body { font-family: 'Segoe UI', Tahoma, sans-serif; padding: 30px; color: #1a1a1a; direction: rtl; }
        h1 { text-align: center; color: #0d9488; font-size: 22px; margin-bottom: 4px; }
        .date { text-align: center; color: #666; font-size: 13px; margin-bottom: 24px; }
        .item { margin-bottom: 20px; page-break-inside: avoid; }
        .item-title { font-size: 15px; font-weight: bold; color: #0d9488; border-right: 4px solid #0d9488; padding-right: 10px; margin-bottom: 8px; }
        .item-content { font-size: 14px; line-height: 2; background: #f8fffe; padding: 12px 16px; border-radius: 8px; white-space: pre-wrap; }
        hr { border: none; border-top: 1px dashed #ccc; margin: 20px 0; }
        @media print { body { padding: 10px; } }
      </style>
    </head><body>
      <h1>🏫 ${schoolName}</h1>
      <div class="date">إذاعة يوم ${date}</div>
      <hr/>
      ${items.map(i => `<div class="item"><div class="item-title">${i.icon} ${i.title}</div><div class="item-content">${i.content || "—"}</div></div>`).join("")}
    </body></html>`);
  };

  return (
    <div>
      <div className="page-header-bar mb-6" style={{background:"linear-gradient(135deg,#0d9488,#065f46)"}}>
        <h2 className="text-2xl font-black">🎙️ الإذاعة المدرسية</h2>
        <p className="opacity-80 text-sm mt-1">أعد محتوى الإذاعة واطبعها بسهولة</p>
      </div>
      <div className="bg-white rounded-2xl p-4 shadow-sm border border-teal-100 mb-4 flex flex-wrap gap-3 items-center justify-between">
        <div>
          <label className={cx.label}>📅 تاريخ الإذاعة</label>
          <input value={date} onChange={e => setDate(e.target.value)}
            className="px-3 py-2 rounded-xl border border-gray-200 text-sm focus:outline-none focus:border-teal-400 w-64" />
        </div>
        <div className="flex gap-2 flex-wrap">
          <button onClick={save} className="px-4 py-2 rounded-xl bg-teal-600 text-white font-bold text-sm hover:bg-teal-700">
            {saved ? "✅ تم الحفظ" : "💾 حفظ"}
          </button>
          <button onClick={print} className={cx.btn}>
            🖨️ طباعة
          </button>
          <button onClick={reset} className="px-4 py-2 rounded-xl bg-gray-100 text-gray-600 font-bold text-sm hover:bg-gray-200">
            🔄 إعادة تعيين
          </button>
        </div>
      </div>
      <div className="space-y-4">
        {items.map(item => (
          <div key={item.id} className={cx.cardSm}>
            <div className="flex items-center gap-2 px-5 py-3 bg-teal-50 border-b border-teal-100">
              <span className="text-xl">{item.icon}</span>
              <span className="font-black text-teal-800 text-sm">{item.title}</span>
            </div>
            <div className="p-4">
              <textarea value={item.content} onChange={e => update(item.id, e.target.value)}
                rows={4} placeholder={"اكتب " + item.title + " هنا..."}
                className="w-full px-4 py-3 rounded-xl border-2 border-gray-200 focus:border-teal-400 focus:outline-none text-sm resize-none leading-loose" />
            </div>
          </div>
        ))}
      </div>
    </div>
  );
}

// ===== صفحة تقسيم الطلاب لمجموعات =====
function QuizPage() {
  const [tab, setTab] = useState("create"); // create | take | results
  const [quizzes, setQuizzes] = useState([]);
  const [currentQuiz, setCurrentQuiz] = useState(null);
  const [form, setForm] = useState({ title: "", description: "", questions: [] });
  const [newQ, setNewQ] = useState({ text: "", type: "mcq", options: ["","","",""], answer: 0, points: 1 });
  const [studentName, setStudentName] = useState("");
  const [studentId, setStudentId] = useState("");
  const [answers, setAnswers] = useState({});
  const [submitted, setSubmitted] = useState(false);
  const [score, setScore] = useState(null);
  const [results, setResults] = useState([]);

  useEffect(() => {
    DB.get("school-quizzes", []).then(d => setQuizzes(Array.isArray(d) ? d : []));
    DB.get("school-quiz-results", []).then(d => setResults(Array.isArray(d) ? d : []));
  }, []);

  const saveQuizzes = (q) => { setQuizzes(q); DB.set("school-quizzes", q); };
  const saveResults = (r) => { setResults(r); DB.set("school-quiz-results", r); };

  const addQuestion = () => {
    if (!newQ.text.trim()) return;
    setForm(f => ({...f, questions: [...f.questions, {...newQ, id: Date.now()}]}));
    setNewQ({ text: "", type: "mcq", options: ["","","",""], answer: 0, points: 1 });
  };

  const saveQuiz = () => {
    if (!form.title.trim() || form.questions.length === 0) { alert("أضف عنوان الاختبار وسؤالاً على الأقل"); return; }
    const q = { ...form, id: Date.now(), createdAt: new Date().toLocaleDateString("ar-SA") };
    saveQuizzes([q, ...quizzes]);
    setForm({ title: "", description: "", questions: [] });
    alert("✅ تم حفظ الاختبار!");
  };

  const submitQuiz = () => {
    if (!studentName.trim()) { alert("أدخل اسمك"); return; }
    let total = 0, earned = 0;
    currentQuiz.questions.forEach(q => {
      total += q.points;
      if (q.type === "mcq" && answers[q.id] === q.answer) earned += q.points;
      if (q.type === "truefalse" && answers[q.id] === q.answer) earned += q.points;
    });
    const result = { id: Date.now(), quizId: currentQuiz.id, quizTitle: currentQuiz.title, studentName, studentId, earned, total, percent: Math.round(earned/total*100), date: new Date().toLocaleDateString("ar-SA") };
    saveResults([result, ...results]);
    setScore(result);
    setSubmitted(true);
  };

  const printResult = (r) => {
    printWindow(`<!DOCTYPE html><html dir="rtl"><head><meta charset="utf-8"/><title>نتيجة الاختبار</title>
    <style>body{font-family:sans-serif;padding:30px;direction:rtl;} h1{color:#0d9488;} .score{font-size:48px;font-weight:bold;text-align:center;color:${r.percent>=60?"#0d9488":"#dc2626"};}</style>
    </head><body>
    <h1>🏫 مدرسة الأمير عبدالمجيد المتوسطة الأولى</h1>
    <h2>نتيجة اختبار: ${r.quizTitle}</h2>
    <p>الطالب: <strong>${r.studentName}</strong></p>
    <p>رقم الهوية: ${r.studentId||"—"}</p>
    <div class="score">${r.percent}%</div>
    <p style="text-align:center">الدرجة: ${r.earned} من ${r.total}</p>
    <p style="text-align:center">التاريخ: ${r.date}</p>
    </body></html>`);
  };

  const tabStyle = (t) => "px-4 py-2.5 rounded-xl font-bold text-sm transition-all " + (tab===t?"bg-teal-600 text-white shadow":"bg-white text-gray-600 border border-gray-200 hover:border-teal-300");

  return (
    <div>
      <div className="page-header-bar mb-6" style={{background:"linear-gradient(135deg,#0284c7,#0369a1)"}}>
        <h2 className="text-2xl font-black">📝 اختبارات الطلاب</h2>
        <p className="opacity-80 text-sm mt-1">أنشئ اختبارات وتابع نتائج طلابك</p>
      </div>
      <div className="flex gap-2 mb-6 flex-wrap">
        <button onClick={() => setTab("create")} className={tabStyle("create")}>➕ إنشاء اختبار</button>
        <button onClick={() => { setTab("take"); setSubmitted(false); setAnswers({}); setScore(null); }} className={tabStyle("take")}>📋 أداء الاختبار</button>
        <button onClick={() => setTab("results")} className={tabStyle("results")}>📊 النتائج ({results.length})</button>
      </div>

      {tab === "create" && (
        <div className="space-y-4">
          <div className={cx.card}>
            <h3 className="font-black text-gray-800 mb-3">معلومات الاختبار</h3>
            <input value={form.title} onChange={e => setForm(f=>({...f,title:e.target.value}))} placeholder="عنوان الاختبار"
              className="w-full px-4 py-3 rounded-xl border-2 border-gray-200 focus:border-blue-400 focus:outline-none text-sm mb-2" />
            <input value={form.description} onChange={e => setForm(f=>({...f,description:e.target.value}))} placeholder="وصف أو تعليمات (اختياري)"
              className="w-full px-4 py-3 rounded-xl border-2 border-gray-200 focus:border-blue-400 focus:outline-none text-sm" />
          </div>

          {form.questions.length > 0 && (
            <div className={cx.card}>
              <h3 className="font-black text-gray-800 mb-3">الأسئلة المضافة ({form.questions.length})</h3>
              <div className="space-y-2">
                {form.questions.map((q, i) => (
                  <div key={q.id} className="flex items-center gap-2 p-3 bg-gray-50 rounded-xl text-sm">
                    <span className="font-black text-blue-600 shrink-0">{i+1}.</span>
                    <span className="flex-1 text-gray-700">{q.text}</span>
                    <span className="text-xs text-gray-400">{q.type==="mcq"?"اختيار":"صح/خطأ"} • {q.points} درجة</span>
                    <button onClick={() => setForm(f=>({...f, questions: f.questions.filter(x=>x.id!==q.id)}))} className="text-red-400 hover:text-red-600 font-bold text-xs">✕</button>
                  </div>
                ))}
              </div>
            </div>
          )}

          <div className={cx.card}>
            <h3 className="font-black text-gray-800 mb-3">إضافة سؤال جديد</h3>
            <div className="space-y-3">
              <textarea value={newQ.text} onChange={e => setNewQ(q=>({...q,text:e.target.value}))} rows={2}
                placeholder="نص السؤال" className="w-full px-4 py-3 rounded-xl border-2 border-gray-200 focus:border-blue-400 focus:outline-none text-sm resize-none" />
              <div className="flex gap-3 flex-wrap items-center">
                <div className="flex gap-2">
                  <button onClick={() => setNewQ(q=>({...q,type:"mcq"}))} className={"px-3 py-2 rounded-xl text-xs font-bold border-2 " + (newQ.type==="mcq"?"bg-blue-600 text-white border-blue-600":"bg-white text-gray-600 border-gray-200")}>اختيار متعدد</button>
                  <button onClick={() => setNewQ(q=>({...q,type:"truefalse"}))} className={"px-3 py-2 rounded-xl text-xs font-bold border-2 " + (newQ.type==="truefalse"?"bg-blue-600 text-white border-blue-600":"bg-white text-gray-600 border-gray-200")}>صح / خطأ</button>
                </div>
                <div className="flex items-center gap-2">
                  <span className="text-xs font-bold text-gray-500">الدرجة:</span>
                  <input type="number" min="1" max="10" value={newQ.points} onChange={e => setNewQ(q=>({...q,points:Number(e.target.value)}))}
                    className="w-16 px-2 py-1.5 rounded-lg border border-gray-200 text-xs text-center" />
                </div>
              </div>
              {newQ.type === "mcq" ? (
                <div className="space-y-2">
                  {newQ.options.map((opt, i) => (
                    <div key={i} className="flex items-center gap-2">
                      <button onClick={() => setNewQ(q=>({...q,answer:i}))}
                        className={"w-7 h-7 rounded-full shrink-0 border-2 font-black text-xs " + (newQ.answer===i?"bg-green-500 text-white border-green-500":"bg-white border-gray-300")}>
                        {["أ","ب","ج","د"][i]}
                      </button>
                      <input value={opt} onChange={e => { const o=[...newQ.options]; o[i]=e.target.value; setNewQ(q=>({...q,options:o})); }}
                        placeholder={"الخيار " + (i+1)}
                        className="flex-1 px-3 py-2 rounded-xl border border-gray-200 focus:border-blue-400 focus:outline-none text-sm" />
                    </div>
                  ))}
                  <p className="text-xs text-gray-400">اضغط على حرف الإجابة الصحيحة (الأخضر)</p>
                </div>
              ) : (
                <div className="flex gap-3">
                  <button onClick={() => setNewQ(q=>({...q,answer:true}))} className={"px-6 py-3 rounded-xl font-black text-sm border-2 " + (newQ.answer===true?"bg-green-500 text-white border-green-500":"bg-white text-gray-600 border-gray-200")}>✅ صح</button>
                  <button onClick={() => setNewQ(q=>({...q,answer:false}))} className={"px-6 py-3 rounded-xl font-black text-sm border-2 " + (newQ.answer===false?"bg-red-500 text-white border-red-500":"bg-white text-gray-600 border-gray-200")}>❌ خطأ</button>
                </div>
              )}
              <button onClick={addQuestion} className="w-full py-2.5 rounded-xl bg-blue-600 text-white font-bold text-sm hover:bg-blue-700">+ إضافة السؤال</button>
            </div>
          </div>

          <button onClick={saveQuiz} className="w-full py-4 rounded-2xl font-black text-white text-base" style={{background:"linear-gradient(135deg,#0284c7,#0369a1)"}}>
            💾 حفظ الاختبار
          </button>
        </div>
      )}

      {tab === "take" && (
        <div>
          {!currentQuiz ? (
            <div className="space-y-3">
              {quizzes.length === 0 && <div className={cx.empty}><div className="text-4xl mb-2">📭</div><p className="font-bold">لا توجد اختبارات بعد</p></div>}
              {quizzes.map(q => (
                <div key={q.id} className="bg-white rounded-2xl p-5 shadow-sm border border-gray-100 flex items-center justify-between gap-3 flex-wrap">
                  <div>
                    <h3 className="font-black text-gray-800">{q.title}</h3>
                    <p className="text-xs text-gray-400 mt-1">{q.questions.length} سؤال • {q.createdAt}</p>
                  </div>
                  <div className="flex gap-2">
                    <button onClick={() => { setCurrentQuiz(q); setAnswers({}); setSubmitted(false); }}
                      className={cx.btn}>ابدأ الاختبار</button>
                    <button onClick={() => { if(window.confirm("حذف الاختبار؟")) saveQuizzes(quizzes.filter(x=>x.id!==q.id)); }}
                      className="px-3 py-2 rounded-xl bg-red-50 text-red-500 font-bold text-sm hover:bg-red-100">🗑️</button>
                  </div>
                </div>
              ))}
            </div>
          ) : submitted ? (
            <div className="bg-white rounded-2xl p-8 text-center shadow-sm">
              <div className={"text-6xl mb-4"}>{score.percent >= 60 ? "🎉" : "📚"}</div>
              <h2 className="text-2xl font-black text-gray-800 mb-2">{score.percent >= 60 ? "أحسنت!" : "حاول مرة أخرى"}</h2>
              <div className={"text-5xl font-black mb-2 " + (score.percent>=60?"text-green-600":"text-red-500")}>{score.percent}%</div>
              <p className="text-gray-500 mb-1">الدرجة: <span className="font-black">{score.earned}</span> من <span className="font-black">{score.total}</span></p>
              <p className="text-gray-400 text-sm mb-6">الطالب: {score.studentName}</p>
              <div className="flex gap-2 justify-center flex-wrap">
                <button onClick={() => printResult(score)} className="px-5 py-2.5 rounded-xl bg-blue-600 text-white font-bold text-sm">🖨️ طباعة النتيجة</button>
                <button onClick={() => { setCurrentQuiz(null); setSubmitted(false); }} className="px-5 py-2.5 rounded-xl bg-gray-100 text-gray-600 font-bold text-sm">← الاختبارات</button>
              </div>
            </div>
          ) : (
            <div>
              <div className="bg-blue-50 rounded-2xl p-5 mb-5 flex flex-wrap gap-3 items-end justify-between">
                <div>
                  <h3 className="font-black text-blue-800 text-lg">{currentQuiz.title}</h3>
                  {currentQuiz.description && <p className="text-blue-600 text-sm mt-1">{currentQuiz.description}</p>}
                </div>
                <button onClick={() => setCurrentQuiz(null)} className="text-xs text-gray-500 font-bold hover:text-gray-700">← العودة</button>
              </div>
              <div className="bg-white rounded-2xl p-5 shadow-sm border border-gray-100 mb-4">
                <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
                  <div>
                    <label className="text-xs font-black text-gray-500 mb-1 block">👤 اسم الطالب</label>
                    <input value={studentName} onChange={e => setStudentName(e.target.value)} placeholder="أدخل اسمك الكامل"
                      className="w-full px-4 py-2.5 rounded-xl border-2 border-gray-200 focus:border-blue-400 focus:outline-none text-sm" />
                  </div>
                  <div>
                    <label className="text-xs font-black text-gray-500 mb-1 block">🪪 رقم الهوية (اختياري)</label>
                    <input value={studentId} onChange={e => setStudentId(e.target.value)} placeholder="رقم الهوية"
                      className="w-full px-4 py-2.5 rounded-xl border-2 border-gray-200 focus:border-blue-400 focus:outline-none text-sm" />
                  </div>
                </div>
              </div>
              <div className="space-y-4 mb-6">
                {currentQuiz.questions.map((q, i) => (
                  <div key={q.id} className={cx.card}>
                    <p className="font-black text-gray-800 mb-3"><span className="text-blue-600 ml-1">{i+1}.</span>{q.text} <span className="text-xs text-gray-400">({q.points} درجة)</span></p>
                    {q.type === "mcq" ? (
                      <div className="space-y-2">
                        {q.options.filter(Boolean).map((opt, j) => (
                          <button key={j} onClick={() => setAnswers(a=>({...a,[q.id]:j}))}
                            className={"w-full text-right px-4 py-3 rounded-xl border-2 font-bold text-sm transition-all " + (answers[q.id]===j?"bg-blue-600 text-white border-blue-600":"bg-white text-gray-700 border-gray-200 hover:border-blue-300")}>
                            <span className="font-black ml-2">{["أ","ب","ج","د"][j]}</span> {opt}
                          </button>
                        ))}
                      </div>
                    ) : (
                      <div className="flex gap-3">
                        <button onClick={() => setAnswers(a=>({...a,[q.id]:true}))} className={"flex-1 py-3 rounded-xl font-black border-2 " + (answers[q.id]===true?"bg-green-500 text-white border-green-500":"bg-white text-gray-600 border-gray-200 hover:border-green-300")}>✅ صح</button>
                        <button onClick={() => setAnswers(a=>({...a,[q.id]:false}))} className={"flex-1 py-3 rounded-xl font-black border-2 " + (answers[q.id]===false?"bg-red-500 text-white border-red-500":"bg-white text-gray-600 border-gray-200 hover:border-red-300")}>❌ خطأ</button>
                      </div>
                    )}
                  </div>
                ))}
              </div>
              <button onClick={submitQuiz} className="w-full py-4 rounded-2xl font-black text-white text-base" style={{background:"linear-gradient(135deg,#0284c7,#0369a1)"}}>
                ✅ تسليم الاختبار
              </button>
            </div>
          )}
        </div>
      )}

      {tab === "results" && (
        <div>
          <div className="flex items-center justify-between mb-4 flex-wrap gap-2">
            <h3 className="font-black text-gray-800">نتائج الطلاب ({results.length})</h3>
            {results.length > 0 && <button onClick={() => { if(window.confirm("حذف كل النتائج؟")) saveResults([]); }} className="text-xs text-red-500 font-bold px-3 py-1.5 rounded-lg bg-red-50">🗑️ حذف الكل</button>}
          </div>
          {results.length === 0 && <div className={cx.empty}><div className="text-4xl mb-2">📭</div><p className="font-bold">لا توجد نتائج بعد</p></div>}
          <div className="space-y-2">
            {results.map(r => (
              <div key={r.id} className="bg-white rounded-xl p-4 shadow-sm border border-gray-100 flex items-center gap-3 flex-wrap">
                <div className={"w-12 h-12 rounded-full flex items-center justify-center font-black text-sm text-white shrink-0 " + (r.percent>=60?"bg-green-500":"bg-red-500")}>{r.percent}%</div>
                <div className="flex-1 min-w-0">
                  <p className="font-black text-gray-800 text-sm truncate">{r.studentName}</p>
                  <p className="text-xs text-gray-400">{r.quizTitle} • {r.earned}/{r.total} • {r.date}</p>
                </div>
                <button onClick={() => printResult(r)} className="text-xs text-blue-600 font-bold px-3 py-1.5 rounded-lg bg-blue-50 hover:bg-blue-100 shrink-0">🖨️</button>
              </div>
            ))}
          </div>
        </div>
      )}
    </div>
  );
}

// ===== مؤقت الحصة =====
// ═══════════════════════════════════════════════════════════════
// عجلة السحب — تستورد أسماء المتأخرين صباحاً أو الغائبين (school-mlate / school-mattend)
// السحب عشوائي من كل الفصول، ويمكن تكراره، مع خيار عدم تكرار الاسم المسحوب
// ═══════════════════════════════════════════════════════════════
const SW_LV = [["#0f766e", "#14b8a6"], ["#1d4ed8", "#3b82f6"], ["#6d28d9", "#8b5cf6"]];
const SW_C = 260, SW_R = 228;
const swShort = n => { const p = String(n || "").trim().split(/\s+/); const s = p.length > 2 ? `${p[0]} ${p[p.length - 1]}` : p.join(" "); return s.length > 16 ? s.slice(0, 15) + "…" : s; };
const swRand = n => { try { const a = new Uint32Array(1); crypto.getRandomValues(a); return a[0] % n; } catch { return Math.floor(Math.random() * n); } };
const swShuffle = A => { const a = [...A]; for (let i = a.length - 1; i > 0; i--) { const j = swRand(i + 1); [a[i], a[j]] = [a[j], a[i]]; } return a; };
const swPt = (deg, r) => { const t = deg * Math.PI / 180; return [SW_C + r * Math.sin(t), SW_C - r * Math.cos(t)]; };
const swSlice = (s, e) => { const [x1, y1] = swPt(s, SW_R), [x2, y2] = swPt(e, SW_R); return `M${SW_C} ${SW_C}L${x1.toFixed(2)} ${y1.toFixed(2)}A${SW_R} ${SW_R} 0 ${e - s > 180 ? 1 : 0} 1 ${x2.toFixed(2)} ${y2.toFixed(2)}Z`; };
let swAC = null;
const swAudio = () => { try { const C = window.AudioContext || window.webkitAudioContext; if (!C) return null; swAC = swAC || new C(); if (swAC.state === "suspended") swAC.resume(); return swAC; } catch { return null; } };
const swTone = (f, d, len, vol, type = "sine") => { const a = swAudio(); if (!a) return; const o = a.createOscillator(), g = a.createGain(), t = a.currentTime + d; o.type = type; o.frequency.value = f; g.gain.setValueAtTime(0.0001, t); g.gain.exponentialRampToValueAtTime(vol, t + .01); g.gain.exponentialRampToValueAtTime(0.0001, t + len); o.connect(g); g.connect(a.destination); o.start(t); o.stop(t + len + .02); };
const swTick = () => swTone(1400, 0, .03, .06, "square");
const swFanfare = () => { [[523, 0], [659, .12], [784, .24], [1047, .38]].forEach(([f, d]) => swTone(f, d, .5, .2)); };
// أيام الأسبوع الدراسي (الأحد ← التاريخ المختار)
const swWeekDays = dk => { const d = maDate(dk); const out = []; for (let i = d.getDay(); i >= 0; i--) { const x = new Date(d); x.setDate(d.getDate() - i); if (x.getDay() <= 4) out.push(maKey(x)); } return out; };
async function swLoad(days) {
  const res = await Promise.all(days.flatMap(k => [maGet(`${MA_ATT}/${k}`), maGet(`${MA_LATE}/${k}`)]));
  const M = {};
  days.forEach((k, i) => {
    Object.entries(maNormDay(res[i * 2])).forEach(([ck, r]) => r.absent.forEach(x => {
      if (!x || !x.name) return; const id = String(x.id || x.name); const key = "a|" + id;
      const e = M[key] || (M[key] = { key, id, name: x.name, ck, src: "abs", n: 0 }); e.n++;
    }));
    ptVals(res[i * 2 + 1]).forEach(x => {
      if (!x.name) return; const id = String(x.id || x.name); const key = "l|" + id;
      const e = M[key] || (M[key] = { key, id, name: x.name, ck: x.ck || "", src: "late", n: 0, time: x.time, mins: +x.mins || 0 }); e.n++;
    });
  });
  return Object.values(M);
}
const swLv = x => { const l = +String(x.ck || "")[0] - 1; return l >= 0 && l < 3 ? l : -1; };

const SW_CSS = `
.sw{font-family:'Cairo','Noto Naskh Arabic',sans-serif;container-type:inline-size}
.sw *{box-sizing:border-box}
.sw-bar{display:flex;gap:10px;flex-wrap:wrap;align-items:center;background:#fff;border:1px solid #e2e8f0;border-radius:22px;padding:12px 14px;margin-bottom:14px}
.sw-grp{display:flex;gap:6px;flex-wrap:wrap;align-items:center}
.sw-grp>span{font-size:12px;font-weight:900;color:#64748b;margin-inline-end:2px}
.sw-chip{font-family:inherit;cursor:pointer;border-radius:999px;border:1.5px solid #e2e8f0;background:#fff;padding:6px 13px;font-size:13px;font-weight:900;color:#475569;display:inline-flex;gap:6px;align-items:center}
.sw-chip i{font-style:normal;background:#f1f5f9;color:#475569;border-radius:999px;padding:0 8px;font-size:12px}
.sw-chip.on{background:#06302b;border-color:#06302b;color:#fff}
.sw-chip.on i{background:#d4a017;color:#2a1d00}
.sw-chip:focus-visible,.sw-wheel:focus-visible,.sw-go:focus-visible{outline:3px solid #fbbf24;outline-offset:3px}
.sw-in{font-family:inherit;font-weight:800;font-size:13px;border:1.5px solid #e2e8f0;border-radius:12px;padding:5px 10px;color:#0f172a}
.sw-sep{width:1px;align-self:stretch;background:#e2e8f0}
.sw-main{display:grid;grid-template-columns:minmax(0,1.35fr) minmax(0,1fr);gap:14px}
.sw-stage{position:relative;border-radius:30px;padding:22px 16px 20px;overflow:hidden;color:#fff;background:radial-gradient(600px 380px at 50% 38%,#0f5c50 0%,#06302b 55%,#031c19 100%);display:flex;flex-direction:column;align-items:center;gap:16px}
.sw-wheel{position:relative;width:min(100%,540px);aspect-ratio:1;border:none;background:none;padding:0;cursor:pointer;border-radius:50%}
.sw-wheel:disabled{cursor:default}
.sw-wheel .sw-disc{width:100%;height:100%;display:block;overflow:visible;filter:drop-shadow(0 30px 40px rgba(0,0,0,.45))}
.sw-wheel .sw-ptr{position:absolute;top:-4px;left:50%;width:9%;height:auto;aspect-ratio:46/58;transform:translateX(-50%);transform-origin:50% 18%;z-index:2;filter:drop-shadow(0 6px 8px rgba(0,0,0,.5))}
.sw-wheel .sw-ptr.k{animation:swK .12s ease-out}
@keyframes swK{0%{transform:translateX(-50%) rotate(0)}40%{transform:translateX(-50%) rotate(-14deg)}100%{transform:translateX(-50%) rotate(0)}}
.sw-bulb{fill:#fde68a;opacity:.45}
.sw-run .sw-bulb{animation:swB .5s steps(1) infinite}
.sw-run .sw-bulb.b{animation-delay:.25s}
@keyframes swB{0%{opacity:1;fill:#fff7cc}50%{opacity:.3;fill:#d4a017}}
.sw-go{font-family:inherit;cursor:pointer;border:none;border-radius:18px;padding:13px 34px;font-size:18px;font-weight:900;background:linear-gradient(180deg,#fcd34d,#d4a017);color:#2a1d00;box-shadow:0 14px 26px -12px rgba(212,160,23,.9),inset 0 -3px 0 rgba(0,0,0,.15)}
.sw-go:disabled{opacity:.5;cursor:default}
.sw-leg{display:flex;gap:12px;flex-wrap:wrap;justify-content:center;font-size:12.5px;font-weight:800;opacity:.9}
.sw-leg b{display:inline-block;width:11px;height:11px;border-radius:4px;margin-inline-end:5px;vertical-align:-1px}
.sw-tools{position:absolute;top:12px;inset-inline-start:12px;display:flex;gap:6px}
.sw-t{font-family:inherit;cursor:pointer;border:1px solid rgba(255,255,255,.25);background:rgba(255,255,255,.1);color:#fff;border-radius:12px;padding:5px 10px;font-size:12.5px;font-weight:900}
.sw-side{display:grid;gap:12px;align-content:start}
.sw-win{border-radius:26px;padding:20px;text-align:center;background:#fff;border:2px solid #fcd34d;box-shadow:0 20px 40px -28px rgba(180,120,0,.8);animation:swPop .55s cubic-bezier(.2,1.5,.4,1)}
@keyframes swPop{0%{transform:scale(.6);opacity:0}100%{transform:scale(1);opacity:1}}
.sw-win small{font-size:13px;font-weight:900;color:#b45309}
.sw-win h2{margin:6px 0 8px;font-size:clamp(24px,4.6cqi,40px);font-weight:900;color:#06302b;line-height:1.3}
.sw-tag{display:inline-flex;align-items:center;gap:5px;border-radius:999px;padding:3px 12px;font-size:13px;font-weight:900;margin:2px}
.sw-wait{border-radius:26px;padding:22px;text-align:center;background:#f8fafc;border:2px dashed #e2e8f0;color:#64748b;font-weight:800}
.sw-hist{background:#fff;border:1px solid #e2e8f0;border-radius:22px;padding:12px 14px}
.sw-hr{display:grid;grid-template-columns:28px minmax(0,1fr) auto;gap:8px;align-items:center;padding:7px 0;border-bottom:1px solid #f1f5f9;font-size:13.5px;font-weight:800}
.sw-hr:last-child{border-bottom:none}
.sw-hr em{font-style:normal;width:26px;height:26px;border-radius:9px;display:grid;place-items:center;background:#fef3c7;color:#92400e;font-size:12px;font-weight:900}
.sw-conf{position:absolute;inset:0;pointer-events:none;overflow:hidden}
.sw-conf i{position:absolute;top:-14px;width:9px;height:14px;border-radius:2px;animation:swF 2.4s ease-in forwards}
@keyframes swF{to{transform:translateY(720px) rotate(720deg);opacity:0}}
.sw:fullscreen{background:#031c19;padding:16px;overflow:auto}
.sw:fullscreen .sw-main{grid-template-columns:minmax(0,1.6fr) minmax(0,1fr);min-height:calc(100vh - 32px)}
.sw:fullscreen .sw-wheel{width:min(100%,78vh)}
.sw:fullscreen .sw-bar{display:none}
@container (max-width:760px){.sw-main{grid-template-columns:1fr}.sw-sep{display:none}.sw-tools{position:static;align-self:flex-end;margin-bottom:-8px}}
@media (prefers-reduced-motion:reduce){.sw-run .sw-bulb,.sw-win,.sw-conf i,.sw-wheel .sw-ptr.k{animation:none}}
`;

// الطلاب المنضبطون: غير متكرري الغياب وقليلو التأخر الصباحي خلال فترة
const swGRange = r => { const t = maWorkDay(); const d = maDate(t); if (r === "week") { const s = new Date(d); s.setDate(d.getDate() - d.getDay()); return [maKey(s), t]; } if (r === "month") { const s = new Date(d); s.setDate(d.getDate() - 29); return [maKey(s), t]; } const y = d.getMonth() >= 7 ? d.getFullYear() : d.getFullYear() - 1; return [`${y}-08-01`, t]; };
async function swLoadGood(rng) {
  const [f, t] = swGRange(rng); const [ros, att, late] = await Promise.all([maGet(MA_ROSTER), fbRange(MA_ATT, f, t), fbRange(MA_LATE, f, t)]); const A = {}, L = {};
  Object.entries(ptObj(att)).forEach(([dk, day]) => { if (maOff(dk)) return; Object.values(ptObj(day)).forEach(r => maArr(r && r.absent).forEach(x => { if (x && x.id) A[x.id] = (A[x.id] || 0) + 1; })); });
  Object.entries(ptObj(late)).forEach(([dk, day]) => { if (maOff(dk)) return; ptVals(day).forEach(x => { if (x && x.id) L[x.id] = (L[x.id] || 0) + 1; }); });
  const out = []; Object.entries(ptObj(ros)).forEach(([ck, r]) => maArr(r && r.students).forEach(s => { if (s && s.id && s.name && !rosNewIn(s, f)) out.push({ key: "g|" + s.id, id: String(s.id), name: s.name, ck, src: "good", a: A[s.id] || 0, l: L[s.id] || 0 }); }));
  return out;
}
function StudentDrawWheel() {
  const today = maKey(new Date());
  const [dk, setDk] = useState(today);
  const [week, setWeek] = useState(false);
  const [src, setSrc] = useState("good");
  const [gRng, setGRng] = useState("month"); const [gAbs, setGAbs] = useState(1); const [gLate, setGLate] = useState(1); const [good, setGood] = useState(null);
  const [lv, setLv] = useState(-1);
  const [all, setAll] = useState(null);
  const [noRep, setNoRep] = useState(true);
  const [snd, setSnd] = useState(() => { try { return localStorage.getItem("sw_snd") !== "off"; } catch { return true; } });
  const [order, setOrder] = useState([]);
  const [win, setWin] = useState(null);
  const [spinning, setSpinning] = useState(false);
  const [conf, setConf] = useState(0);
  const histKey = src === "good" ? `sw_hist_g_${gRng}_${maWorkDay()}` : `sw_hist_${week ? "w" : "d"}_${dk}`;
  const [hist, setHist] = useState([]);
  const rot = useRef(0), gRef = useRef(null), ptrRef = useRef(null), boxRef = useRef(null), histRef = useRef([]);
  histRef.current = hist;

  useEffect(() => { let alive = true; setAll(null); setWin(null); swLoad(week ? swWeekDays(dk) : [dk]).then(r => { if (alive) setAll(r); }); return () => { alive = false; }; }, [dk, week]);
  useEffect(() => { let alive = true; setGood(null); swLoadGood(gRng).then(r => { if (alive) setGood(r); }).catch(() => alive && setGood([])); return () => { alive = false; }; }, [gRng]);
  useEffect(() => { try { setHist(JSON.parse(localStorage.getItem(histKey) || "[]")); } catch { setHist([]); } }, [histKey]);
  const saveHist = h => { setHist(h); try { localStorage.setItem(histKey, JSON.stringify(h.slice(0, 200))); } catch {} };

  // المصدر + الصف (الغائب والمتأخر نفسه يظهر مرة واحدة في «الكل»)
  const goodF = (good || []).filter(x => x.a <= gAbs && x.l <= gLate && (lv < 0 || swLv(x) === lv));
  const filtered = src === "good" ? goodF : (all || []).filter(x => (src === "all" || x.src === src) && (lv < 0 || swLv(x) === lv))
    .filter((x, i, A) => src !== "all" || A.findIndex(y => y.id === x.id) === i);
  const cnt = s => s === "good" ? goodF.length : (all || []).filter(x => (s === "all" || x.src === s) && (lv < 0 || swLv(x) === lv)).filter((x, i, A) => s !== "all" || A.findIndex(y => y.id === x.id) === i).length;
  const sig = filtered.map(x => x.key).join(",") + "|" + noRep;
  useEffect(() => {
    if (spinning) return;
    let H = []; try { H = JSON.parse(localStorage.getItem(histKey) || "[]"); } catch {}
    const drawn = new Set(H.map(h => h.id));
    setOrder(swShuffle(noRep ? filtered.filter(x => !drawn.has(x.id)) : filtered)); setWin(null);
  }, [sig, histKey]);

  const spin = () => {
    if (spinning) return;
    let L = order; if (noRep && win) L = order.filter(x => x.key !== win.key);
    if (!L.length) return;
    if (L !== order) setOrder(L);
    setWin(null); setSpinning(true); swAudio();
    const n = L.length, a = 360 / n, i = swRand(n);
    const jit = (Math.random() - .5) * a * .6;
    const cur = rot.current;
    const want = ((360 - ((i + .5) * a + jit)) % 360 + 360) % 360;
    let target = cur - (cur % 360) + 360 * 7 + want; if (target - cur < 360 * 6) target += 360;
    const reduced = window.matchMedia && window.matchMedia("(prefers-reduced-motion: reduce)").matches;
    const dur = reduced ? 1200 : 6000 + Math.random() * 900;
    const t0 = performance.now(); let last = -1;
    const step = now => {
      const p = Math.min(1, (now - t0) / dur), e = 1 - Math.pow(1 - p, 4);
      const R = cur + (target - cur) * e; rot.current = R;
      if (gRef.current) gRef.current.setAttribute("transform", `rotate(${R.toFixed(3)} ${SW_C} ${SW_C})`);
      const idx = Math.floor((((360 - R % 360) % 360) + 360) % 360 / a) % n;
      if (idx !== last) { last = idx; if (snd && n > 1) swTick(); const el = ptrRef.current; if (el) { el.classList.remove("k"); void el.getBoundingClientRect(); el.classList.add("k"); } }
      if (p < 1) { requestAnimationFrame(step); return; }
      const w = L[i];
      setWin(w); setSpinning(false); setConf(c => c + 1);
      saveHist([{ id: w.id, key: w.key, name: w.name, ck: w.ck, src: w.src, time: w.time || "", at: Date.now() }, ...histRef.current]);
      if (snd) swFanfare();
    };
    requestAnimationFrame(step);
  };
  const reset = () => { if (hist.length && !window.confirm("مسح سجل السحب لهذا اليوم وإرجاع كل الأسماء للعجلة؟")) return; saveHist([]); setOrder(swShuffle(filtered)); setWin(null); };
  const full = () => { try { if (document.fullscreenElement) document.exitFullscreen(); else boxRef.current && boxRef.current.requestFullscreen(); } catch {} };
  const toggleSnd = () => { const v = !snd; setSnd(v); try { localStorage.setItem("sw_snd", v ? "on" : "off"); } catch {} };

  const n = order.length, a = n ? 360 / n : 360;
  const showTxt = n <= 48, fs = n <= 8 ? 19 : n <= 14 ? 16 : n <= 24 ? 13 : n <= 36 ? 10.5 : 8.5;
  const bulbs = Array.from({ length: 28 }, (_, k) => swPt(k * 360 / 28, SW_R + 14));
  const ready = src === "good" ? !!good : !!all;
  const empty = ready && !filtered.length;
  const srcL = { good: "الطلاب المنضبطين", late: "المتأخرين صباحاً", abs: "الغائبين", all: "المتأخرين والغائبين" }[src];
  const gLbl = { week: "هذا الأسبوع", month: "آخر ٣٠ يوماً", term: "منذ بداية العام" }[gRng];

  return <div className="sw" dir="rtl" ref={boxRef}><style>{SW_CSS}</style>
    <div className="sw-bar">
      <div className="sw-grp"><span>الأسماء من</span>
        {[["good", "🌟 المنضبطون"], ["late", "🌅 المتأخرون صباحاً"], ["abs", "🚫 الغائبون"], ["all", "الاثنان معاً"]].map(([k, l]) => <button key={k} className={`sw-chip ${src === k ? "on" : ""}`} onClick={() => setSrc(k)} aria-pressed={src === k}>{l}<i>{(k === "good" ? good : all) ? maAr(cnt(k)) : "…"}</i></button>)}
      </div>
      <div className="sw-sep" />
      <div className="sw-grp"><span>الصف</span>
        <button className={`sw-chip ${lv < 0 ? "on" : ""}`} onClick={() => setLv(-1)}>كل الفصول</button>
        {MA_LV.map((L, k) => <button key={k} className={`sw-chip ${lv === k ? "on" : ""}`} onClick={() => setLv(k)}>{L.s} متوسط</button>)}
      </div>
      <div className="sw-sep" />
      {src === "good" ? <div className="sw-grp"><span>الفترة</span>{[["week", "هذا الأسبوع"], ["month", "آخر ٣٠ يوماً"], ["term", "منذ بداية العام"]].map(([k, l]) => <button key={k} className={`sw-chip ${gRng === k ? "on" : ""}`} onClick={() => setGRng(k)}>{l}</button>)}
        <span style={{ marginInlineStart: 6 }}>غياب ≤</span>{[0, 1, 2, 3].map(n => <button key={"a" + n} className={`sw-chip ${gAbs === n ? "on" : ""}`} style={{ padding: "4px 10px" }} onClick={() => setGAbs(n)}>{maAr(n)}</button>)}
        <span style={{ marginInlineStart: 6 }}>تأخر ≤</span>{[0, 1, 2, 3].map(n => <button key={"l" + n} className={`sw-chip ${gLate === n ? "on" : ""}`} style={{ padding: "4px 10px" }} onClick={() => setGLate(n)}>{maAr(n)}</button>)}</div> : <>
      <div className="sw-grp"><span>اليوم</span>
        <input type="date" className="sw-in" value={dk} max={today} onChange={e => e.target.value && setDk(e.target.value)} />
        {dk !== today && <button className="sw-chip" onClick={() => setDk(today)}>اليوم</button>}
        <button className={`sw-chip ${week ? "on" : ""}`} onClick={() => setWeek(!week)} aria-pressed={week}>📅 الأسبوع كامل</button>
      </div></>}
      <div className="sw-grp" style={{ marginInlineStart: "auto" }}>
        <button className={`sw-chip ${noRep ? "on" : ""}`} onClick={() => setNoRep(!noRep)} aria-pressed={noRep}>{noRep ? "✓ لا يتكرر الاسم" : "يمكن تكرار الاسم"}</button>
      </div>
    </div>

    <div className="sw-main">
      <div className={`sw-stage ${spinning ? "sw-run" : ""}`}>
        <div className="sw-tools">
          <button className="sw-t" onClick={toggleSnd} aria-pressed={snd}>{snd ? "🔊" : "🔇"}</button>
          <button className="sw-t" onClick={full}>⛶ ملء الشاشة</button>
        </div>
        <div style={{ textAlign: "center" }}>
          <div style={{ fontSize: 20, fontWeight: 900 }}>🎡 عجلة السحب</div>
          <div style={{ fontSize: 13, fontWeight: 800, opacity: .8 }}>{srcL} • {src === "good" ? `${gLbl} • غياب ≤ ${maAr(gAbs)} • تأخر ≤ ${maAr(gLate)}` : <>{week ? `الأسبوع حتى ${maDay(maDate(dk))}` : dk === today ? "اليوم" : maDay(maDate(dk))} {asmHij(maDate(dk))}</>} • في العجلة {maAr(n)} اسم</div>
        </div>
        <button className="sw-wheel" onClick={spin} disabled={spinning || !n} aria-label="أدر العجلة">
          <svg ref={ptrRef} className="sw-ptr" viewBox="0 0 46 58" aria-hidden="true"><path d="M23 56 L4 14 A20 20 0 1 1 42 14 Z" fill="#d4a017" stroke="#fff7cc" strokeWidth="3" /><circle cx="23" cy="18" r="7" fill="#fff7cc" /></svg>
          <svg className="sw-disc" viewBox="0 0 520 520" aria-hidden="true">
            <circle cx={SW_C} cy={SW_C} r={SW_R + 24} fill="#d4a017" />
            <circle cx={SW_C} cy={SW_C} r={SW_R + 6} fill="#7a5a06" />
            {bulbs.map(([x, y], k) => <circle key={k} cx={x} cy={y} r="5" className={`sw-bulb ${k % 2 ? "b" : ""}`} />)}
            <g ref={gRef} transform={`rotate(${rot.current} ${SW_C} ${SW_C})`}>
              {!n ? <circle cx={SW_C} cy={SW_C} r={SW_R} fill="#0b3d36" /> : n === 1 ? <circle cx={SW_C} cy={SW_C} r={SW_R} fill={SW_LV[Math.max(0, swLv(order[0]))][1]} /> :
                order.map((x, k) => { const l = swLv(x); const pal = l < 0 ? ["#475569", "#64748b"] : SW_LV[l]; return <path key={x.key} d={swSlice(k * a, (k + 1) * a)} fill={pal[k % 2]} stroke="rgba(255,255,255,.55)" strokeWidth={n > 60 ? .5 : 1.5} />; })}
              {showTxt && order.map((x, k) => <g key={"t" + x.key} transform={`rotate(${(k + .5) * a} ${SW_C} ${SW_C})`}>
                <text x={SW_C} y={SW_C - SW_R * .6} transform={`rotate(-90 ${SW_C} ${SW_C - SW_R * .6})`} textAnchor="middle" dominantBaseline="central" fill="#fff" fontFamily="Cairo, sans-serif" fontWeight="800" fontSize={fs}>{swShort(x.name)}</text>
              </g>)}
            </g>
            <circle cx={SW_C} cy={SW_C} r="58" fill="#fff" stroke="#d4a017" strokeWidth="6" />
            <image href={SCHOOL_LOGO} x={SW_C - 50} y={SW_C - 50} width="100" height="100" />
          </svg>
        </button>
        <button className="sw-go" onClick={spin} disabled={spinning || !n}>{spinning ? "تدور…" : win ? "🎡 اسحب مرة أخرى" : "🎡 أدِر العجلة"}</button>
        <div className="sw-leg">{MA_LV.map((L, k) => <span key={k}><b style={{ background: SW_LV[k][1] }} />{L.n}</span>)}</div>
        {conf > 0 && win && <div className="sw-conf" key={conf}>{Array.from({ length: 36 }, (_, k) => <i key={k} style={{ left: `${(k * 37) % 100}%`, background: ["#fcd34d", "#14b8a6", "#3b82f6", "#8b5cf6", "#f472b6", "#fff"][k % 6], animationDelay: `${(k % 9) * .08}s` }} />)}</div>}
      </div>

      <div className="sw-side">
        {win ? <div className="sw-win" key={win.key + conf}>
          <small>🎉 وقعت العجلة على</small>
          <h2>{win.name}</h2>
          <div>
            {win.ck && <span className="sw-tag" style={{ background: "#ecfdf5", color: "#065f46" }}>🚪 {maClassName(win.ck)}</span>}
            {win.src === "good" ? <span className="sw-tag" style={{ background: "#dcfce7", color: "#15803d" }}>🌟 منضبط • غياب {maAr(win.a)} • تأخر {maAr(win.l)} ({gLbl})</span> : win.src === "late" ? <span className="sw-tag" style={{ background: "#ffedd5", color: "#9a3412" }}>🌅 متأخر{win.time ? ` — ${mlFmtT(win.time)}` : ""}{win.n > 1 ? ` • ${maAr(win.n)} مرات` : ""}</span>
              : <span className="sw-tag" style={{ background: "#fee2e2", color: "#b91c1c" }}>🚫 غائب{win.n > 1 ? ` • ${maAr(win.n)} أيام` : ""}</span>}
          </div>
        </div> : <div className="sw-wait">
          {!ready ? "جارٍ تحميل الأسماء…" : empty ? <>لا يوجد {srcL} {src === "good" ? gLbl : week ? "هذا الأسبوع" : "في هذا اليوم"}{lv >= 0 ? ` في ${MA_LV[lv].n}` : ""}.<div style={{ fontSize: 13, marginTop: 6 }}>غيّر المصدر أو التاريخ، أو فعّل «الأسبوع كامل».</div></>
            : !n ? <>سُحبت كل الأسماء ({maAr(filtered.length)}).<div style={{ marginTop: 10 }}><button className="sw-chip on" onClick={reset}>↺ أرجع كل الأسماء</button></div></>
              : spinning ? "العجلة تدور…" : <>اضغط على العجلة أو زر «أدِر العجلة».<div style={{ fontSize: 13, marginTop: 6 }}>السحب عشوائي من كل الفصول.</div></>}
        </div>}

        <div className="sw-hist">
          <div className="flex items-center gap-2" style={{ marginBottom: 6 }}>
            <b style={{ fontSize: 14.5 }}>📜 سجل السحب</b>
            <span className="sw-tag" style={{ background: "#f1f5f9", color: "#475569" }}>{maAr(hist.length)}</span>
            {hist.length > 0 && <button className="sw-chip" style={{ marginInlineStart: "auto", padding: "3px 10px", fontSize: 12 }} onClick={reset}>↺ مسح السجل</button>}
          </div>
          {hist.length ? hist.slice(0, 30).map((h, k) => <div key={h.at} className="sw-hr">
            <em>{maAr(hist.length - k)}</em>
            <span style={{ minWidth: 0, overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap" }}>{h.name} <small style={{ color: "#94a3b8" }}>{h.ck ? `• ${sttCk(h.ck)}` : ""} • {h.src === "good" ? "منضبط" : h.src === "late" ? "متأخر" : "غائب"}</small></span>
            <small style={{ color: "#94a3b8", fontWeight: 800 }}>{new Date(h.at).toLocaleTimeString("ar-SA", { hour: "2-digit", minute: "2-digit" })}</small>
          </div>) : <div style={{ fontSize: 13, fontWeight: 800, color: "#94a3b8", padding: "8px 0" }}>لم يُسحب أي اسم بعد.</div>}
        </div>
      </div>
    </div>
  </div>;
}

function LuckyWheelPage() {
  const [tab, setTab] = useState(() => { try { return localStorage.getItem("lw_tab") || "draw"; } catch { return "draw"; } });
  const go = t => { setTab(t); try { localStorage.setItem("lw_tab", t); } catch {} };
  return <div dir="rtl">
    <div className="flex gap-2 flex-wrap mb-4" style={{ fontFamily: "'Cairo',sans-serif" }}>
      {[["draw", "🎡 سحب للطلاب المنضبطين"], ["manual", "✍️ عجلة بأسماء يدوية"]].map(([k, l]) => <button key={k} onClick={() => go(k)} style={{ fontFamily: "inherit", cursor: "pointer", borderRadius: 999, padding: "8px 18px", fontWeight: 900, fontSize: 14, border: tab === k ? "none" : "1.5px solid #e2e8f0", background: tab === k ? "#06302b" : "#fff", color: tab === k ? "#fff" : "#475569" }}>{l}</button>)}
    </div>
    {tab === "draw" ? <StudentDrawWheel /> : <LuckyWheelManual />}
  </div>;
}


// العجلة اليدوية الأصلية (محفوظة كما هي — تبويب «عجلة بأسماء يدوية»)
function LuckyWheelManual() {
  const [names, setNames] = useState("");
  const [spinning, setSpinning] = useState(false);
  const [winner, setWinner] = useState(null);
  const [angle, setAngle] = useState(0);
  const [history, setHistory] = useState([]);
  const canvasRef = useRef(null);
  const colors = ["#0d9488","#2563eb","#7c3aed","#db2777","#d97706","#059669","#dc2626","#0284c7","#65a30d","#9333ea"];

  const nameList = names.split("\n").map(n=>n.trim()).filter(Boolean);

  const drawWheel = (rot) => {
    const canvas = canvasRef.current;
    if (!canvas || nameList.length === 0) return;
    const ctx = canvas.getContext("2d");
    const cx = canvas.width / 2, cy = canvas.height / 2, r = cx - 10;
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    const slice = (2 * Math.PI) / nameList.length;
    nameList.forEach((name, i) => {
      const start = rot + i * slice, end = start + slice;
      ctx.beginPath(); ctx.moveTo(cx, cy);
      ctx.arc(cx, cy, r, start, end);
      ctx.fillStyle = colors[i % colors.length];
      ctx.fill();
      ctx.strokeStyle = "white"; ctx.lineWidth = 2; ctx.stroke();
      ctx.save(); ctx.translate(cx, cy); ctx.rotate(start + slice / 2);
      ctx.textAlign = "right"; ctx.fillStyle = "white";
      ctx.font = `bold ${Math.min(14, 100/nameList.length + 8)}px sans-serif`;
      ctx.fillText(name.length > 10 ? name.substring(0,10)+"…" : name, r - 10, 5);
      ctx.restore();
    });
    // المؤشر
    ctx.beginPath(); ctx.moveTo(cx + r - 5, cy);
    ctx.lineTo(cx + r + 20, cy - 10); ctx.lineTo(cx + r + 20, cy + 10);
    ctx.fillStyle = "#1f2937"; ctx.fill();
  };

  useEffect(() => { drawWheel(angle * Math.PI / 180); }, [names, angle]);

  const spin = () => {
    if (spinning || nameList.length === 0) return;
    setSpinning(true); setWinner(null);
    const extra = 1800 + Math.random() * 1800;
    const target = angle + extra;
    const slice = 360 / nameList.length;
    const finalAngle = target % 360;
    const winIdx = Math.floor(((360 - finalAngle) % 360) / slice) % nameList.length;
    let start = null;
    const animate = (ts) => {
      if (!start) start = ts;
      const elapsed = ts - start, duration = 4000;
      const progress = Math.min(elapsed / duration, 1);
      const ease = 1 - Math.pow(1 - progress, 4);
      const cur = angle + extra * ease;
      setAngle(cur);
      drawWheel((cur * Math.PI) / 180);
      if (progress < 1) requestAnimationFrame(animate);
      else {
        setSpinning(false);
        const w = nameList[winIdx];
        setWinner(w);
        setHistory(h => [{ name: w, time: new Date().toLocaleTimeString("ar-SA") }, ...h.slice(0,9)]);
      }
    };
    requestAnimationFrame(animate);
  };

  const handleExcel = (e) => {
    const file = e.target.files[0]; if (!file) return;
    readFileAsync(file, "text").then(ev => { const lines = ev.split("\n").map(l=>l.split(",")[0].trim()).filter(Boolean); setNames(lines.join("\n")); });
  };

  return (
    <div>
      <div className="page-header-bar mb-6" style={{background:"linear-gradient(135deg,#7c3aed,#db2777)"}}>
        <h2 className="text-2xl font-black">🎯 عجلة الحظ</h2>
        <p className="opacity-80 text-sm mt-1">اختر طالباً عشوائياً بطريقة ممتعة</p>
      </div>
      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
        <div>
          <div className="bg-white rounded-2xl p-5 shadow-sm border border-gray-100 mb-4">
            <label className="text-sm font-black text-gray-700 mb-2 block">📋 أسماء الطلاب</label>
            <textarea value={names} onChange={e => setNames(e.target.value)} rows={10}
              placeholder={"أحمد محمد\nسلطان علي\nعمر خالد\n..."}
              className="w-full px-4 py-3 rounded-xl border-2 border-gray-200 focus:border-purple-400 focus:outline-none text-sm resize-none mb-2" />
            <label className="flex items-center gap-2 cursor-pointer text-sm font-bold text-purple-600">
              📥 استيراد من Excel
              <input type="file" accept=".csv,.txt" className="hidden" onChange={handleExcel} />
            </label>
          </div>
          {history.length > 0 && (
            <div className="bg-white rounded-2xl p-4 shadow-sm border border-gray-100">
              <h3 className="font-black text-gray-700 text-sm mb-3">📜 سجل الاختيارات</h3>
              <div className="space-y-1">
                {history.map((h,i) => (
                  <div key={i} className="flex items-center justify-between text-sm px-3 py-1.5 bg-gray-50 rounded-lg">
                    <span className="font-bold text-gray-700">🏆 {h.name}</span>
                    <span className="text-xs text-gray-400">{h.time}</span>
                  </div>
                ))}
              </div>
            </div>
          )}
        </div>
        <div className="text-center">
          <div className="relative inline-block mb-4">
            <canvas ref={canvasRef} width={300} height={300} className="rounded-full shadow-2xl cursor-pointer" onClick={spin} />
            {nameList.length === 0 && (
              <div className="absolute inset-0 flex items-center justify-center bg-gray-100 rounded-full">
                <p className="text-gray-400 font-bold text-sm">أضف الأسماء أولاً</p>
              </div>
            )}
          </div>
          {winner && (
            <div className="bg-gradient-to-l from-purple-600 to-pink-600 rounded-2xl p-5 text-white mb-4 animate-pulse">
              <div className="text-3xl mb-1">🎉</div>
              <p className="text-xl font-black">{winner}</p>
              <p className="text-sm opacity-80 mt-1">الطالب المختار</p>
            </div>
          )}
          <button onClick={spin} disabled={spinning || nameList.length === 0}
            className={"w-full py-4 rounded-2xl font-black text-white text-lg transition-all " + (spinning||nameList.length===0?"opacity-40 cursor-not-allowed":"hover:shadow-xl")}
            style={{background:"linear-gradient(135deg,#7c3aed,#db2777)"}}>
            {spinning ? "🌀 جاري الدوران..." : "🎯 أدِر العجلة!"}
          </button>
        </div>
      </div>
    </div>
  );
}

// ===== بطاقة الخروج =====
function TimetablePage({ teachers }) {
  const days = ["الأحد","الإثنين","الثلاثاء","الأربعاء","الخميس"];
  const periods = [1,2,3,4,5,6,7,8];
  const [timetable, setTimetable] = useState({});
  const [selectedTeacher, setSelectedTeacher] = useState("الكل");

  useEffect(() => {
    DB.get("school-timetable", {}).then(d => setTimetable(d||{}));
  }, []);

  const save = (t) => { setTimetable(t); DB.set("school-timetable", t); };

  const update = (day, period, value) => {
    const t = { ...timetable, [`${day}-${period}`]: value };
    save(t);
  };

  const print = () => {
    printWindow(`<!DOCTYPE html><html dir="rtl"><head><meta charset="utf-8"/><title>جدول الحصص</title>
    <style>body{font-family:sans-serif;direction:rtl;padding:20px;font-size:12px;} h1{color:#0d9488;text-align:center;} table{width:100%;border-collapse:collapse;margin-top:16px;} th,td{border:1px solid #ccc;padding:8px 6px;text-align:center;} th{background:#0d9488;color:white;font-size:11px;} td{font-size:11px;} .period{background:#f0fdfa;font-weight:bold;}</style>
    </head><body><h1>🏫 جدول الحصص الأسبوعي — مدرسة الأمير عبدالمجيد المتوسطة الأولى</h1>
    <table><tr><th>الحصة</th>${days.map(d=>`<th>${d}</th>`).join("")}</tr>
    ${periods.map(p=>`<tr><td class="period">الحصة ${p}</td>${days.map(d=>`<td>${timetable[d+"-"+p]||""}</td>`).join("")}</tr>`).join("")}
    </table></body></html>`);
  };

  return (
    <div>
      <div className="page-header-bar mb-6" style={{background:"linear-gradient(135deg,#0369a1,#1e3a5f)"}}>
        <h2 className="text-2xl font-black">🗓️ جدول الحصص الأسبوعي</h2>
        <p className="opacity-80 text-sm mt-1">جدول أسبوعي قابل للتعديل والطباعة</p>
      </div>
      <div className="flex items-center justify-between mb-4 flex-wrap gap-2">
        <p className="text-sm text-gray-500 font-bold">اضغط على أي خانة لتعديلها</p>
        <button onClick={print} className={cx.btn}>🖨️ طباعة الجدول</button>
      </div>
      <div className="overflow-x-auto">
        <table className="w-full text-sm border-collapse bg-white rounded-2xl overflow-hidden shadow-sm">
          <thead>
            <tr>
              <th className="px-3 py-3 text-white text-xs font-black" style={{background:"#0d9488"}}>الحصة</th>
              {days.map(d => <th key={d} className="px-3 py-3 text-white text-xs font-black" style={{background:"#0d9488"}}>{d}</th>)}
            </tr>
          </thead>
          <tbody>
            {periods.map(p => (
              <tr key={p} className={p%2===0?"bg-gray-50":""}>
                <td className="px-3 py-2 text-center font-black text-teal-700 text-xs border border-gray-100">{p}</td>
                {days.map(d => (
                  <td key={d} className="border border-gray-100 p-1">
                    <input value={timetable[`${d}-${p}`]||""} onChange={e => update(d,p,e.target.value)}
                      placeholder="المادة / المعلم"
                      className="w-full px-2 py-1.5 rounded-lg text-xs focus:outline-none focus:bg-teal-50 bg-transparent hover:bg-gray-50 transition-all text-center" />
                  </td>
                ))}
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </div>
  );
}

// ===== سجل الزيارات الصفية =====
function HonorBoardPage({ classList }) {
  const [honorStudents, setHonorStudents] = useState([]);
  const [form, setForm] = useState({ name:"", class:"", reason:"", badge:"🏆" });
  const [showForm, setShowForm] = useState(false);
  const badges = ["🏆","⭐","🥇","🎖️","🌟","💎","🔥","👑","🎯","✨"];

  useEffect(() => {
    DB.get("school-honor-board", []).then(d => setHonorStudents(Array.isArray(d)?d:[]));
  }, []);

  const save = (v) => { setHonorStudents(v); DB.set("school-honor-board", v); };

  const add = () => {
    if (!form.name.trim()) { alert("أدخل اسم الطالب"); return; }
    save([{ ...form, id: Date.now(), date: new Date().toLocaleDateString("ar-SA") }, ...honorStudents]);
    setForm({ name:"", class:"", reason:"", badge:"🏆" }); setShowForm(false);
  };

  const print = () => {
    printWindow(`<!DOCTYPE html><html dir="rtl"><head><meta charset="utf-8"/><title>لوحة الشرف</title>
    <style>body{font-family:sans-serif;direction:rtl;padding:30px;text-align:center;background:#fffbeb;} h1{color:#0d9488;font-size:22px;margin-bottom:4px;} .grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(180px,1fr));gap:16px;margin-top:24px;} .card{background:white;border:2px solid #fde68a;border-radius:12px;padding:16px;} .badge{font-size:36px;} .name{font-weight:bold;font-size:14px;margin:8px 0 4px;} .class{font-size:12px;color:#666;} .reason{font-size:11px;color:#0d9488;margin-top:6px;}</style>
    </head><body>
    <h1>🏫 لوحة الشرف</h1><p style="color:#666;font-size:13px;">مدرسة الأمير عبدالمجيد المتوسطة الأولى</p>
    <div class="grid">${honorStudents.map(s=>`<div class="card"><div class="badge">${s.badge}</div><div class="name">${s.name}</div><div class="class">${s.class}</div><div class="reason">${s.reason||""}</div></div>`).join("")}</div>
    </body></html>`);
  };

  return (
    <div>
      <div className="page-header-bar mb-6" style={{background:"linear-gradient(135deg,#d97706,#b45309)"}}>
        <h2 className="text-2xl font-black">🏆 لوحة الشرف</h2>
        <p className="opacity-80 text-sm mt-1">كرّم طلابك المتميزين</p>
      </div>
      <div className="flex justify-between items-center mb-4 flex-wrap gap-2">
        <span className="text-sm font-bold text-gray-500">{honorStudents.length} طالب متميز</span>
        <div className="flex gap-2">
          {honorStudents.length>0 && <button onClick={print} className="px-4 py-2 rounded-xl bg-blue-600 text-white font-bold text-sm">🖨️ طباعة</button>}
          <button onClick={() => setShowForm(!showForm)} className="px-4 py-2 rounded-xl bg-amber-600 text-white font-bold text-sm hover:bg-amber-700">
            {showForm?"✕ إلغاء":"+ إضافة طالب"}
          </button>
        </div>
      </div>
      {showForm && (
        <div className="bg-white rounded-2xl p-5 shadow-sm border border-amber-100 mb-5">
          <div className="grid grid-cols-1 sm:grid-cols-2 gap-3 mb-3">
            <input value={form.name} onChange={e => setForm(f=>({...f,name:e.target.value}))} placeholder="اسم الطالب"
              className="w-full px-4 py-3 rounded-xl border-2 border-gray-200 focus:border-amber-400 focus:outline-none text-sm" />
            <input value={form.class} onChange={e => setForm(f=>({...f,class:e.target.value}))} placeholder="الفصل"
              className="w-full px-4 py-3 rounded-xl border-2 border-gray-200 focus:border-amber-400 focus:outline-none text-sm" />
          </div>
          <input value={form.reason} onChange={e => setForm(f=>({...f,reason:e.target.value}))} placeholder="سبب التكريم (اختياري)"
            className="w-full px-4 py-3 rounded-xl border-2 border-gray-200 focus:border-amber-400 focus:outline-none text-sm mb-3" />
          <div className="flex gap-2 flex-wrap mb-3">
            {badges.map(b => (
              <button key={b} onClick={() => setForm(f=>({...f,badge:b}))}
                className={"text-2xl p-2 rounded-xl border-2 transition-all " + (form.badge===b?"border-amber-400 bg-amber-50":"border-transparent hover:border-gray-200")}>
                {b}
              </button>
            ))}
          </div>
          <button onClick={add} className="w-full py-3 rounded-2xl bg-amber-600 text-white font-black hover:bg-amber-700">✨ إضافة للوحة الشرف</button>
        </div>
      )}
      {honorStudents.length === 0 && !showForm && <div className={cx.empty}><div className="text-5xl mb-2">🏆</div><p className="font-bold">لوحة الشرف فارغة</p></div>}
      <div className="grid grid-cols-2 sm:grid-cols-3 lg:grid-cols-4 xl:grid-cols-5 gap-4">
        {honorStudents.map(s => (
          <div key={s.id} className="bg-white rounded-2xl p-4 text-center shadow-sm border-2 border-amber-200 hover:shadow-md transition-all relative group">
            <button onClick={() => save(honorStudents.filter(x=>x.id!==s.id))} className="absolute top-2 left-2 text-xs text-red-400 opacity-0 group-hover:opacity-100 font-bold">✕</button>
            <div className="text-4xl mb-2">{s.badge}</div>
            <p className="font-black text-gray-800 text-sm">{s.name}</p>
            <p className="text-xs text-gray-400 mt-0.5">{s.class}</p>
            {s.reason && <p className="text-xs text-teal-600 mt-1 font-bold">{s.reason}</p>}
            <p className="text-xs text-gray-300 mt-1">{s.date}</p>
          </div>
        ))}
      </div>
    </div>
  );
}

// ===== تتبع المهام =====
function AbsenceStatsPage({ teachers, attendance, week, weekArchive }) {
  const [selectedTeacher, setSelectedTeacher] = useState(null);
  const [viewMode, setViewMode] = useState("overview"); // overview | teacher

  // دمج كل الأسابيع (الحالي + المؤرشفة)
  const allWeeks = [
    { id: "current", week, attendance, label: weekLabel(week) + " (الحالي)" },
    ...(weekArchive || []).map(w => ({ id: w.id, week: w.week, attendance: w.attendance, label: weekLabel(w.week) }))
  ];

  // حساب إحصائيات كل معلم عبر كل الأسابيع
  const teacherStats = teachers.map((name, ti) => {
    let totalDays = 0, absent = 0, lateMorn = 0, latePeriod = 0, lateMins = 0;
    const weeklyData = [];

    allWeeks.forEach(({ week: w, attendance: att, label }) => {
      let wAbsent=0, wLateMorn=0, wLatePeriod=0, wPresent=0, wMins=0;
      w.days.forEach((day, di) => {
        const r = att[ti]?.[di] || {};
        const st = r.status || "حاضر";
        totalDays++;
        if (st === "غائب") { absent++; wAbsent++; }
        else if (st === "متأخر") {
          const mins = parseInt(r.lateMinutes) || 0;
          lateMins += mins; wMins += mins;
          if (r.lateType === "حصص") { latePeriod++; wLatePeriod++; }
          else { lateMorn++; wLateMorn++; }
        } else { wPresent++; }
      });
      weeklyData.push({ label, absent: wAbsent, late: wLateMorn+wLatePeriod, present: wPresent, days: w.days.length });
    });

    const present = totalDays - absent - lateMorn - latePeriod;
    const rate = totalDays > 0 ? Math.round((present / totalDays) * 100) : 100;
    return { name, totalDays, absent, lateMorn, latePeriod, lateMins, present, rate, weeklyData };
  }).sort((a,b) => a.rate - b.rate);

  const totalAbsences = teacherStats.reduce((s,t)=>s+t.absent,0);
  const totalLate = teacherStats.reduce((s,t)=>s+t.lateMorn+t.latePeriod,0);
  const avgRate = teacherStats.length > 0 ? Math.round(teacherStats.reduce((s,t)=>s+t.rate,0)/teacherStats.length) : 100;
  const topPerformers = [...teacherStats].sort((a,b)=>b.rate-a.rate).slice(0,3);
  const atRisk = teacherStats.filter(t=>t.absent>=3||t.rate<80);

  const st = selectedTeacher ? teacherStats.find(t=>t.name===selectedTeacher) : null;

  return (
    <div dir="rtl">
      {/* رأس الصفحة */}
      <div className="rounded-b-2xl overflow-hidden mb-6 shadow-xl" style={{background:"linear-gradient(135deg,#1e3a5f,#dc2626)"}}>
        <div className="p-6 text-white">
          <h2 className="text-2xl font-black mb-1">📊 التحليل الإحصائي للأداء</h2>
          <p className="opacity-80 text-sm">تحليل شامل لحضور وغياب المعلمين — {allWeeks.length} أسبوع مسجل</p>
          <div className="grid grid-cols-4 gap-3 mt-4">
            {[
              {label:"نسبة الحضور الكلية", value:avgRate+"%", icon:"✅", color:"#22c55e"},
              {label:"إجمالي الغياب", value:totalAbsences, icon:"❌", color:"#ef4444"},
              {label:"إجمالي التأخر", value:totalLate, icon:"⚠️", color:"#f59e0b"},
              {label:"في خطر", value:atRisk.length, icon:"🔴", color:"#f97316"},
            ].map(s=>(
              <div key={s.label} className="bg-white bg-opacity-10 rounded-2xl p-3 text-center">
                <div className="text-2xl mb-1">{s.icon}</div>
                <div className="text-xl font-black" style={{color:s.color}}>{s.value}</div>
                <div className="text-xs opacity-70 mt-0.5">{s.label}</div>
              </div>
            ))}
          </div>
        </div>
      </div>

      {/* تبويب العرض */}
      <div className="flex gap-2 mb-6">
        {[{id:"overview",label:"نظرة عامة",icon:"📈"},{id:"teacher",label:"تحليل لكل معلم",icon:"👨‍🏫"}].map(t=>(
          <button key={t.id} onClick={()=>setViewMode(t.id)}
            className={`px-4 py-2.5 rounded-xl text-sm font-black transition-all ${viewMode===t.id?"bg-blue-600 text-white shadow-lg":"bg-white text-gray-600 border border-gray-200 hover:bg-gray-50"}`}>
            {t.icon} {t.label}
          </button>
        ))}
      </div>

      {/* ===== نظرة عامة ===== */}
      {viewMode === "overview" && (
        <div className="space-y-6">
          {/* المعلمون في خطر */}
          {atRisk.length > 0 && (
            <div className="bg-red-50 border-2 border-red-200 rounded-2xl p-5">
              <h3 className="font-black text-red-800 mb-3 flex items-center gap-2">🔴 تنبيه — معلمون يحتاجون متابعة ({atRisk.length})</h3>
              <div className="grid gap-2 sm:grid-cols-2">
                {atRisk.map(t=>(
                  <div key={t.name} className="bg-white rounded-xl px-4 py-3 flex items-center justify-between border border-red-100">
                    <span className="font-bold text-gray-800 text-sm">{t.name}</span>
                    <div className="flex gap-2 text-xs">
                      {t.absent>0&&<span className="bg-red-100 text-red-700 px-2 py-0.5 rounded-full font-bold">{t.absent} غياب</span>}
                      {(t.lateMorn+t.latePeriod)>0&&<span className="bg-amber-100 text-amber-700 px-2 py-0.5 rounded-full font-bold">{t.lateMorn+t.latePeriod} تأخر</span>}
                    </div>
                  </div>
                ))}
              </div>
            </div>
          )}

          {/* نجوم الأسبوع */}
          <div className="bg-green-50 border border-green-200 rounded-2xl p-5">
            <h3 className="font-black text-green-800 mb-3">🏆 الأكثر التزاماً</h3>
            <div className="flex gap-3 flex-wrap">
              {topPerformers.map((t,i)=>(
                <div key={t.name} className="flex items-center gap-2 bg-white rounded-xl px-4 py-3 border border-green-100">
                  <span className="text-xl">{i===0?"🥇":i===1?"🥈":"🥉"}</span>
                  <div><div className="font-black text-gray-800 text-sm">{t.name}</div>
                    <div className="text-xs text-green-700 font-bold">{t.rate}% حضور</div></div>
                </div>
              ))}
            </div>
          </div>

          {/* الرسم البياني الرئيسي */}
          <div className="bg-white rounded-2xl p-5 shadow-sm border border-gray-100">
            <h3 className="font-black text-gray-800 mb-4">📊 نسبة الحضور لكل معلم</h3>
            <div className="space-y-3 max-h-96 overflow-y-auto">
              {teacherStats.map(t=>{
                const rateColor = t.rate>=95?"#22c55e":t.rate>=85?"#84cc16":t.rate>=75?"#f59e0b":"#ef4444";
                const bgColor = t.rate>=95?"#dcfce7":t.rate>=85?"#ecfccb":t.rate>=75?"#fef3c7":"#fee2e2";
                return (
                  <div key={t.name} className="cursor-pointer hover:scale-[1.01] transition-transform"
                    onClick={()=>{setSelectedTeacher(t.name);setViewMode("teacher");}}>
                    <div className="flex items-center justify-between mb-1">
                      <span className="text-xs font-bold text-gray-700 truncate max-w-[55%]">{t.name}</span>
                      <div className="flex items-center gap-2 text-xs">
                        {t.absent>0&&<span className="text-red-600 font-bold">{t.absent}❌</span>}
                        {(t.lateMorn+t.latePeriod)>0&&<span className="text-amber-600 font-bold">{t.lateMorn+t.latePeriod}⚠️</span>}
                        <span className="font-black px-2 py-0.5 rounded-full text-xs" style={{background:bgColor,color:rateColor}}>{t.rate}%</span>
                      </div>
                    </div>
                    <div className="h-3 rounded-full" style={{background:"#f3f4f6"}}>
                      <div className="h-full rounded-full transition-all duration-700"
                        style={{width:t.rate+"%", background:`linear-gradient(to left, ${rateColor}, ${rateColor}88)`}}/>
                    </div>
                  </div>
                );
              })}
            </div>
            <div className="flex gap-4 mt-4 text-xs text-gray-500 flex-wrap">
              {[{c:"#22c55e",l:"ممتاز ≥95%"},{c:"#84cc16",l:"جيد ≥85%"},{c:"#f59e0b",l:"متوسط ≥75%"},{c:"#ef4444",l:"ضعيف <75%"}].map(x=>(
                <span key={x.l} className="flex items-center gap-1"><span className="w-3 h-3 rounded-full" style={{background:x.c}}></span>{x.l}</span>
              ))}
            </div>
          </div>

          {/* جدول تفصيلي */}
          <div className="bg-white rounded-2xl overflow-hidden shadow-sm border border-gray-100">
            <div className="px-5 py-3 border-b border-gray-100 flex items-center justify-between">
              <h3 className="font-black text-gray-800">📋 جدول تفاصيل المعلمين</h3>
              <span className="text-xs text-gray-400">{allWeeks.length} أسبوع</span>
            </div>
            <div className="overflow-x-auto">
              <table className="w-full text-sm">
                <thead className="bg-gray-50">
                  <tr>
                    <th className="px-4 py-3 text-right text-xs font-black text-gray-500">المعلم</th>
                    <th className="px-3 py-3 text-center text-xs font-black text-red-600">غياب</th>
                    <th className="px-3 py-3 text-center text-xs font-black text-amber-600">تأخر ص</th>
                    <th className="px-3 py-3 text-center text-xs font-black text-orange-600">تأخر ح</th>
                    <th className="px-3 py-3 text-center text-xs font-black text-gray-500">دقائق</th>
                    <th className="px-3 py-3 text-center text-xs font-black text-green-600">الحضور</th>
                    <th className="px-3 py-3 text-center text-xs font-black text-blue-600">النسبة</th>
                  </tr>
                </thead>
                <tbody>
                  {[...teacherStats].sort((a,b)=>b.absent-a.absent).map((t,i)=>{
                    const rateColor=t.rate>=95?"bg-green-100 text-green-700":t.rate>=85?"bg-lime-100 text-lime-700":t.rate>=75?"bg-amber-100 text-amber-700":"bg-red-100 text-red-700";
                    return (
                      <tr key={t.name} className={(i%2===0?"":"bg-gray-50")+" hover:bg-blue-50 cursor-pointer"}
                        onClick={()=>{setSelectedTeacher(t.name);setViewMode("teacher");}}>
                        <td className="px-4 py-3 font-bold text-gray-800 text-sm">{t.name}</td>
                        <td className="px-3 py-3 text-center font-black text-red-600">{t.absent||"—"}</td>
                        <td className="px-3 py-3 text-center font-black text-amber-600">{t.lateMorn||"—"}</td>
                        <td className="px-3 py-3 text-center font-black text-orange-600">{t.latePeriod||"—"}</td>
                        <td className="px-3 py-3 text-center text-gray-500 text-xs">{t.lateMins>0?t.lateMins+"د":"—"}</td>
                        <td className="px-3 py-3 text-center font-black text-green-600">{t.present}</td>
                        <td className="px-3 py-3 text-center">
                          <span className={"text-xs font-black px-2 py-1 rounded-full "+rateColor}>{t.rate}%</span>
                        </td>
                      </tr>
                    );
                  })}
                </tbody>
              </table>
            </div>
          </div>
        </div>
      )}

      {/* ===== تحليل معلم محدد ===== */}
      {viewMode === "teacher" && (
        <div className="space-y-5">
          {/* اختيار معلم */}
          <div className="bg-white rounded-2xl p-4 shadow-sm border border-gray-100">
            <label className="text-xs font-bold text-gray-500 mb-2 block">اختر معلماً للتحليل التفصيلي</label>
            <div className="flex gap-2 flex-wrap">
              <select value={selectedTeacher||""} onChange={e=>setSelectedTeacher(e.target.value)}
                className="flex-1 px-3 py-2 rounded-xl border-2 border-gray-200 focus:border-blue-400 focus:outline-none text-sm"
                style={{fontFamily:"inherit"}}>
                <option value="">— اختر معلماً —</option>
                {teachers.map(t=><option key={t} value={t}>{t}</option>)}
              </select>
              <button onClick={()=>setViewMode("overview")}
                className="px-4 py-2 rounded-xl bg-gray-100 text-gray-600 text-sm font-bold hover:bg-gray-200">
                ← العودة
              </button>
            </div>
          </div>

          {st && (
            <>
              {/* بطاقة ملخص المعلم */}
              <div className="rounded-2xl overflow-hidden shadow-xl" style={{background:"linear-gradient(135deg,#1e3a5f,#2563eb)"}}>
                <div className="p-5 text-white">
                  <div className="flex items-center gap-4 mb-4">
                    <div className="w-14 h-14 rounded-full bg-white bg-opacity-20 flex items-center justify-center text-2xl font-black">
                      {st.name.charAt(0)}
                    </div>
                    <div>
                      <h3 className="text-lg font-black">{st.name}</h3>
                      <p className="opacity-70 text-sm">{st.totalDays} يوم مسجل — {allWeeks.length} أسبوع</p>
                    </div>
                    <div className="mr-auto text-center">
                      <div className="text-4xl font-black" style={{color:st.rate>=95?"#86efac":st.rate>=80?"#fde68a":"#fca5a5"}}>{st.rate}%</div>
                      <div className="text-xs opacity-70">نسبة الحضور</div>
                    </div>
                  </div>
                  <div className="grid grid-cols-4 gap-3">
                    {[
                      {label:"أيام الحضور",value:st.present,color:"#86efac"},
                      {label:"الغياب",value:st.absent,color:"#fca5a5"},
                      {label:"تأخر صباحي",value:st.lateMorn,color:"#fde68a"},
                      {label:"تأخر حصص",value:st.latePeriod,color:"#fb923c"},
                    ].map(s=>(
                      <div key={s.label} className="bg-white bg-opacity-10 rounded-xl p-3 text-center">
                        <div className="text-xl font-black" style={{color:s.color}}>{s.value}</div>
                        <div className="text-xs opacity-70 mt-0.5">{s.label}</div>
                      </div>
                    ))}
                  </div>
                </div>
                {/* شريط الحضور المرئي */}
                <div className="h-3 flex">
                  <div style={{width:st.totalDays?(st.present/st.totalDays*100)+"%":"0%",background:"#22c55e"}}/>
                  <div style={{width:st.totalDays?((st.lateMorn+st.latePeriod)/st.totalDays*100)+"%":"0%",background:"#f59e0b"}}/>
                  <div style={{width:st.totalDays?(st.absent/st.totalDays*100)+"%":"0%",background:"#ef4444"}}/>
                </div>
              </div>

              {/* مخطط الأسابيع */}
              {st.weeklyData.length > 1 && (
                <div className="bg-white rounded-2xl p-5 shadow-sm border border-gray-100">
                  <h3 className="font-black text-gray-800 mb-4">📅 الأداء الأسبوعي</h3>
                  <div className="space-y-3">
                    {st.weeklyData.map((w,i)=>{
                      const rate = w.days>0?Math.round((w.present/w.days)*100):100;
                      const color = rate>=100?"#22c55e":rate>=80?"#84cc16":rate>=60?"#f59e0b":"#ef4444";
                      return (
                        <div key={i}>
                          <div className="flex items-center justify-between mb-1">
                            <span className="text-xs text-gray-600 font-bold truncate max-w-[65%]">{w.label}</span>
                            <div className="flex gap-1 text-xs">
                              {w.absent>0&&<span className="bg-red-100 text-red-600 px-1.5 py-0.5 rounded font-bold">{w.absent}❌</span>}
                              {w.late>0&&<span className="bg-amber-100 text-amber-600 px-1.5 py-0.5 rounded font-bold">{w.late}⚠️</span>}
                              <span className="font-black" style={{color}}>{rate}%</span>
                            </div>
                          </div>
                          <div className="h-2.5 rounded-full" style={{background:"#f3f4f6"}}>
                            <div className="h-full rounded-full transition-all" style={{width:rate+"%",background:color}}/>
                          </div>
                        </div>
                      );
                    })}
                  </div>
                </div>
              )}

              {/* دقائق التأخر */}
              {st.lateMins > 0 && (
                <div className="bg-amber-50 border border-amber-200 rounded-2xl p-4">
                  <h3 className="font-black text-amber-800 mb-2">⏱️ إجمالي دقائق التأخر</h3>
                  <div className="text-3xl font-black text-amber-700">{st.lateMins} <span className="text-base font-bold">دقيقة</span></div>
                  <div className="text-xs text-amber-600 mt-1">= {Math.floor(st.lateMins/60)} ساعة و {st.lateMins%60} دقيقة</div>
                </div>
              )}
            </>
          )}

          {!st && selectedTeacher === null && (
            <div className="bg-white rounded-2xl p-12 text-center shadow-sm border border-gray-100">
              <div className="text-4xl mb-2">👨‍🏫</div>
              <p className="font-black text-gray-600">اختر معلماً من القائمة أعلاه لعرض تحليله التفصيلي</p>
            </div>
          )}
        </div>
      )}
    </div>
  );
}

// ══════════════════════════════════════════════════════════════════════
// 🏅 متابعة أداء انضباط المعلمين والإداريين — صفحة موحّدة
// رفع ملفات البصمة (يومي أو فردي) ← تُدمج تراكمياً في Firebase ← تحليل الفترة
// school-sdisc/days/{YYYY-MM-DD}/rows/{k} = {n, id, a, d, st}
// school-sdisc/perm/{YYYY-MM-DD}/{k} = {t: "early"|"late"|"both"|"full", note}
// school-sdisc/staff/{k} = {n, r: "t"|"a", x: bool}
// school-sdisc/cfg = {s, e, g, md}
// ══════════════════════════════════════════════════════════════════════
const SDX_NODE = "school-sdisc";
const SDX_DEF_CFG = { s: "06:45", e: "12:35", g: 0, md: 15 };
const SDX_DAYS_AR = ["الأحد", "الاثنين", "الثلاثاء", "الأربعاء", "الخميس", "الجمعة", "السبت"];
const SDX_CATS = [
  { k: "star", min: 98, l: "متميز", c: "#0f7b5f", bg: "#e3f3ec", ic: "🏆" },
  { k: "exc", min: 95, l: "ممتاز", c: "#16a34a", bg: "#e8f7ec", ic: "🌟" },
  { k: "good", min: 85, l: "جيد", c: "#2563eb", bg: "#e4eefc", ic: "👍" },
  { k: "mid", min: 75, l: "متوسط", c: "#d97706", bg: "#fdf0dc", ic: "⚠️" },
  { k: "weak", min: -1, l: "ضعيف", c: "#dc2626", bg: "#fde5e5", ic: "🚨" },
];
const SDX_PERM = { early: "استئذان خروج", late: "استئذان تأخر", both: "استئذان دخول وخروج", full: "غياب بعذر / إجازة / انتداب" };
const SDX_THANKS = [
  "نشكر لكم انضباطكم المثالي وحرصكم على الحضور في الوقت، فأنتم قدوة لزملائكم وطلابكم.",
  "التزامكم بالوقت عنوانٌ لإخلاصكم في رسالتكم، دمتم نموذجاً مشرّفاً للانضباط.",
  "حضوركم المبكر وبقاؤكم حتى نهاية الدوام يعكس مسؤولية عالية نقدّرها ونعتز بها.",
  "انضباطكم المتميز يصنع بيئة تعليمية مستقرة؛ شكراً من القلب على هذا العطاء.",
  "نثمّن حرصكم الدائم والتزامكم التام، وتستحقون أن تكونوا في مقدمة لوحة التميز.",
];
const SDX_IMPROVE = [
  "لاحظنا تحسناً واضحاً في انضباطكم، شكراً لهذا الحرص ونتطلع إلى المزيد من التقدم.",
  "تقدّمكم في الالتزام بالدوام محل تقدير الإدارة، استمروا على هذا النهج الجميل.",
  "خطوة رائعة نحو التميز؛ تحسّن انضباطكم ملحوظ ومقدّر، بارك الله في جهودكم.",
];
const SDX_SCHOOL = "مدرسة الأمير عبدالمجيد المتوسطة الأولى";

// ── أدوات الوقت والتاريخ ──
const sdxPad = n => String(n).padStart(2, "0");
const sdxNum = s => String(s ?? "").replace(/[٠-٩]/g, x => "٠١٢٣٤٥٦٧٨٩".indexOf(x));
function sdxTm(v) {
  if (v === null || v === undefined || v === "") return null;
  if (typeof v === "number") { if (v > 0 && v < 1.0001) return Math.round(v * 1440); return null; }
  let s = sdxNum(v).trim(); if (!s || s === "-" || s === "--") return null;
  const m = s.match(/(\d{1,2})\s*[:.]\s*(\d{2})(?:\s*[:.]\s*\d{2})?/); if (!m) return null;
  let h = +m[1]; const mi = +m[2];
  const pm = /PM|م|مساء/i.test(s), am = /AM|ص|صباح/i.test(s);
  if (pm && h < 12) h += 12; if (am && h === 12) h = 0;
  if (h > 23 || mi > 59) return null;
  return h * 60 + mi;
}
const sdxHM = m => m === null || m === undefined ? "—" : `${sdxPad(Math.floor(m / 60))}:${sdxPad(m % 60)}`;
const sdx12 = m => { if (m === null || m === undefined) return "—"; const h = Math.floor(m / 60), mi = m % 60; return `${sdxPad(h % 12 || 12)}:${sdxPad(mi)} ${h < 12 ? "ص" : "م"}`; };
const sdxDur = m => { m = Math.round(m || 0); if (!m) return "0 د"; const h = Math.floor(m / 60), r = m % 60; return h ? (r ? `${h} س ${r} د` : `${h} س`) : `${r} د`; };
const sdxKey = d => `${d.getFullYear()}-${sdxPad(d.getMonth() + 1)}-${sdxPad(d.getDate())}`;
const sdxDate = k => { const [y, m, d] = k.split("-").map(Number); return new Date(y, m - 1, d); };
const sdxDayName = k => SDX_DAYS_AR[sdxDate(k).getDay()];
const sdxHij = k => { try { return sdxDate(k).toLocaleDateString("ar-SA-u-ca-islamic-umalqura-nu-latn", { day: "numeric", month: "long", year: "numeric" }); } catch { return ""; } };
const sdxGreg = k => { try { return sdxDate(k).toLocaleDateString("ar-u-nu-latn", { day: "numeric", month: "long", year: "numeric" }); } catch { return k; } };
const sdxShort = k => { const d = sdxDate(k); return `${d.getDate()}/${d.getMonth() + 1}`; };
function sdxHijriToG(y, m, d) {
  try {
    const f = new Intl.DateTimeFormat("en-u-ca-islamic-umalqura-nu-latn", { year: "numeric", month: "numeric", day: "numeric" });
    const approx = new Date(Date.UTC(622, 6, 16) + ((y - 1) * 354.36707 + (m - 1) * 29.5306 + (d - 1)) * 864e5);
    for (let off = -45; off <= 45; off++) {
      const t = new Date(approx.getTime() + off * 864e5); const p = {}; f.formatToParts(t).forEach(x => { p[x.type] = x.value; });
      if (+p.year === y && +p.month === m && +p.day === d) return new Date(t.getUTCFullYear(), t.getUTCMonth(), t.getUTCDate());
    }
  } catch {}
  return null;
}
function sdxParseDate(v) {
  if (v === null || v === undefined || v === "") return null;
  if (typeof v === "number" && v > 30000 && v < 80000) { const d = new Date(Math.round((v - 25569) * 864e5)); return sdxKey(new Date(d.getUTCFullYear(), d.getUTCMonth(), d.getUTCDate())); }
  if (v instanceof Date && !isNaN(v)) return sdxKey(v);
  const s = sdxNum(v);
  let m = s.match(/(\d{4})[-/.](\d{1,2})[-/.](\d{1,2})/);
  if (m) { const y = +m[1], mo = +m[2], d = +m[3]; if (y > 1900) return `${y}-${sdxPad(mo)}-${sdxPad(d)}`; const g = sdxHijriToG(y, mo, d); return g ? sdxKey(g) : null; }
  m = s.match(/(\d{1,2})[-/.](\d{1,2})[-/.](\d{2})(?!\d)/);
  if (m && !/\d{1,2}[-/.]\d{1,2}[-/.]\d{4}/.test(s)) { const d = +m[1], mo = +m[2], yy = +m[3]; if (yy >= 40 && yy <= 60) { const g = sdxHijriToG(1400 + yy, mo, d); return g ? sdxKey(g) : null; } return `${2000 + yy}-${sdxPad(mo)}-${sdxPad(d)}`; }
  m = s.match(/(\d{1,2})[-/.](\d{1,2})[-/.](\d{4})/);
  if (m) { const d = +m[1], mo = +m[2], y = +m[3]; if (y > 1900) return `${y}-${sdxPad(mo)}-${sdxPad(d)}`; const g = sdxHijriToG(y, mo, d); return g ? sdxKey(g) : null; }
  return null;
}
const sdxClean = n => String(n || "").replace(/\s+/g, " ").trim();
const sdxK = (id, n) => { const d = sdxNum(id).replace(/\D/g, ""); return d.length >= 6 ? "i" + d : asmK(n); };
const sdxCat = (pct, abs) => { const c = SDX_CATS.find(x => pct >= x.min) || SDX_CATS[4]; return c.k === "star" && abs > 0 ? SDX_CATS[1] : c; };
const sdxPick = (arr, seed) => arr[Math.abs([...String(seed)].reduce((a, ch) => a * 31 + ch.charCodeAt(0), 7)) % arr.length];

// ── قراءة ملف الإكسل: كشف يومي لكل الموظفين، أو تقرير فردي متعدد الأيام ──
async function sdxReadFile(file) {
  await loadXLSX();
  const XLSX = window.XLSX;
  const wb = XLSX.read(new Uint8Array(await file.arrayBuffer()), { type: "array", cellDates: false });
  const out = []; let fileDate = sdxParseDate(file.name); const warn = [];
  wb.SheetNames.forEach(sn => {
    const rows = XLSX.utils.sheet_to_json(wb.Sheets[sn], { header: 1, defval: "", raw: true });
    let hr = -1;
    for (let i = 0; i < Math.min(rows.length, 30); i++) { const cells = rows[i].map(c => sdxClean(c)).filter(Boolean); if (cells.length >= 3 && cells.some(c => /^(توقيت|وقت)?\s*الحضور$/.test(c)) && cells.some(c => /^(توقيت|وقت)?\s*ال[إا]نصراف$|^ال[إا]سم$|^اسم الموظف$/.test(c))) { hr = i; break; } }
    if (hr < 0) return;
    const H = rows[hr].map(c => sdxClean(c));
    const col = re => H.findIndex(h => re.test(h));
    const C = { n: col(/^(ال)?[إا]سم|اسم الموظف|الموظف|المعلم/), id: col(/السجل|الهوية|رقم الموظف|الرقم الوظيفي/), dt: col(/التاريخ/), st: col(/حالة|الحالة/), pm: col(/^الاستئذانات?$|مدة الاستئذان/), job: col(/المسمى|الوظيفة/), a: col(/توقيت الحضور|وقت الحضور|^الحضور/), d: col(/توقيت ال[إا]نصراف|وقت ال[إا]نصراف|^ال[إا]نصراف/) };
    if (C.a < 0) return;
    // اسم الموظف في رأس التقرير الفردي
    let empName = "", empId = "";
    if (C.n < 0) {
      for (let i = 0; i < hr; i++) { const cell = rows[i].find(c => typeof c === "string" && /من\s*:/.test(c)); if (cell) { const lines = cell.split("\n"); const info = lines.find(l => l.includes("-") && !/من\s*:/.test(l)) || lines[lines.length - 1]; const p = info.split("-").map(s => s.trim()); empName = sdxClean(p[0]); empId = sdxNum(p[1] || "").replace(/\D/g, ""); break; } }
      if (!empName) for (let i = 0; i < hr; i++) { const cell = rows[i].find(c => typeof c === "string" && /[؀-ۿ]{2,}\s+[؀-ۿ]{2,}/.test(c) && !/تقرير|الحضور|من\s*:/.test(c)); if (cell) { empName = sdxClean(cell.split("-")[0]); break; } }
      if (!empName) { warn.push(`«${sn}»: لم أجد اسم الموظف`); return; }
    }
    if (!fileDate && C.dt < 0) for (let i = 0; i < hr; i++) for (const c of rows[i]) { const k = sdxParseDate(c); if (k) { fileDate = k; break; } }
    for (let i = hr + 1; i < rows.length; i++) {
      const r = rows[i]; const name = C.n >= 0 ? sdxClean(r[C.n]) : empName;
      if (!name || /المجموع|الإجمالي|الاجمالي/.test(name)) continue;
      const dt = C.dt >= 0 ? sdxParseDate(r[C.dt]) : null;
      if (C.dt >= 0 && !dt) continue;
      const dtxt = C.dt >= 0 ? sdxClean(r[C.dt]) : "";
      const st = C.st >= 0 ? sdxClean(r[C.st]) : "";
      if (/الجمعة|السبت/.test(dtxt) || /عطلة/.test(st)) continue;
      const a = sdxTm(r[C.a]); const d = C.d >= 0 ? sdxTm(r[C.d]) : null;
      const id = C.id >= 0 ? sdxNum(r[C.id]).replace(/\D/g, "") : empId;
      const pm = C.pm >= 0 ? (sdxTm(r[C.pm]) || 0) : 0; const job = C.job >= 0 ? sdxClean(r[C.job]) : "";
      out.push({ n: name, id, dt, a, d, st, pm, job });
    }
  });
  return { rows: out, fileDate, warn };
}

// ── أيام الإجازات الرسمية: يدوياً من الإعدادات، أو تلقائياً إذا غاب 80٪ فأكثر من الموظفين (مثل اليوم الوطني)
function sdxHolidays(days, cfg) {
  const man = (cfg && cfg.hol) || {}; const o = {};
  Object.keys(days || {}).forEach(dk => { const rs = Object.values((days[dk] && days[dk].rows) || {}).filter(Boolean);
    const auto = rs.length >= 5 && rs.filter(r => r.a === null || r.a === undefined || /غياب|غائب/.test(r.st || "")).length / rs.length >= 0.8;
    let off = ""; try { off = typeof maOffName === "function" ? maOffName(dk) : ""; } catch {}
    const v = man[dk] === true || man[dk] === false ? man[dk] : (auto || !!off); if (v) o[dk] = man[dk] === true ? "يدوي" : off ? off.replace(/^إجازة\s*/, "") : "تلقائي"; });
  return o;
}

// ── محرك التحليل ──
function sdxCompute({ days, perm, staff, cfg, from, to, role }) {
  const S = sdxTm(cfg.s) ?? 405, E = sdxTm(cfg.e) ?? 755, W = Math.max(60, E - S), G = +cfg.g || 0, MD = +cfg.md || 0;
  const HOL = sdxHolidays(days, cfg);
  const allKeys = Object.keys(days).filter(k => days[k] && days[k].rows && !HOL[k]).sort();
  const first = {}, names = {};
  allKeys.forEach(dk => Object.entries(days[dk].rows || {}).forEach(([k, r]) => { if (!r) return; if (!first[k]) first[k] = dk; names[k] = r.n || names[k]; }));
  Object.entries(staff || {}).forEach(([k, s]) => { if (s && s.n && !names[k]) names[k] = s.n; });
  const inRole = k => { const s = (staff || {})[k] || {}; if (s.x) return false; const r = s.r || "t"; return role === "all" || r === role; };
  const people = Object.keys(names).filter(inRole);
  const dup = {}; people.forEach(k => { const n = sdxClean(names[k]); dup[n] = (dup[n] || 0) + 1; });
  const label = k => { const n = sdxClean(names[k]); return dup[n] > 1 && k.startsWith("i") ? `${n} (${k.slice(-4)})` : n; };

  const dayRec = (k, dk) => {
    const r = (days[dk].rows || {})[k]; const p = ((perm || {})[dk] || {})[k];
    const o = { dk, r, p, a: r ? (r.a ?? null) : null, d: r ? (r.d ?? null) : null, late: 0, early: 0, exL: 0, exE: 0, miss: false, abs: false, exc: false };
    if ((p && p.t === "full") || (r && /إجازة|اجازة|انتداب|مهمة رسمية|تكليف|عذر/.test(r.st || ""))) { o.exc = true; return o; }
    if (!r || o.a === null || /غياب|غائب/.test(r.st || "")) { o.abs = true; return o; }
    const late = Math.max(0, o.a - S - G);
    if (p && (p.t === "late" || p.t === "both")) o.exL = late; else o.late = late;
    if (o.d !== null && o.d < o.a + 30) o.d = o.a;
    if (o.d === null || o.d === o.a || /تلقائي/.test(r.st || "")) { o.miss = !(p && (p.t === "early" || p.t === "both")); o.d = o.d === o.a ? null : o.d; if (/تلقائي/.test(r.st || "")) o.d = null; }
    else { const early = Math.max(0, E - o.d); if (p && (p.t === "early" || p.t === "both")) o.exE = early; else o.early = early; }
    // استئذان مسجّل في نظام حضوري: دقائقه لا تُحتسب (تُخصم من الخروج المبكر ثم التأخر)
    let pm = +r.pm || 0; if (pm > 0) { const e1 = Math.min(pm, o.early); o.early -= e1; o.exE += e1; pm -= e1; const l1 = Math.min(pm, o.late); o.late -= l1; o.exL += l1; }
    return o;
  };
  const stat = (k, keys) => {
    const recs = keys.filter(dk => first[k] && dk >= first[k]).map(dk => dayRec(k, dk));
    const work = recs.filter(x => !x.exc);
    const pres = work.filter(x => !x.abs);
    const s = { k, n: label(k), role: ((staff || {})[k] || {}).r || "t", recs, days: work.length, exc: recs.length - work.length, pres: pres.length, abs: work.length - pres.length,
      lateDays: pres.filter(x => x.late > 0).length, lateMins: pres.reduce((a, x) => a + x.late, 0),
      earlyDays: pres.filter(x => x.early > 0).length, earlyMins: pres.reduce((a, x) => a + x.early, 0),
      miss: pres.filter(x => x.miss).length, exMins: pres.reduce((a, x) => a + x.exL + x.exE, 0) };
    const arr = pres.map(x => x.a).filter(v => v !== null), dep = pres.map(x => x.d).filter(v => v !== null);
    s.avgA = arr.length ? Math.round(arr.reduce((a, b) => a + b, 0) / arr.length) : null;
    s.avgD = dep.length ? Math.round(dep.reduce((a, b) => a + b, 0) / dep.length) : null;
    s.lost = s.abs * W + s.lateMins + s.earlyMins + s.miss * MD;
    s.pct = s.days ? Math.max(0, Math.round(1000 * (1 - s.lost / (s.days * W))) / 10) : null;
    s.attRate = s.days ? Math.round(100 * s.pres / s.days) : null;
    s.onTime = s.pres ? Math.round(100 * pres.filter(x => x.late === 0).length / s.pres) : null;
    return s;
  };
  const keys = allKeys.filter(dk => dk >= from && dk <= to);
  const prevKeys = allKeys.filter(dk => dk < from).slice(-Math.max(1, keys.length));
  const list = people.map(k => {
    const s = stat(k, keys); if (!s.days && !s.exc) return null;
    const p = prevKeys.length ? stat(k, prevKeys) : null;
    s.prev = p && p.days ? p.pct : null; s.delta = s.prev === null || s.pct === null ? null : Math.round((s.pct - s.prev) * 10) / 10;
    s.cat = s.pct === null ? { k: "na", l: "بعذر", c: "#6b5b95", bg: "#ece8f4", ic: "📋" } : sdxCat(s.pct, s.abs);
    s.improved = s.delta !== null && s.delta >= 2; s.declined = s.delta !== null && s.delta <= -2;
    // منحنى أسبوعي
    const wk = {}; keys.forEach(dk => { const d = sdxDate(dk); const sun = new Date(d); sun.setDate(d.getDate() - d.getDay()); const w = sdxKey(sun); (wk[w] = wk[w] || []).push(dk); });
    s.trend = Object.keys(wk).sort().map(w => { const x = stat(k, wk[w]); return { w, pct: x.pct }; }).filter(x => x.pct !== null);
    return s;
  }).filter(Boolean).sort((a, b) => (b.pct ?? -1) - (a.pct ?? -1) || a.abs - b.abs || (a.lateMins + a.earlyMins) - (b.lateMins + b.earlyMins) || (a.avgA ?? 999) - (b.avgA ?? 999));
  list.forEach((s, i) => { s.rank = i + 1; });
  const sum = f => list.reduce((a, s) => a + (f(s) || 0), 0);
  const T = { people: list.length, days: keys.length, keys, prevKeys, W, S, E, hol: Object.keys(HOL).filter(k => k >= from && k <= to).sort(),
    workDays: sum(s => s.days), pres: sum(s => s.pres), abs: sum(s => s.abs), lateMins: sum(s => s.lateMins), earlyMins: sum(s => s.earlyMins),
    lateDays: sum(s => s.lateDays), earlyDays: sum(s => s.earlyDays), miss: sum(s => s.miss), exc: sum(s => s.exc), exMins: sum(s => s.exMins) };
  T.attRate = T.workDays ? Math.round(1000 * T.pres / T.workDays) / 10 : 0;
  const scored = list.filter(s => s.pct !== null);
  T.avgPct = scored.length ? Math.round(10 * scored.reduce((a, s) => a + s.pct, 0) / scored.length) / 10 : 0;
  T.byCat = SDX_CATS.map(c => ({ ...c, n: list.filter(s => s.cat.k === c.k).length }));
  T.improved = list.filter(s => s.improved).sort((a, b) => b.delta - a.delta);
  T.declined = list.filter(s => s.declined).sort((a, b) => a.delta - b.delta);
  T.stars = list.filter(s => s.cat.k === "star");
  T.watch = list.filter(s => s.pct !== null && (s.pct < 85 || s.abs >= 2 || s.lateDays >= 3 || s.earlyDays >= 3));
  // سلسلة يومية للمدرسة
  T.daily = keys.map(dk => { let p = 0, a = 0, l = 0, e = 0; list.forEach(s => { const r = s.recs.find(x => x.dk === dk); if (!r || r.exc) return; if (r.abs) a++; else { p++; l += r.late; e += r.early; } }); return { dk, p, a, l, e, rate: p + a ? Math.round(100 * p / (p + a)) : 0 }; });
  return { list, T };
}

// ── رسائل الواتساب ──
function sdxWaText(s, kind, range) {
  const head = `السلام عليكم ورحمة الله وبركاته\nالأستاذ الفاضل / ${s.n}\n`;
  const st = `\n📊 نسبة الانضباط: ${s.pct ?? "—"}٪\n📅 أيام الدوام: ${s.days} | الغياب: ${s.abs}\n⏰ دقائق التأخر: ${s.lateMins} | الخروج المبكر: ${s.earlyMins} د\n🗓️ الفترة: ${range}\n`;
  const sign = `\nمع خالص التحية — إدارة ${SDX_SCHOOL}`;
  if (kind === "thanks") return head + "\n🌟 " + sdxPick(SDX_THANKS, s.k) + st + sign;
  if (kind === "improve") return head + `\n📈 ${sdxPick(SDX_IMPROVE, s.k)}\nارتفعت نسبة انضباطكم بمقدار ${s.delta}٪ عن الفترة السابقة.` + st + sign;
  const issues = []; if (s.abs) issues.push(`الغياب (${s.abs} يوم)`); if (s.lateMins) issues.push(`التأخر الصباحي (${s.lateMins} دقيقة في ${s.lateDays} يوم)`); if (s.earlyMins) issues.push(`الانصراف قبل نهاية الدوام (${s.earlyMins} دقيقة)`); if (s.miss) issues.push(`عدم تسجيل بصمة الانصراف (${s.miss} مرة)`);
  return head + `\nنود لفت انتباهكم الكريم إلى ما رصده نظام البصمة من ملاحظات على الدوام: ${issues.join("، ") || "—"}.\nنأمل منكم مراعاة الالتزام بأوقات الدوام الرسمي، وفي حال وجود عذر يُرجى تقديمه للإدارة لتوثيقه.` + st + sign;
}

// ── عدّاد متحرك ──
function SdxCount({ v, dec = 0, suf = "" }) {
  const [x, setX] = useState(0); const ref = useRef(0);
  useEffect(() => { const from = ref.current, to = +v || 0, t0 = performance.now(); let raf; const step = t => { const p = Math.min(1, (t - t0) / 900); const e = 1 - Math.pow(1 - p, 3); const val = from + (to - from) * e; setX(val); ref.current = val; if (p < 1) raf = requestAnimationFrame(step); }; raf = requestAnimationFrame(step); return () => cancelAnimationFrame(raf); }, [v]);
  return <>{dec ? x.toFixed(dec) : Math.round(x).toLocaleString("en")}{suf}</>;
}
function SdxRing({ pct, c, size = 64, sw = 7 }) {
  const R = (size - sw) / 2, C = 2 * Math.PI * R, f = C * Math.max(0, Math.min(100, pct || 0)) / 100;
  return <svg width={size} height={size} style={{ flex: "none" }}><circle cx={size / 2} cy={size / 2} r={R} fill="none" stroke="#e8eef0" strokeWidth={sw} /><circle cx={size / 2} cy={size / 2} r={R} fill="none" stroke={c} strokeWidth={sw} strokeLinecap="round" strokeDasharray={`${f} ${C}`} transform={`rotate(-90 ${size / 2} ${size / 2})`} style={{ transition: "stroke-dasharray .9s" }} /><text x="50%" y="54%" textAnchor="middle" dominantBaseline="middle" fontSize={size * .24} fontWeight="900" fill={c} fontFamily="Cairo">{pct === null || pct === undefined ? "—" : Math.round(pct)}</text></svg>;
}
function SdxSpark({ data, c = "#0f766e", w = 110, h = 30 }) {
  if (!data || data.length < 2) return <span style={{ fontSize: 11, color: "#94a3b8", fontWeight: 700 }}>—</span>;
  const mn = Math.min(...data.map(d => d.pct), 70), mx = 100; const X = i => 3 + i * (w - 6) / (data.length - 1), Y = v => h - 3 - (v - mn) / (mx - mn || 1) * (h - 6);
  const pts = data.map((d, i) => `${X(i)},${Y(d.pct)}`).join(" ");
  return <svg width={w} height={h}><polyline points={pts} fill="none" stroke={c} strokeWidth="2.2" strokeLinejoin="round" strokeLinecap="round" />{data.map((d, i) => <circle key={i} cx={X(i)} cy={Y(d.pct)} r="2.6" fill={c}><title>{`أسبوع ${sdxShort(d.w)}: ${d.pct}٪`}</title></circle>)}</svg>;
}
const SdxDelta = ({ d }) => d === null || d === undefined ? <span className="sdx-chip" style={{ background: "#f1f5f9", color: "#64748b" }}>— لا مقارنة</span>
  : d >= 2 ? <span className="sdx-chip" style={{ background: "#dcfce7", color: "#15803d" }}>▲ تحسّن {d}٪</span>
  : d <= -2 ? <span className="sdx-chip" style={{ background: "#fee2e2", color: "#b91c1c" }}>▼ تدنٍّ {Math.abs(d)}٪</span>
  : <span className="sdx-chip" style={{ background: "#f1f5f9", color: "#475569" }}>● ثابت {d > 0 ? "+" : ""}{d}٪</span>;

