  const secHTML = !A.secs.length ? "" : `${head("02", "نتائج المحاور", "متوسط عبارات كل محور مرتبة كما في الاستبانة")}<div class="rl">${A.secs.map((s, i) => `<div class="ri" style="grid-template-columns:7mm minmax(0,1fr) minmax(0,40mm) 13mm 22mm 14mm"><div class="r" style="background:${s.lvl[1]}">${i + 1}</div><div class="n">${svxE(s.s)}</div><div class="bar"><i style="width:${s.pct || 0}%;background:${s.lvl[1]}"></i></div><div class="v" style="color:${s.lvl[1]}">${f2(s.mean)}<small>المتوسط</small></div><div><span class="pill" style="background:${s.lvl[1]}18;color:${s.lvl[1]}">${s.lvl[0]}</span></div><div class="v">${s.agree.toFixed(0)}٪<small>موافقة</small></div></div>`).join("")}</div>
    ${gN.length > 1 && !grp ? (() => { const G = gN.map(([g]) => [g, svxAnalyze(d, R, g)]); return `<h3>👥 مقارنة الفئات</h3><div class="rl">${G.map(([g, a]) => `<div class="ri" style="grid-template-columns:minmax(0,30mm) minmax(0,1fr) 13mm 22mm 12mm"><div class="n">${svxE(g)}</div><div class="bar"><i style="width:${a.pct || 0}%;background:${a.lvl[1]}"></i></div><div class="v" style="color:${a.lvl[1]}">${f2(a.overall)}<small>المتوسط</small></div><div><span class="pill" style="background:${a.lvl[1]}18;color:${a.lvl[1]}">${a.lvl[0]}</span></div><div class="v">${a.n}<small>مشارك</small></div></div>`).join("")}</div>`; })() : ""}`;
  // جدول العبارات
  const lkRow = (o, i) => `<div class="ri" style="grid-template-columns:7mm minmax(0,1fr) minmax(0,44mm) 12mm 11mm 21mm"><div class="r" style="background:${o.lvl[1]}">${i + 1}</div><div class="k" style="white-space:normal;color:#0f172a;font-size:8.6pt;font-weight:600">${svxE(o.q.text)}${o.q.rev ? ' <span class="muted">(عكسية)</span>' : ""}</div><div class="stk" style="height:4.6mm">${o.cnt.map((c, k) => c ? `<div style="flex:${c};background:${svxCol(o.cnt.length, k)}">${Math.round(100 * c / o.n) >= 9 ? Math.round(100 * c / o.n) + "٪" : ""}</div>` : "").join("")}</div><div class="v" style="color:${o.lvl[1]}">${f2(o.mean)}<small>المتوسط</small></div><div class="v">${f2(o.sd)}<small>الانحراف</small></div><div><span class="pill" style="background:${o.lvl[1]}18;color:${o.lvl[1]}">${o.lvl[0]}</span></div></div>`;
  const lkSorted = A.ranked;
  const mergeSec = secHTML && lkSorted.length <= 14; if (secHTML && !mergeSec) P("المحاور", secHTML);
  for (let i = 0; i < lkSorted.length; i += 24) P(i === 0 && mergeSec ? "المحاور وترتيب العبارات" : "ترتيب العبارات", `${i === 0 && mergeSec ? secHTML + '<div style="height:5mm"></div>' : ""}${i === 0 ? head("03", "ترتيب العبارات تنازلياً حسب المتوسط", (() => { const sig = new Set(lkSorted.map(o => o.scale.join("|"))); return sig.size === 1 && lkSorted.length ? "ألوان الشريط: " + lkSorted[0].scale.map((l, k) => `<span style="color:${svxCol(lkSorted[0].scale.length, k)}">${svxE(l)}</span>`).join(" • ") : "ألوان الشريط من الأخضر (أعلى فقرة) إلى الأحمر (أدنى فقرة) حسب مقياس كل عبارة"; })()) : ""}<div class="rl">${lkSorted.slice(i, i + 24).map((o, j) => lkRow(o, i + j)).join("")}</div>`);
  // بقية الأنواع
