// ── تحليل ملفات Excel (نور وغيرها): إيجاد صف العناوين وعمود الاسم
const FG_NAME_HDR = /^(اسم الطالب|اسم الطالبة|الاسم|الإسم|الاسم الرباعي|الاسم الكامل|اسم الطالب رباعي|اسم الطالب الرباعي|student ?name|name)$/i;
const FG_NOT_NAME = /المسمى|الوظيف|التاريخ|تاريخ|حالة|مكان|توقيت|ساعات|الصف|الفصل|الجنس|الجنسية|الهوية|السجل|رقم|جوال|هاتف|المرحلة|الشعبة|ملاحظ/;
function fgParseRows(raw) {
  const rows = (raw || []).filter(r => Array.isArray(r) && r.some(x => String(x ?? "").trim()));
  let hi = -1, col = -1;
  for (let i = 0; i < Math.min(rows.length, 40) && col < 0; i++) {
    const j = rows[i].findIndex(x => FG_NAME_HDR.test(String(x ?? "").trim()));
    if (j >= 0) { hi = i; col = j; }
  }
  if (col < 0) for (let i = 0; i < Math.min(rows.length, 40) && col < 0; i++) {
    const j = rows[i].findIndex(x => { const t = String(x ?? "").trim(); return /اسم/.test(t) && t.length < 30 && !FG_NOT_NAME.test(t); });
    if (j >= 0) { hi = i; col = j; }
  }
  const headerRow = hi >= 0 ? rows[hi] : null;
  const body = hi >= 0 ? rows.slice(hi + 1) : rows;
  if (col < 0) {
    // لا يوجد عنوان واضح: العمود الذي فيه أكثر أسماء عربية (كلمتان فأكثر) غير مكررة
    const width = Math.max(0, ...body.map(r => r.length));
    let bestScore = -1;
    for (let c = 0; c < width; c++) { const sc = fgUniqueNames(body, c).length; if (sc > bestScore) { bestScore = sc; col = c; } }
    if (col < 0) col = 0;
  }
  const staff = !!(headerRow && headerRow.some(x => /المسمى الوظيفي|الانصراف|ساعات الدوام|حالة التحضير/.test(String(x ?? ""))));
  const meta = fgDetectMeta(rows.slice(0, hi >= 0 ? hi : Math.min(rows.length, 25)));
  // الأعمدة التي فيها بيانات فعلاً (لإخفاء الأعمدة الفارغة في ملفات نور)
  const used = [];
  const width = Math.max(0, ...(headerRow ? [headerRow.length] : []), ...body.map(r => r.length));
  for (let c = 0; c < width; c++) if (body.some(r => String(r[c] ?? "").trim())) used.push(c);
  return { headerRow, body, col, staff, meta, used };
}
// قراءة بيانات الكليشة في ملف نور: «الصف : الثالث المتوسط» ، «الفصل : 2» ...
function fgDetectMeta(top) {
  const LABELS = { level: /^(الصف|الصف الدراسي)$/, section: /^(الفصل|الشعبة)$/, school: /^المدرسة$/, teacher: /^(المعلم|اسم المعلم)$/, subject: /^(المادة|المقرر)$/ };
  const isLabel = t => Object.values(LABELS).some(r => r.test(t)) || /^(القسم|النظام الدراسي|الفترة|العام الدراسي)$/.test(t);
  const meta = {};
  (top || []).forEach(r => {
    (r || []).forEach((x, ci) => {
      const t = String(x ?? "").trim().replace(/[:：]$/, "").trim();
      const key = Object.keys(LABELS).find(k => LABELS[k].test(t));
      if (!key || meta[key]) return;
      const pick = (dir) => { for (let k = ci + dir; k >= 0 && k < r.length; k += dir) { const v = String(r[k] ?? "").trim(); if (!v || v === ":" ) continue; if (isLabel(v.replace(/[:：]$/, "").trim())) return ""; return v; } return ""; };
      const v = pick(-1) || pick(1);
      if (v) meta[key] = v;
    });
  });
  if (meta.level) {
    const L = meta.level;
    const idx = /الأول|الاول|1/.test(L) ? 0 : /الثاني|2/.test(L) ? 1 : /الثالث|3/.test(L) ? 2 : -1;
    meta.levelNorm = idx >= 0 && /متوسط|المتوسط/.test(L + " متوسط") ? FG_LEVELS[idx] : "";
  }
  return meta;
}

function fgUniqueNames(body, col) {
  const seen = new Set(), out = [];
  (body || []).forEach(r => {
    const t = String((r || [])[col] ?? "").trim().replace(/\s+/g, " ");
    if (!t || !/[\u0600-\u06FFa-zA-Z]{2,}/.test(t) || /^\d+$/.test(t) || FG_NAME_HDR.test(t) || t.length > 80) return;
    if (!seen.has(t)) { seen.add(t); out.push(t); }
  });
  return out;
}

function FormativeGradebookPage({ classList = [] }) {
  const [sheets, setSheets] = useState([]);
  const [rowsN, setRowsN] = useState(1);
  const [activeId, setActiveId] = useState(null);
  const [loaded, setLoaded] = useState(false);
  const [swatch, setSwatch] = useState(null);
  const [modal, setModal] = useState(null); // paste | excel | classes | model
  const [pasteText, setPasteText] = useState("");
  const [xl, setXl] = useState(null); // {sheets, sheet, col, target, adv}
  const [toast, setToast] = useState("");
  const [showStyle, setShowStyle] = useState(false);
  const [teachersList, setTeachersList] = useState(FG_TEACHERS_DEFAULT);
  const [ink, setInk] = useState(() => { try { return localStorage.getItem("fg-ink") || "full"; } catch { return "full"; } });
  const staffRef = useRef(null);
  useEffect(() => { (async () => { try { const t = await DB.get("formative-teachers", null); if (Array.isArray(t) && t.length) setTeachersList(t); } catch {} })(); }, []);
  const saveTeachers = (list) => { const u = [...new Set(list.map(x => String(x).trim()).filter(Boolean))].sort((a, b) => a.localeCompare(b, "ar")); setTeachersList(u); try { DB.set("formative-teachers", u); } catch {} return u; };
  useEffect(() => { if (!toast) return; const t = setTimeout(() => setToast(""), 3500); return () => clearTimeout(t); }, [toast]);
  const fileRef = useRef(null);
  const saveT = useRef(null);

  useEffect(() => {
    (async () => {
      let list = [];
      try { list = (await DB.get("formative-sheets", [])) || []; } catch {}
      if (!Array.isArray(list) || !list.length) list = [fgNewSheet()];
      // ترقية السجلات القديمة (بدون درجات) إلى التقسيم الجديد: أعمدة رئيسية بخانات + أسماء الاختبارات
      list = list.map(sh => {
        const old = (sh.v || 0) < 4;
        const hasScores = (sh.students || []).some(st => Object.keys(st.scores || {}).length);
        return old && !hasScores ? { ...sh, ...fgBuildColumns(sh.model || "4") } : sh;
      });
      setSheets(list); setActiveId(list[0].id); setLoaded(true);
    })();
  }, []);

  const persist = (list) => {
    if (saveT.current) clearTimeout(saveT.current);
    saveT.current = setTimeout(() => { try { DB.set("formative-sheets", list); } catch {} }, 700);
  };
  const sheet = sheets.find(s => s.id === activeId) || sheets[0];
  const update = (fn) => setSheets(prev => {
    const next = prev.map(s => s.id === sheet.id ? { ...fn(s), updated: Date.now() } : s);
    persist(next); return next;
  });
  const set = (k, v) => update(s => ({ ...s, [k]: v }));

  if (!loaded || !sheet) return <div className="fg p-10 text-center font-bold text-gray-400">جاري تحميل السجل…</div>;

  const modelInfo = (typeof GA_MODELS !== "undefined" && GA_MODELS[sheet.model]) || null;
  const subjects = (typeof GA_SUBJECTS !== "undefined" && GA_SUBJECTS["متوسط"]) || {};
  const wOf = c => (+c.weight > 0 ? +c.weight : 1);
  const examGroup = sheet.groups.find(g => g.exam);
  // النسبة الشرطية تُطبق على الاختبار النهائي في المواد المقوّمة ختامياً
  const form = sheet.form || fgFormOf(sheet.model);
  const examCols = form === "final" ? sheet.cols.filter(c => c.exam || (examGroup && c.groupId === examGroup.id)) : [];
  const maxTotal = Math.round(sheet.cols.reduce((a, c) => a + (+c.max || 0) * wOf(c), 0) * 100) / 100;

  // ── العمليات على الأعمدة
  const addCol = (groupId) => update(s => {
    const g = s.groups.find(x => x.id === groupId);
    const idx = s.cols.map(c => c.groupId).lastIndexOf(groupId);
    const col = { id: fgId(), label: "عمود جديد", max: 5, groupId, color: FG_PALETTE[s.cols.length % FG_PALETTE.length] || g.color };
    const cols = [...s.cols]; cols.splice(idx + 1, 0, col);
    return { ...s, cols };
  });
  const delCol = (id) => {
    const c = sheet.cols.find(x => x.id === id);
    if (!window.confirm(`حذف عمود «${c.label}» وجميع درجاته؟`)) return;
    update(s => ({ ...s, cols: s.cols.filter(x => x.id !== id), students: s.students.map(st => { const sc = { ...st.scores }; Object.keys(sc).forEach(k => { if (k === id || k.startsWith(id + "#")) delete sc[k]; }); return { ...st, scores: sc }; }) }));
  };
  const setCol = (id, k, v) => update(s => ({ ...s, cols: s.cols.map(c => c.id === id ? { ...c, [k]: v } : c) }));
  const moveCol = (id, dir) => update(s => {
    const cols = [...s.cols]; const i = cols.findIndex(c => c.id === id); const j = i + dir;
    if (j < 0 || j >= cols.length || cols[j].groupId !== cols[i].groupId) return s;
    [cols[i], cols[j]] = [cols[j], cols[i]]; return { ...s, cols };
  });
  const addGroup = () => update(s => {
    const g = { id: fgId(), label: "مكوّن إضافي", max: 10, color: FG_GROUP_COLORS[s.groups.length % FG_GROUP_COLORS.length] };
    return { ...s, groups: [...s.groups, g], cols: [...s.cols, { id: fgId(), label: "عمود جديد", max: 10, groupId: g.id, color: g.color }] };
  });
  const setGroup = (id, k, v) => update(s => ({ ...s, groups: s.groups.map(g => g.id === id ? { ...g, [k]: v } : g) }));
  const delGroup = (id) => {
    if (!window.confirm("حذف هذا المكوّن بكل أعمدته ودرجاته؟")) return;
    update(s => ({ ...s, groups: s.groups.filter(g => g.id !== id), cols: s.cols.filter(c => c.groupId !== id) }));
  };
  const applyModel = (key) => {
    const hasScores = sheet.students.some(st => Object.keys(st.scores || {}).length);
    if (hasScores && !window.confirm("تطبيق النموذج سيعيد بناء الأعمدة ويمسح الدرجات المرصودة. متابعة؟")) return;
    update(s => ({ ...s, model: key, ...fgBuildColumns(key), students: s.students.map(st => ({ ...st, scores: {} })) }));
    setModal(null);
  };
  const applyForm = (f) => {
    if (f === form && (sheet.v || 0) >= 4) return;
    const hasScores = sheet.students.some(st => Object.keys(st.scores || {}).length);
    if (hasScores && !window.confirm("تغيير النموذج سيعيد بناء الأعمدة ويمسح الدرجات المرصودة في هذا السجل. متابعة؟")) return;
    const mk = f === fgFormOf(sheet.model) ? sheet.model : (f === "final" ? "2" : "4");
    update(s => ({ ...s, model: mk, ...fgBuildColumns(mk, f), students: s.students.map(st => ({ ...st, scores: {} })) }));
  };
  const onSubject = (sub) => {
    const key = subjects[sub];
    update(s => {
      const hasScores = s.students.some(st => Object.keys(st.scores || {}).length);
      if (key && key !== s.model && !hasScores) return { ...s, subject: sub, model: key, ...fgBuildColumns(key) };
      return { ...s, subject: sub };
    });
  };

  // ── الطلاب
  const mergeNames = (students, names) => {
    const clean = students.filter(st => st.name.trim() || Object.keys(st.scores || {}).length);
    const existing = new Set(clean.map(st => st.name.trim().replace(/\s+/g, " ")));
    const add = [];
    names.forEach(n => { const name = String(n ?? "").trim().replace(/\s+/g, " "); if (name && !existing.has(name)) { existing.add(name); add.push({ id: fgId(), name, scores: {} }); } });
    return { list: [...clean, ...add], added: add.length };
  };
  // استيراد إلى سجل محدد (الحالي / المطابق للفصل / جديد) مع تعبئة بيانات الفصل
  const importTo = (target, names, meta) => {
    const info = {};
    if (meta?.levelNorm) info.level = meta.levelNorm;
    if (meta?.section) info.section = meta.section;
    if (meta?.teacher) info.teacher = meta.teacher;
    if (meta?.subject) info.subject = meta.subject;
    let added = 0, targetId = sheet.id;
    {
      const prev = sheets; let next;
      if (target === "new") {
        const base = fgNewSheet({ teacher: sheet.teacher, subject: sheet.subject, model: sheet.model, semester: sheet.semester, edu: sheet.edu, school: sheet.school, ...info });
        const m = mergeNames([], names); added = m.added;
        const ns = { ...base, students: m.list }; targetId = ns.id;
        next = [ns, ...prev];
      } else {
        targetId = target === "current" ? sheet.id : target;
        next = prev.map(sh => { if (sh.id !== targetId) return sh; const m = mergeNames(sh.students, names); added = m.added; return { ...sh, ...(target === "current" ? info : {}), students: m.list, updated: Date.now() }; });
      }
      setSheets(next); persist(next);
    }
    setActiveId(targetId);
    setTimeout(() => setToast(`✅ تم استيراد ${added} طالب${meta?.levelNorm ? ` — ${meta.levelNorm} / ${meta.section || ""}` : ""}`), 50);
  };
  const addStudents = (names) => update(s => {
    const clean = s.students.filter(st => st.name.trim() || Object.keys(st.scores || {}).length);
    const existing = new Set(clean.map(st => st.name.trim().replace(/\s+/g, " ")));
    const add = [];
    names.forEach(n => { const name = String(n ?? "").trim().replace(/\s+/g, " "); if (name && !existing.has(name)) { existing.add(name); add.push({ id: fgId(), name, scores: {} }); } });
    return { ...s, students: [...clean, ...add] };
  });
  const addBlank = (n = 1) => update(s => ({ ...s, students: [...s.students, ...Array.from({ length: Math.max(1, Math.min(60, +n || 1)) }, () => ({ id: fgId(), name: "", scores: {}, keep: 1 }))] }));
  const delBlankRows = () => { const n = sheet.students.filter(st => !st.name.trim() && !Object.values(st.scores || {}).some(v => v !== "" && v != null)).length; if (!n) return; if (window.confirm(`حذف ${n} صفاً فارغاً (بدون اسم ولا درجات)؟`)) update(s => ({ ...s, students: s.students.filter(st => st.name.trim() || Object.values(st.scores || {}).some(v => v !== "" && v != null)) })); };
  const dupCol = (id) => update(s => { const i = s.cols.findIndex(c => c.id === id); if (i < 0) return s; const c = s.cols[i]; const m = String(c.label).match(/^(.*?)\s*(\d+)$/); const label = m ? `${m[1]} ${+m[2] + 1}` : `${c.label} ٢`; const cols = [...s.cols]; cols.splice(i + 1, 0, { ...c, id: fgId(), label }); return { ...s, cols }; });
  const addColEnd = () => update(s => { let groups = s.groups; let g = groups[groups.length - 1]; if (!g) { g = { id: fgId(), label: "مكوّن", max: 10, color: FG_GROUP_COLORS[0] }; groups = [g]; } const col = { id: fgId(), label: "عمود جديد", max: 5, groupId: g.id, color: FG_PALETTE[s.cols.length % FG_PALETTE.length] || g.color }; const idx = s.cols.map(c => c.groupId).lastIndexOf(g.id); const cols = [...s.cols]; cols.splice(idx + 1, 0, col); return { ...s, groups, cols }; });
  const setName = (id, name) => update(s => ({ ...s, students: s.students.map(st => st.id === id ? { ...st, name } : st) }));
  const delStudent = (id) => update(s => ({ ...s, students: s.students.filter(st => st.id !== id) }));
  const setScore = (sid, cid, v) => update(s => ({ ...s, students: s.students.map(st => {
    if (st.id !== sid) return st;
    const sc = { ...st.scores };
    if (v === "") delete sc[cid]; else sc[cid] = v;
    return { ...st, scores: sc };
  }) }));
  const sortByName = () => update(s => ({ ...s, students: [...s.students].sort((a, b) => (a.name || "ي").localeCompare(b.name || "ي", "ar")) }));

  // ── الحسابات
  const num = v => { const n = parseFloat(String(v ?? "").replace(/[٠-٩]/g, d => "٠١٢٣٤٥٦٧٨٩".indexOf(d))); return isNaN(n) ? null : n; };
  const nEntries = c => Math.max(1, Math.min(10, parseInt(c.entries) || 1));
  const keysOf = c => nEntries(c) > 1 ? Array.from({ length: nEntries(c) }, (_, k) => `${c.id}#${k}`) : [c.id];
  // حد الخانة: درجة العمود ÷ عدد الخانات (مثال ١٠ ÷ ٥ = ٢)
  const entryMax = c => Math.round((+c.max || 0) / nEntries(c) * 100) / 100;
  // قيمة العمود الخام: مجموع خاناته (بحد أقصى درجة العمود)
  const colRaw = (st, c) => {
    const em = entryMax(c);
    const vals = keysOf(c).map(k => num(st.scores?.[k])).filter(n => n != null).map(n => Math.min(Math.max(n, 0), em));
    if (!vals.length) return null;
    return Math.round(Math.min(vals.reduce((a, b) => a + b, 0), +c.max || 0) * 100) / 100;
  };
  // القيمة المحتسبة في المجموع (فترة أولى وثانية ÷٢)
  const colValue = (st, c) => { const v = colRaw(st, c); return v == null ? null : Math.round(v * wOf(c) * 100) / 100; };
  const rowCalc = (st) => {
    let t = 0, any = false;
    sheet.cols.forEach(c => { const n = colValue(st, c); if (n != null) { t += n; any = true; } });
    const pct = maxTotal ? (t / maxTotal) * 100 : 0;
    let cond = true;
    if (examCols.length) {
      const exMax = examCols.reduce((a, c) => a + (+c.max || 0), 0);
      const exGot = examCols.reduce((a, c) => a + (colRaw(st, c) || 0), 0);
      const exAny = examCols.some(c => colRaw(st, c) != null);
      cond = !exAny || exGot >= exMax * 0.2;
    }
    return { t: Math.round(t * 100) / 100, pct, any, cond };
  };
  const named = sheet.students.filter(st => st.name.trim());
  const calcs = named.map(rowCalc).filter(r => r.any);
  const avg = calcs.length ? calcs.reduce((a, r) => a + r.pct, 0) / calcs.length : 0;
  const excellent = calcs.filter(r => r.pct >= 90).length;
  const weak = calcs.filter(r => r.pct < 50 || !r.cond).length;
  const colAvg = (c) => { const v = named.map(st => colRaw(st, c)).filter(n => n != null); return v.length ? (v.reduce((a, b) => a + b, 0) / v.length).toFixed(1) : "—"; };
  const keyAvg = (k) => { const v = named.map(st => num(st.scores?.[k])).filter(n => n != null); return v.length ? (v.reduce((a, b) => a + b, 0) / v.length).toFixed(1) : ""; };
  const spanOf = c => nEntries(c);
  const orderedColsAll = sheet.groups.flatMap(g => sheet.cols.filter(c => c.groupId === g.id));
  const anyMulti = orderedColsAll.some(c => nEntries(c) > 1);

  // تنقل بالأسهم و Enter
  const onKey = (e, r, c) => {
    const go = (rr, cc) => { const el = document.querySelector(`[data-fg="${rr}-${cc}"]`); if (el) { e.preventDefault(); el.focus(); el.select?.(); } };
    if (e.key === "Enter" || e.key === "ArrowDown") go(r + 1, c);
    else if (e.key === "ArrowUp") go(r - 1, c);
    else if (e.key === "ArrowLeft" && e.target.selectionStart === e.target.value.length) go(r, c + 1);
    else if (e.key === "ArrowRight" && e.target.selectionStart === 0) go(r, c - 1);
  };

  // ── Excel
  const onExcel = async (e) => {
    const f = e.target.files?.[0]; e.target.value = "";
    if (!f) return;
    try {
      const XLSX = await loadXLSX();
      const wb = XLSX.read(await f.arrayBuffer());
      const sheetsParsed = wb.SheetNames.map(n => ({ name: n, ...fgParseRows(XLSX.utils.sheet_to_json(wb.Sheets[n], { header: 1, defval: "" })) }));
      const usable = sheetsParsed.filter(x => x.body.length);
      if (!usable.length) { alert("الملف فارغ"); return; }
      const bestSheet = usable.reduce((a, b) => fgUniqueNames(b.body, b.col).length > fgUniqueNames(a.body, a.col).length ? b : a);
      const m = bestSheet.meta || {};
      const match = m.levelNorm ? sheets.find(sh => sh.level === m.levelNorm && String(sh.section) === String(m.section || "")) : null;
      const curEmpty = !sheet.students.some(st => st.name.trim());
      const target = match ? match.id : (curEmpty ? "current" : (m.levelNorm ? "new" : "current"));
      setXl({ fname: f.name, sheets: usable, sheet: bestSheet.name, col: bestSheet.col, target, adv: false });
      setModal("excel");
    } catch (err) { alert("تعذّر قراءة الملف: " + (err?.message || err)); }
  };
  // تحديث قائمة المعلمين من تقرير الحضور والانصراف (يأخذ من مسمّاه «معلم»)
  const onStaffFile = async (e) => {
    const f = e.target.files?.[0]; e.target.value = "";
    if (!f) return;
    try {
      const XLSX = await loadXLSX();
      const wb = XLSX.read(await f.arrayBuffer());
      const found = [];
      wb.SheetNames.forEach(n => {
        const rows = XLSX.utils.sheet_to_json(wb.Sheets[n], { header: 1, defval: "" });
        let hi = -1, nc = -1, jc = -1;
        for (let i = 0; i < Math.min(rows.length, 40) && hi < 0; i++) {
          const r = rows[i].map(x => String(x ?? "").trim());
          const a = r.findIndex(x => /^(الإسم|الاسم|اسم الموظف|اسم المعلم)$/.test(x));
          if (a >= 0) { hi = i; nc = a; jc = r.findIndex(x => /المسمى|الوظيفة/.test(x)); }
        }
        if (hi < 0) return;
        rows.slice(hi + 1).forEach(r => { const nm = String(r[nc] ?? "").trim(); const job = jc >= 0 ? String(r[jc] ?? "") : "معلم"; if (nm && /معلم/.test(job)) found.push(nm); });
      });
      const uniq = [...new Set(found)];
      if (!uniq.length) { alert("لم أجد معلمين في الملف — تأكد أنه تقرير الحضور والانصراف (عمود «الإسم» و«المسمى الوظيفي»)"); return; }
      const before = new Set(teachersList);
      const merged = saveTeachers([...teachersList, ...uniq]);
      setToast(`✅ قائمة المعلمين: ${merged.length} معلم (${uniq.filter(x => !before.has(x)).length} جديد)`);
    } catch (err) { alert("تعذّر قراءة الملف: " + (err?.message || err)); }
  };
  const onTeacherPick = (v) => {
    if (v === "__add") { const n = window.prompt("اسم المعلم:"); if (n && n.trim()) { saveTeachers([...teachersList, n.trim()]); set("teacher", n.trim()); } return; }
    set("teacher", v);
  };
  const ST = { line: "#94a3b8", lineW: 1, vline: "#e2e8f0", cells: "tint", tint: 14, zebra: "#f1f5f9", head: "#0f172a", ...(sheet.style || {}) };
  const setStyle = (k, v) => update(s => ({ ...s, style: { ...(s.style || {}), [k]: v } }));
  const hexA = (hex, a) => { const h = String(hex || "#000").replace("#", ""); const n = parseInt(h.length === 3 ? h.split("").map(x => x + x).join("") : h.slice(0, 6), 16); return `rgba(${(n >> 16) & 255},${(n >> 8) & 255},${n & 255},${a})`; };
  const cellBg = (c, ri, filled) => ST.cells === "white" ? (ri % 2 && ST.zebraOn ? ST.zebra : "#fff") : ST.cells === "zebra" ? (ri % 2 ? ST.zebra : "#fff") : hexA(c.color, (ST.tint / 100) * (filled ? 1.3 : .6));
  const fromRoster = async () => {
    const lvI = FG_LEVELS.indexOf(sheet.level) + 1; const ck = `${lvI}-${sheet.section}`;
    const ros = await maGet(MA_ROSTER); const L = maArr(ptObj(ros)[ck] && ptObj(ros)[ck].students).filter(x => x && x.id && x.name);
    if (!L.length) { alert(`لا توجد أسماء لفصل ${maClassName(ck)} في كشوف المدرسة — ارفع كشف نور من «سجل التأخر الصباحي ← الفصول»`); return; }
    const nn = t => String(t || "").replace(/[إأآا]/g, "ا").replace(/ى/g, "ي").replace(/ة/g, "ه").replace(/\s+/g, " ").trim();
    const cur = sheet.students.filter(st => st.name.trim()); const hasScores = cur.some(st => Object.keys(st.scores || {}).length);
    if (cur.length && !window.confirm(`استيراد ${L.length} طالب من كشف ${maClassName(ck)}؟\n${hasScores ? "ستبقى درجات الطلاب المطابقين بالاسم." : "سيُستبدل الطلاب الحاليون."}`)) return;
    const bySid = new Map(cur.filter(st => st.sid).map(st => [st.sid, st])); const byName = new Map(cur.map(st => [nn(st.name), st]));
    const students = L.map(x => { const o = bySid.get(x.id) || byName.get(nn(x.name)); return { id: o ? o.id : fgId(), sid: x.id, name: x.name, scores: o ? o.scores || {} : {} }; });
    update(s => ({ ...s, ck, students })); setToast(`✅ استُورد ${L.length} طالب من كشف ${maClassName(ck)} — مرتبطون ببوابة ولي الأمر`);
  };
  // تغيير الصف/الفصل من الأعلى ← تُحمَّل أسماء الفصل الجديد من كشوف المدرسة تلقائياً
  const changeClass = async (lv, sec) => {
    const lvI = FG_LEVELS.indexOf(lv) + 1; const ck = `${lvI}-${sec}`; const curCk = `${FG_LEVELS.indexOf(sheet.level) + 1}-${sheet.section}`;
    if (ck === curCk) return;
    const ex = sheets.find(x => x.id !== sheet.id && x.level === lv && String(x.section) === String(sec) && (x.subject || "") === (sheet.subject || "") && (x.teacher || "") === (sheet.teacher || "") && x.semester === sheet.semester);
    if (ex && window.confirm(`يوجد سجل محفوظ لفصل ${maClassName(ck)} في نفس المادة والفترة — فتحه؟`)) { setActiveId(ex.id); return; }
    const ros = await maGet(MA_ROSTER); const L = maArr(ptObj(ros)[ck] && ptObj(ros)[ck].students).filter(x => x && x.id && x.name);
    const studs = L.map(x => ({ id: fgId(), sid: x.id, name: x.name, scores: {} }));
    const blank = Array.from({ length: 5 }, () => ({ id: fgId(), name: "", scores: {} }));
    const hasScores = sheet.students.some(st => Object.keys(st.scores || {}).length);
    const named = sheet.students.some(st => st.name.trim());
    if (hasScores || (named && !L.length && !sheet.ck)) {
      if (!window.confirm(`السجل الحالي (${maClassName(curCk)}) ${hasScores ? "فيه درجات مرصودة" : "فيه أسماء"} — سيُنشأ سجل جديد لفصل ${maClassName(ck)} بنفس الأعمدة والإعدادات، ويبقى السجل الحالي محفوظاً. متابعة؟`)) return;
      const ns = { ...JSON.parse(JSON.stringify(sheet)), id: "fg-" + Date.now(), level: lv, section: sec, ck, pub: false, students: studs.length ? studs : blank, updated: Date.now() };
      const next = [ns, ...sheets]; setSheets(next); setActiveId(ns.id); persist(next);
    } else update(x => ({ ...x, level: lv, section: sec, ck, students: studs.length ? studs : blank }));
    setToast(L.length ? `✅ ${maClassName(ck)}: تم تحميل ${L.length} طالب من كشوف المدرسة` : `⚠️ لا توجد أسماء لفصل ${maClassName(ck)} في كشوف المدرسة — ارفع كشف نور من «سجل التأخر الصباحي ← الفصول» أو أضف الأسماء يدوياً`);
  };
  const onLevel = (lv) => changeClass(lv, (FG_SECTIONS[lv] || []).includes(String(sheet.section)) ? sheet.section : "1");
  const distribute = (gid) => update(s => {
    const g = s.groups.find(x => x.id === gid); const cs = s.cols.filter(c => c.groupId === gid);
    if (!g || !cs.length) return s;
    const base = Math.floor((+g.max || 0) / cs.length * 2) / 2; let rest = (+g.max || 0) - base * cs.length;
    const ids = cs.map(c => c.id);
    return { ...s, cols: s.cols.map(c => { const i = ids.indexOf(c.id); if (i < 0) return c; let v = base; if (i === ids.length - 1) v = +(base + rest).toFixed(2); return { ...c, max: v }; }) };
  });
  const exportExcel = async () => {
    const XLSX = await loadXLSX();
    const h1 = ["م", "اسم الطالب"], h2 = ["", ""], h3 = ["", ""];
    orderedColsAll.forEach(c => {
      const g = sheet.groups.find(x => x.id === c.groupId); const first = sheet.cols.find(x => x.groupId === c.groupId) === c;
      const span = spanOf(c);
      for (let k = 0; k < span; k++) {
        h1.push(first && k === 0 ? `${g.label} (${g.max})` : "");
        h2.push(k === 0 ? `${c.label} (${c.max})` : "");
        h3.push(span > 1 ? `${k + 1} (/${entryMax(c)})` : (wOf(c) === 0.5 ? "÷٢" : ""));
      }
    });
    h1.push("المجموع"); h2.push(`من ${maxTotal}`); h3.push("");
    const rows = named.map((st, i) => { const r = rowCalc(st); const out = [i + 1, st.name];
      orderedColsAll.forEach(c => { keysOf(c).forEach(k => out.push(num(st.scores?.[k]) ?? "")); });
      out.push(r.any ? r.t : ""); return out; });
    const aoa = [
      ["المملكة العربية السعودية — وزارة التعليم — " + sheet.edu],
      [sheet.school + " — سجل رصد التقويم التكويني"],
      [`المعلم: ${sheet.teacher || "—"}   المادة: ${sheet.subject || "—"}   الصف: ${sheet.level} / ${sheet.section}   ${sheet.semester}   العام: ${sheet.year}`],
      [], h1, h2, h3, ...rows,
    ];
    const ws = XLSX.utils.aoa_to_sheet(aoa);
    ws["!cols"] = [{ wch: 5 }, { wch: 30 }, ...h1.slice(2).map(() => ({ wch: 9 }))];
    ws["!rtl"] = true;
    const wb = XLSX.utils.book_new(); wb.Workbook = { Views: [{ RTL: true }] };
    XLSX.utils.book_append_sheet(wb, ws, "التقويم التكويني");
    XLSX.writeFile(wb, `التقويم_التكويني_${sheet.subject || "مادة"}_${sheet.level}_${sheet.section}.xlsx`);
  };
  const downloadTemplate = async () => {
    const XLSX = await loadXLSX();
    const ws = XLSX.utils.aoa_to_sheet([["م", "اسم الطالب"], [1, "محمد عبدالله أحمد"], [2, "فهد سعد علي"]]);
    ws["!cols"] = [{ wch: 5 }, { wch: 32 }];
    const wb = XLSX.utils.book_new(); XLSX.utils.book_append_sheet(wb, ws, "الطلاب");
    XLSX.writeFile(wb, "نموذج_أسماء_الطلاب.xlsx");
  };

  // ── طباعة (ألوان كاملة / خفيفة لتوفير الحبر / أبيض وأسود)
  const setInkM = v => { setInk(v); try { localStorage.setItem("fg-ink", v); } catch {} };
  const print = () => {
    const LT = ink === "light", BW = ink === "bw";
    const cellBgP = (c, i) => BW ? (i % 2 ? "#f5f5f5" : "#fff") : LT ? (i % 2 ? "#fafafa" : "#fff") : cellBg(c, i, true);
    const logo = typeof SCHOOL_LOGO !== "undefined" ? `<img src="${SCHOOL_LOGO}" style="width:62px;height:62px">` : "";
    const HR = anyMulti ? 3 : 2;
    const gh = sheet.groups.map(g => { const n = sheet.cols.filter(c => c.groupId === g.id).reduce((a, c) => a + spanOf(c), 0); return n ? `<th colspan="${n}" style="${BW ? "background:#fff;color:#000;border:1.5px solid #000" : LT ? `background:${hexA(g.color, .12)};color:${g.color};border-top:3px solid ${g.color}` : `background:${g.color};color:#fff`}">${g.label} (${g.max})</th>` : ""; }).join("");
    const ch = orderedColsAll.map(c => `<th colspan="${spanOf(c)}" ${spanOf(c) === 1 && anyMulti ? 'rowspan="2"' : ""} style="${BW ? "background:#fff;border-top:2px solid #000" : LT ? `background:#fff;border-top:2px solid ${c.color};color:${c.color}` : `background:${hexA(c.color, .15)};border-top:3px solid ${c.color}`}">${c.label}<br><small>${c.max}${wOf(c) === 0.5 ? " ÷٢" : ""}</small></th>`).join("");
    const sh3 = orderedColsAll.filter(c => nEntries(c) > 1).map(c => keysOf(c).map((_, k) => `<th style="background:${BW || LT ? "#fff" : hexA(c.color, .1)};font-size:9px">${k + 1}</th>`).join("")).join("");
    const prows = sheet.students.filter(st => (st.name || "").trim() || st.keep || Object.values(st.scores || {}).some(v => v !== "" && v != null));
    const body = prows.map((st, i) => { const r = rowCalc(st);
      const cells = orderedColsAll.map(c => { const v = colValue(st, c);
        return keysOf(c).map(k => `<td style="background:${cellBgP(c, i)}">${st.scores?.[k] ?? ""}</td>`).join(""); }).join("");
      return `<tr><td>${i + 1}</td><td style="text-align:right;padding-right:8px;font-weight:700;white-space:nowrap;height:22px">${st.name || ""}</td>${cells}<td style="font-weight:900">${r.any ? r.t : ""}${r.any && !r.cond ? "<br><small style='color:#dc2626'>لم يحقق النسبة الشرطية</small>" : ""}</td></tr>`; }).join("");
    printWindow(`<!DOCTYPE html><html dir="rtl" lang="ar"><head><meta charset="utf-8"><title>سجل التقويم التكويني</title>
<link href="https://fonts.googleapis.com/css2?family=Cairo:wght@400;700;900&display=swap" rel="stylesheet">
<style>@page{size:A4 landscape;margin:10mm}*{box-sizing:border-box;-webkit-print-color-adjust:exact;print-color-adjust:exact}body{font-family:Cairo,Tahoma,sans-serif;margin:0;color:#0f172a}
.k{display:grid;grid-template-columns:1fr auto 1fr;align-items:center;border-bottom:3px solid #0f766e;padding-bottom:8px;margin-bottom:8px;font-size:12px;font-weight:700;line-height:1.8}
.k .l{text-align:left}h1{text-align:center;font-size:18px;margin:4px 0;color:#0f766e}
.info{display:flex;justify-content:center;gap:18px;flex-wrap:wrap;font-size:12px;font-weight:700;background:#f0fdfa;border:1px solid #99f6e4;border-radius:10px;padding:6px;margin-bottom:8px}
table{width:100%;border-collapse:collapse;font-size:11px}th,td{border:1px solid ${ST.vline};border-bottom:${ST.lineW}px solid ${ST.line};padding:4px;text-align:center}th small{font-weight:400;color:#475569}
.sig{display:flex;justify-content:space-around;margin-top:26px;font-weight:700;font-size:12px}
${BW ? `body{color:#000}h1{color:#000!important}.k{border-bottom-color:#000!important}.info{background:#fff!important;border-color:#000!important}img{filter:grayscale(1)}th,td{border-color:#999!important}` : LT ? `.info{background:#fff!important}.k{border-bottom-width:1.5px!important}` : ""}</style></head><body>
<div class="k"><div>المملكة العربية السعودية<br>وزارة التعليم<br>${sheet.edu}<br>${sheet.school}</div><div>${logo}</div><div class="l">العام الدراسي: ${sheet.year}<br>${sheet.semester}<br>المادة: ${sheet.subject || "—"}</div></div>
<h1>سجل رصد التقويم التكويني</h1>
<div class="info"><span>المعلم: ${sheet.teacher || "—"}</span><span>المادة: ${sheet.subject || "—"}</span><span>الصف: ${sheet.level}</span><span>الفصل: ${sheet.section}</span><span>عدد الطلاب: ${named.length}</span><span>${FG_FORMS[form].ic} ${FG_FORMS[form].t}</span></div>
<table style="font-size:10px"><thead><tr><th rowspan="${HR}">م</th><th rowspan="${HR}" style="min-width:150px">اسم الطالب</th>${gh}<th rowspan="${HR}">المجموع<br><small>${maxTotal}</small></th></tr><tr>${ch}</tr>${anyMulti ? `<tr>${sh3}</tr>` : ""}</thead><tbody>${body}</tbody></table>
<div class="sig"><span>معلم المادة: ${sheet.teacher || "............"}</span><span>التوقيع: ............</span><span>مدير المدرسة: فازع القرني ............</span></div>
<script>setTimeout(()=>print(),600)</script></body></html>`);
  };

  // ── إدارة السجلات
  const newSheet = () => {
    const s = fgNewSheet({ teacher: sheet.teacher, subject: sheet.subject, model: sheet.model, semester: sheet.semester, edu: sheet.edu });
    const next = [s, ...sheets]; setSheets(next); setActiveId(s.id); persist(next);
  };
  const dupSheet = () => {
    const s = { ...JSON.parse(JSON.stringify(sheet)), id: "fg-" + Date.now(), section: sheet.section, students: sheet.students.map(st => ({ ...st, id: fgId(), scores: {} })) };
    s.students = s.students.map(st => ({ ...st, scores: {} }));
    const next = [s, ...sheets]; setSheets(next); setActiveId(s.id); persist(next);
  };
  const deleteSheet = () => {
    if (!window.confirm("حذف هذا السجل نهائياً؟")) return;
    let next = sheets.filter(s => s.id !== sheet.id);
    if (!next.length) next = [fgNewSheet()];
    setSheets(next); setActiveId(next[0].id); persist(next);
  };

  const groupSum = (g) => Math.round(sheet.cols.filter(c => c.groupId === g.id).reduce((a, c) => a + (+c.max || 0) * wOf(c), 0) * 100) / 100;
  let colIndex = -1;

  return (
    <div className="fg px-3 md:px-6 py-4" dir="rtl">
      <style>{FG_CSS}</style>

      {/* شريط السجلات */}
      <div className="fg-card p-3 mb-4">
        <div className="flex items-center justify-between gap-3 mb-2 flex-wrap">
          <div className="flex items-center gap-2">
            <span style={{ width: 38, height: 38, borderRadius: 12, display: "grid", placeItems: "center", fontSize: 20, background: "linear-gradient(135deg,#2dd4bf,#0f766e)", boxShadow: "0 6px 14px -6px #0f766e" }}>📘</span>
            <div><div className="font-black" style={{ fontSize: 16 }}>سجلات التقويم التكويني</div><div className="text-xs font-bold text-gray-400">وفق لائحة تقويم الطالب — سجل لكل مادة وفصل</div></div>
          </div>
          <div className="flex gap-2 flex-wrap">
            <button className="fg-btn pri" onClick={newSheet}>＋ سجل جديد</button>
            <button className="fg-btn" onClick={dupSheet}>⧉ نسخ لفصل آخر</button>
            <button className="fg-btn red" onClick={deleteSheet}>🗑 حذف السجل</button>
          </div>
        </div>
        <div className="fg-sheets">
          {sheets.map(s => (
            <button key={s.id} className={`fg-sheet ${s.id === sheet.id ? "on" : ""}`} onClick={() => setActiveId(s.id)}>
              <b>📚 {s.subject || "مادة غير محددة"}</b>
              <small>{s.level.replace("الصف ", "")} / {s.section} • {s.students.filter(x => x.name.trim()).length} طالب</small>
            </button>
          ))}
        </div>
      </div>

      <div className="fg-card">
        {/* الكليشة */}
        <div className="fg-klish">
          <div className="grid items-center gap-4" style={{ gridTemplateColumns: "1fr auto 1fr" }}>
            <div className="col">
              <div>المملكة العربية السعودية</div>
              <div>وزارة التعليم</div>
              <input value={sheet.edu} onChange={e => set("edu", e.target.value)} />
              <input value={sheet.school} onChange={e => set("school", e.target.value)} />
            </div>
            <div className="text-center" style={{ position: "relative", zIndex: 1 }}>
              {typeof SCHOOL_LOGO !== "undefined" && <img src={SCHOOL_LOGO} alt="" style={{ width: 64, height: 64, margin: "0 auto 4px", filter: "drop-shadow(0 4px 10px rgba(0,0,0,.3))" }} />}
              <div className="fg-title">سجل رصد التقويم التكويني</div>
              {modelInfo && <div style={{ fontSize: 11, fontWeight: 800, opacity: .85 }}>{modelInfo.name} • تقويم {modelInfo.type} • {maxTotal} درجة</div>}
            </div>
            <div className="col" style={{ textAlign: "left" }}>
              <div className="flex gap-1 items-center justify-end">العام الدراسي: <input style={{ width: 70, textAlign: "center" }} value={sheet.year} onChange={e => set("year", e.target.value)} /></div>
              <div>{sheet.semester}</div>
              <div>المادة: {sheet.subject || "—"}</div>
              <div>{sheet.level} / {sheet.section}</div>
            </div>
          </div>
        </div>

        {/* بيانات المعلم والمادة */}
        <div className="p-4 grid gap-3" style={{ gridTemplateColumns: "repeat(auto-fit,minmax(170px,1fr))", background: "linear-gradient(180deg,#f0fdfa,#fff)" }}>
          <div>
            <span className="fg-lbl flex items-center justify-between">👨‍🏫 المعلم
              <button onClick={() => staffRef.current?.click()} title="تحديث قائمة المعلمين من تقرير الحضور والانصراف" style={{ background: "none", border: "none", color: "#0d9488", fontWeight: 800, fontSize: 10.5, cursor: "pointer", fontFamily: "inherit" }}>📥 تحديث القائمة</button>
            </span>
            <input ref={staffRef} type="file" accept=".xlsx,.xls,.csv" hidden onChange={onStaffFile} />
            <select className="fg-inp" value={sheet.teacher || ""} onChange={e => onTeacherPick(e.target.value)}>
              <option value="">— اختر المعلم ({teachersList.length}) —</option>
              {[...new Set([...(sheet.teacher && !teachersList.includes(sheet.teacher) ? [sheet.teacher] : []), ...teachersList])].map(t => <option key={t} value={t}>{t}</option>)}
              <option value="__add">➕ إضافة معلم آخر…</option>
            </select>
          </div>
          <div><span className="fg-lbl">📚 المادة</span>
            <input className="fg-inp" list="fg-subjects" value={sheet.subject} placeholder="اختر أو اكتب المادة" onChange={e => onSubject(e.target.value)} />
            <datalist id="fg-subjects">{Object.keys(subjects).map(s => <option key={s} value={s} />)}</datalist>
          </div>
          <div><span className="fg-lbl">🎓 الصف</span><select className="fg-inp" value={sheet.level} onChange={e => onLevel(e.target.value)}>{FG_LEVELS.map(l => <option key={l}>{l}</option>)}</select></div>
          <div><span className="fg-lbl">🚪 الفصل</span><select className="fg-inp" value={sheet.section} onChange={e => changeClass(sheet.level, e.target.value)}>{[...new Set([...(FG_SECTIONS[sheet.level] || ["1"]), String(sheet.section || "1")])].map(l => <option key={l} value={l}>{sheet.level.replace("الصف ", "")} / {l}</option>)}</select></div>
          <div><span className="fg-lbl">🗓 الفترة الدراسية</span><select className="fg-inp" value={sheet.semester} onChange={e => set("semester", e.target.value)}>{FG_SEMESTERS.map(l => <option key={l}>{l}</option>)}</select></div>
          <div><span className="fg-lbl">📐 نموذج التوزيع</span><button className="fg-inp text-right" style={{ cursor: "pointer" }} onClick={() => setModal("model")}>{modelInfo ? `${modelInfo.name} — ${modelInfo.type}` : "مخصص"} ▾</button></div>
        </div>
        <div className="px-4 pb-3 grid gap-2" style={{ gridTemplateColumns: "repeat(auto-fit,minmax(240px,1fr))" }}>
          {Object.entries(FG_FORMS).map(([k, f]) => { const on = form === k; return (
            <button key={k} type="button" onClick={() => applyForm(k)} style={{ textAlign: "right", fontFamily: "inherit", cursor: "pointer", borderRadius: 18, padding: "12px 14px", border: `2px solid ${on ? f.c : "#e2e8f0"}`, background: on ? `linear-gradient(135deg,${f.c}14,#fff)` : "#fff", boxShadow: on ? `0 8px 20px -12px ${f.c}` : "none", display: "flex", gap: 10, alignItems: "center" }}>
              <span style={{ fontSize: 26 }}>{f.ic}</span>
              <span style={{ flex: 1, minWidth: 0 }}><b style={{ display: "block", fontSize: 14, fontWeight: 900, color: on ? f.c : "#0f172a" }}>{f.t}{on ? " ✓" : ""}</b><small style={{ fontSize: 11.5, fontWeight: 700, color: "#64748b" }}>{f.d}</small></span>
            </button>); })}
          <div style={{ gridColumn: "1/-1", fontSize: 11.5, fontWeight: 800, color: "#64748b" }}>ℹ️ {form === "final" ? "تُطبَّق النسبة الشرطية (٢٠٪ من درجة الاختبار النهائي = ٨ من ٤٠). الاختباران القصيران كل منهما من ٢٠ ويُحتسب نصفه." : "لا يوجد اختبار نهائي: التقويمات التحريرية والشفهية/العملية من ٦٠ (ثلاثة تقويمات كل منها من ٢٠)."} الدور الثاني: يحتفظ الطالب بـ٤٠ ويُختبر من ٦٠.</div>
        </div>

        {/* مؤشرات */}
        <div className="px-4 pb-3 fg-kpi">
          <div style={{ background: "linear-gradient(135deg,#14b8a6,#0f766e)" }}><b>{named.length}</b><small>عدد الطلاب</small></div>
          <div style={{ background: "linear-gradient(135deg,#60a5fa,#2563eb)" }}><b>{calcs.length ? avg.toFixed(1) + "%" : "—"}</b><small>متوسط الفصل</small></div>
          <div style={{ background: "linear-gradient(135deg,#34d399,#16a34a)" }}><b>{excellent}</b><small>ممتاز (٩٠٪ فأكثر)</small></div>
          <div style={{ background: "linear-gradient(135deg,#fb7185,#dc2626)" }}><b>{weak}</b><small>بحاجة لخطة علاجية</small></div>
        </div>

        {/* الأدوات */}
        <div className="px-4 pb-3 flex gap-2 flex-wrap items-center">
          <button className="fg-btn grn" onClick={() => fileRef.current?.click()}>📥 استيراد الطلاب من Excel</button>
          <input ref={fileRef} type="file" accept=".xlsx,.xls,.csv" hidden onChange={onExcel} />
          <button className="fg-btn" onClick={() => { setPasteText(""); setModal("paste"); }}>📋 لصق الأسماء</button>
          <button className="fg-btn pri" onClick={fromRoster}>🏫 من كشوف المدرسة</button>
          {classList.length > 0 && <button className="fg-btn" onClick={() => setModal("classes")}>🏫 من فصول الموقع</button>}
          <button className="fg-btn" style={sheet.pub ? { background: "#dbeafe", borderColor: "#2563eb", color: "#1d4ed8" } : null} onClick={() => { const lvI = FG_LEVELS.indexOf(sheet.level) + 1; update(s => ({ ...s, pub: !s.pub, ck: s.ck || `${lvI}-${s.section}` })); setToast(sheet.pub ? "🔒 أُخفيت الدرجات عن أولياء الأمور" : "👪 أصبحت الدرجات ظاهرة في بوابة ولي الأمر"); }}>{sheet.pub ? "👪 ✓ ظاهرة لأولياء الأمور" : "👪 إظهار لأولياء الأمور"}</button>
          <button className="fg-btn" onClick={() => addBlank(1)}>＋ طالب</button>
          <button className="fg-btn" onClick={sortByName}>↕ ترتيب أبجدي</button>
          <button className="fg-btn red" onClick={() => { if (window.confirm(`مسح جميع الطلاب (${named.length}) ودرجاتهم من هذا السجل؟`)) update(s => ({ ...s, students: Array.from({ length: 5 }, () => ({ id: fgId(), name: "", scores: {} })) })); }}>🧹 مسح الطلاب</button>
          <span style={{ flex: 1 }} />
          <button className="fg-btn" onClick={() => setShowStyle(v => !v)} style={showStyle ? { borderColor: "#0d9488", color: "#0d9488" } : undefined}>🎨 الألوان والخطوط</button>
          <button className="fg-btn" onClick={addGroup}>＋ مكوّن تقويم</button>
          <button className="fg-btn vio" onClick={exportExcel}>📤 تصدير Excel</button>
          <span style={{ display: "inline-flex", gap: 0, borderRadius: 12, overflow: "hidden", border: "1px solid #0f766e" }}><select value={ink} onChange={e => setInkM(e.target.value)} style={{ border: "none", fontFamily: "inherit", fontWeight: 800, fontSize: 12.5, padding: "0 8px", background: "#f0fdfa", color: "#0f766e" }}><option value="full">🎨 ألوان كاملة</option><option value="light">🌤️ ألوان خفيفة (توفير الحبر)</option><option value="bw">⚫ أبيض وأسود (أقصى توفير)</option></select><button className="fg-btn pri" style={{ borderRadius: 0 }} onClick={print}>🖨 طباعة</button></span>
        </div>

        {showStyle && (
          <div className="mx-4 mb-3 p-4 rounded-2xl" style={{ background: "#f8fafc", border: "1px solid #e2e8f0" }}>
            <div className="grid gap-4" style={{ gridTemplateColumns: "repeat(auto-fit,minmax(230px,1fr))" }}>
              <div>
                <div className="fg-lbl">➖ الخطوط الأفقية (بين الطلاب)</div>
                <div className="flex items-center gap-2 flex-wrap">
                  <input type="color" value={ST.line} onChange={e => setStyle("line", e.target.value)} style={{ width: 38, height: 32, border: "none", background: "none" }} />
                  {["#94a3b8", "#475569", "#0f172a", "#0d9488", "#2563eb", "#dc2626"].map(c => <span key={c} onClick={() => setStyle("line", c)} style={{ width: 22, height: 22, borderRadius: 6, background: c, cursor: "pointer", outline: ST.line === c ? "2px solid #0f172a" : "none", outlineOffset: 2 }} />)}
                </div>
                <div className="flex items-center gap-2 mt-2 text-xs font-bold text-gray-500">السُّمك
                  {[1, 2, 3].map(w => <button key={w} className="fg-btn" style={{ padding: "4px 10px", borderColor: ST.lineW === w ? "#0d9488" : undefined, color: ST.lineW === w ? "#0d9488" : undefined }} onClick={() => setStyle("lineW", w)}>{w === 1 ? "رفيع" : w === 2 ? "متوسط" : "عريض"}</button>)}
                </div>
                <div className="fg-lbl mt-3">┃ الخطوط العمودية</div>
                <div className="flex items-center gap-2">
                  <input type="color" value={ST.vline} onChange={e => setStyle("vline", e.target.value)} style={{ width: 38, height: 32, border: "none", background: "none" }} />
                  {["#e2e8f0", "#cbd5e1", "#94a3b8", "#475569"].map(c => <span key={c} onClick={() => setStyle("vline", c)} style={{ width: 22, height: 22, borderRadius: 6, background: c, cursor: "pointer", outline: ST.vline === c ? "2px solid #0f172a" : "none", outlineOffset: 2 }} />)}
                </div>
              </div>
              <div>
                <div className="fg-lbl">▦ خلفية الخلايا</div>
                <div className="flex gap-2 flex-wrap">
                  {[["tint", "بلون العمود"], ["zebra", "مخططة"], ["white", "بيضاء"]].map(([k, l]) => <button key={k} className="fg-btn" style={{ padding: "6px 12px", borderColor: ST.cells === k ? "#0d9488" : undefined, color: ST.cells === k ? "#0d9488" : undefined }} onClick={() => setStyle("cells", k)}>{l}</button>)}
                </div>
                {ST.cells === "tint" && <div className="mt-2 text-xs font-bold text-gray-500">درجة اللون <input type="range" min="4" max="40" value={ST.tint} onChange={e => setStyle("tint", +e.target.value)} style={{ verticalAlign: "middle", accentColor: "#0d9488" }} /></div>}
                {ST.cells === "zebra" && <div className="mt-2 flex items-center gap-2 text-xs font-bold text-gray-500">لون الصف المخطط <input type="color" value={ST.zebra} onChange={e => setStyle("zebra", e.target.value)} style={{ width: 38, height: 30, border: "none", background: "none" }} /></div>}
                <div className="fg-lbl mt-3">⬛ رأس المجموع</div>
                <input type="color" value={ST.head} onChange={e => setStyle("head", e.target.value)} style={{ width: 38, height: 32, border: "none", background: "none" }} />
              </div>
              <div>
                <div className="fg-lbl">🎨 ألوان المكوّنات والأعمدة</div>
                <div style={{ maxHeight: 190, overflow: "auto" }}>
                  {sheet.groups.map(g => (
                    <div key={g.id} className="mb-2">
                      <label className="flex items-center gap-2 font-black text-xs"><input type="color" value={g.color} onChange={e => setGroup(g.id, "color", e.target.value)} style={{ width: 30, height: 26, border: "none", background: "none" }} />{g.label}</label>
                      <div className="flex gap-1 flex-wrap pr-6">
                        {sheet.cols.filter(c => c.groupId === g.id).map(c => <label key={c.id} className="flex items-center gap-1 text-xs font-bold" style={{ background: "#fff", border: "1px solid #e2e8f0", borderRadius: 8, padding: "1px 6px 1px 2px" }}><input type="color" value={c.color} onChange={e => setCol(c.id, "color", e.target.value)} style={{ width: 22, height: 22, border: "none", background: "none" }} />{c.label}</label>)}
                      </div>
                    </div>
                  ))}
                </div>
              </div>
            </div>
            <div className="flex justify-end mt-2"><button className="fg-btn" style={{ padding: "5px 12px" }} onClick={() => update(s => ({ ...s, style: {} }))}>↺ الألوان الافتراضية</button></div>
          </div>
        )}

        {/* الجدول العرضي */}
        <div className="fg-wrap">
          <style>{`.fg-tbl td,.fg-tbl th{border-bottom:${ST.lineW}px solid ${ST.line}!important;border-left:1px solid ${ST.vline}!important}.fg-tbl thead th{border-bottom:${Math.max(ST.lineW, 1.5)}px solid ${ST.line}!important}`}</style>
          <table className="fg-tbl">
            <thead>
              <tr className="r1">
                <th rowSpan={anyMulti ? 3 : 2} className="stk1" style={{ width: 44, minWidth: 44 }}>م</th>
                <th rowSpan={anyMulti ? 3 : 2} className="stk2" style={{ minWidth: 175 }}>اسم الطالب</th>
                {sheet.groups.map(g => {
                  const gcols = sheet.cols.filter(c => c.groupId === g.id);
                  if (!gcols.length) return null;
                  const n = gcols.reduce((a, c) => a + spanOf(c), 0);
                  const sum = groupSum(g);
                  return (
                    <th key={g.id} colSpan={n} className="fg-grp" style={{ background: `linear-gradient(135deg, ${g.color}, ${g.color}cc)` }}>
                      <span className="gx">
                        <input value={g.label} onChange={e => setGroup(g.id, "label", e.target.value)} style={{ background: "transparent", border: "none", color: "#fff", fontFamily: "inherit", fontWeight: 900, fontSize: 13, outline: "none", width: Math.max(90, g.label.length * 8.5), textAlign: "center" }} />
                        <input type="number" min="0" value={g.max} title="درجة المكوّن" onChange={e => setGroup(g.id, "max", e.target.value === "" ? "" : +e.target.value)} style={{ width: 46, height: 24, borderRadius: 999, border: "1px solid rgba(255,255,255,.5)", background: "rgba(255,255,255,.22)", color: "#fff", textAlign: "center", fontFamily: "inherit", fontWeight: 900, fontSize: 12, outline: "none" }} />
                        {sum !== +g.max && <><span className="warn" title="مجموع درجات الأعمدة لا يطابق درجة المكوّن">⚠ {sum}/{g.max}</span><button className="addc" style={{ color: g.color, width: "auto", padding: "0 6px", fontSize: 11 }} title="توزيع درجة المكوّن بالتساوي على أعمدته" onClick={() => distribute(g.id)}>⚖ توزيع</button></>}
                        <button className="addc" style={{ color: g.color, width: "auto", padding: "0 7px", fontSize: 11.5 }} title="إضافة عمود رئيسي" onClick={() => addCol(g.id)}>＋ عمود</button>
                        <button className="addc" style={{ color: "#dc2626" }} title="حذف المكوّن بكل أعمدته" onClick={() => delGroup(g.id)}>🗑</button>
                      </span>
                    </th>
                  );
                })}
                <th rowSpan={anyMulti ? 3 : 2} className="fg-addcol" style={{ minWidth: 92 }}>
                  <button onClick={addColEnd} title="إضافة عمود جديد في آخر السجل">＋<span>إضافة عمود</span></button>
                  <select value="" onChange={e => { if (e.target.value) dupCol(e.target.value); }} title="تكرار عمود موجود">
                    <option value="">⧉ تكرار عمود…</option>
                    {orderedColsAll.map(c => <option key={c.id} value={c.id}>{c.label}</option>)}
                  </select>
                </th>
                <th rowSpan={anyMulti ? 3 : 2} style={{ minWidth: 80, background: ST.head, color: "#fff", fontWeight: 900 }}>المجموع<div style={{ fontSize: 11, opacity: .7 }}>من {maxTotal}</div></th>
                <th rowSpan={anyMulti ? 3 : 2} style={{ width: 34, background: ST.head }}></th>
              </tr>
              <tr className="r2">
                {orderedColsAll.map(c => {
                  const multi = nEntries(c) > 1;
                  return (
                  <th key={c.id} className="fg-ch" colSpan={spanOf(c)} rowSpan={!multi && anyMulti ? 2 : 1} style={{ background: c.color + "10" }}>
                    <button className="fg-xdel" title="حذف العمود" onClick={() => delCol(c.id)}>✕</button>
                    <div className="bar" style={{ background: c.color }} />
                    <input className="l" value={c.label} onChange={e => setCol(c.id, "label", e.target.value)} />
                    <div className="mx">
                      من <input type="number" min="0" value={c.max} onChange={e => setCol(c.id, "max", e.target.value === "" ? "" : +e.target.value)} />
                      <span style={{ marginRight: 4 }}>خانات</span>
                      <input type="number" min="1" max="10" value={nEntries(c)} title="عدد الخانات داخل العمود" onChange={e => setCol(c.id, "entries", Math.max(1, Math.min(10, parseInt(e.target.value) || 1)))} style={{ width: 34 }} />
                    </div>
                    <div className="tools">
                      <button title="نقل يميناً" onClick={() => moveCol(c.id, -1)}>→</button>
                      <button title="اللون" onClick={() => setSwatch(swatch === c.id ? null : c.id)} style={{ background: c.color }}>&nbsp;</button>
                      <button title="نقل يساراً" onClick={() => moveCol(c.id, 1)}>←</button>
                      <button title={wOf(c) === 0.5 ? "تُحسب ÷٢ — اضغط لإلغاء القسمة" : "اضغط لاحتساب هذا العمود ÷٢"} onClick={() => setCol(c.id, "weight", wOf(c) === 0.5 ? 1 : 0.5)} style={{ width: "auto", padding: "0 4px", fontWeight: 900, background: wOf(c) === 0.5 ? c.color : "#f1f5f9", color: wOf(c) === 0.5 ? "#fff" : "#475569" }}>÷٢</button>
                      <button title="تكرار العمود (نسخة بنفس الإعدادات بجانبه)" onClick={() => dupCol(c.id)} style={{ fontWeight: 900 }}>⧉</button>
                    </div>
                    {wOf(c) === 0.5 && <div style={{ fontSize: 9.5, fontWeight: 800, color: c.color }}>يُحتسب {Math.round((+c.max || 0) / 2 * 100) / 100} في المجموع</div>}
                    {swatch === c.id && (
                      <div className="fg-sw" onMouseLeave={() => setSwatch(null)}>
                        {FG_PALETTE.map(p => <span key={p} style={{ background: p }} onClick={() => { setCol(c.id, "color", p); setSwatch(null); }} />)}
                        <input type="color" value={c.color} onChange={e => setCol(c.id, "color", e.target.value)} title="لون مخصص" style={{ width: 20, height: 20, border: "none", padding: 0, background: "none", gridColumn: "span 1" }} />
                      </div>
                    )}
                  </th>);
                })}
              </tr>
              {anyMulti && (
                <tr className="r3">
                  {orderedColsAll.filter(c => nEntries(c) > 1).flatMap(c =>
                    keysOf(c).map((k, i) => <th key={k} style={{ background: hexA(c.color, .1) }}>{i + 1}<span style={{ fontSize: 9, color: "#94a3b8", fontWeight: 700 }}> /{entryMax(c)}</span></th>)
                  )}
                </tr>
              )}
            </thead>
            <tbody>
              {sheet.students.map((st, ri) => {
                const r = rowCalc(st);
                let ci = -1;
                return (
                  <tr key={st.id}>
                    <td className="stk1" style={{ fontWeight: 900, color: "#94a3b8" }}>{ri + 1}</td>
                    <td className="stk2 fg-name"><input data-fg={`${ri}-n`} value={st.name} placeholder="اسم الطالب…" onChange={e => setName(st.id, e.target.value)} onKeyDown={e => { if (e.key === "Enter") { e.preventDefault(); if (ri === sheet.students.length - 1) addBlank(1); setTimeout(() => document.querySelector(`[data-fg="${ri + 1}-n"]`)?.focus(), 30); } }} /></td>
                    {orderedColsAll.flatMap(c => {
                      const multi = nEntries(c) > 1;
                      const cells = keysOf(c).map(k => {
                        ci++; const idx = ci;
                        const v = st.scores?.[k] ?? ""; const n = num(v);
                        const lim = entryMax(c);
                        const bad = n != null && (n > lim || n < 0);
                        return (
                          <td key={k} className={`fg-cell ${multi ? "fg-sub" : ""} ${bad ? "bad" : ""}`} style={{ background: cellBg(c, ri, n != null), "--c": c.color }}>
                            <input data-fg={`${ri}-${idx}`} inputMode="decimal" value={v} onChange={e => setScore(st.id, k, e.target.value.replace(/[^\d.٠-٩]/g, ""))} onKeyDown={e => onKey(e, ri, idx)} title={bad ? `الحد الأعلى ${lim}` : ""} />
                          </td>
                        );
                      });
                      return cells;
                    })}
                    <td className="fg-addcol-td"></td>
                    <td className="fg-tot" style={{ color: "#0f172a" }}>{r.any ? r.t : ""}{r.any && !r.cond && <div style={{ fontSize: 9, fontWeight: 800, color: "#dc2626" }}>لم يحقق النسبة الشرطية</div>}</td>
                    <td><button className="fg-rowdel" title="حذف الطالب" onClick={() => { if (!st.name || window.confirm(`حذف ${st.name}؟`)) delStudent(st.id); }}>✕</button></td>
                  </tr>
                );
              })}
              {!sheet.students.length && <tr><td colSpan={orderedColsAll.reduce((a, c) => a + spanOf(c), 0) + 5} style={{ padding: 40, color: "#94a3b8", fontWeight: 800 }}>لا يوجد طلاب — استورد من Excel أو الصق الأسماء</td></tr>}
            </tbody>
            <tfoot>
              <tr className="fg-foot">
                <td className="stk1"></td>
                <td className="stk2" style={{ textAlign: "right", paddingRight: 10 }}>📊 متوسط العمود</td>
                {orderedColsAll.flatMap(c => nEntries(c) > 1
                  ? keysOf(c).map(k => <td key={k} style={{ color: c.color, fontSize: 11 }}>{keyAvg(k)}</td>)
                  : [<td key={c.id} style={{ color: c.color }}>{colAvg(c)}</td>])}
                <td className="fg-addcol-td"></td>
                <td>{calcs.length ? (calcs.reduce((a, r) => a + r.t, 0) / calcs.length).toFixed(1) : "—"}</td>
                <td></td>
              </tr>
            </tfoot>
          </table>
        </div>
        <div className="p-3 flex items-center justify-between flex-wrap gap-2 text-xs font-bold text-gray-500">
          <span className="fg-addrows">
            <span>إضافة</span>
            <input type="number" min="1" max="60" value={rowsN} onChange={e => setRowsN(e.target.value)} />
            <span>صف</span>
            <button className="fg-btn pri" onClick={() => addBlank(rowsN)}>＋ إضافة صفوف في آخر السجل</button>
            <button className="fg-btn" onClick={delBlankRows} title="حذف الصفوف التي ليس فيها اسم ولا درجات">🧹 حذف الصفوف الفارغة</button>
          </span>
          <span>💡 Enter للانتقال للطالب التالي • الأسهم للتنقل • الخلية الحمراء تتجاوز الدرجة • يُحفظ تلقائياً</span>
        </div>
      </div>

      {/* نافذة: لصق الأسماء */}
      {modal === "paste" && (
        <div className="fg-modal" onClick={() => setModal(null)}><div onClick={e => e.stopPropagation()}>
          <h3 className="font-black text-lg mb-1">📋 لصق أسماء الطلاب</h3>
          <p className="text-xs text-gray-500 font-bold mb-3">اسم في كل سطر (يمكن النسخ من نور أو Excel مباشرة)</p>
          <textarea className="fg-inp" style={{ height: 260, padding: 12, lineHeight: 1.9 }} value={pasteText} onChange={e => setPasteText(e.target.value)} placeholder={"محمد عبدالله أحمد\nفهد سعد علي\n..."} />
          <div className="flex gap-2 mt-3 justify-end">
            <button className="fg-btn" onClick={() => setModal(null)}>إلغاء</button>
            <button className="fg-btn pri" onClick={() => { addStudents(pasteText.split(/\n/).map(l => l.replace(/^\s*\d+[\s.\-)]*/, "").split("\t").find(x => /[؀-ۿ]/.test(x)) || "")); setModal(null); }}>إضافة {pasteText.split(/\n/).filter(l => l.trim()).length} طالب</button>
          </div>
        </div></div>
      )}

      {/* نافذة: Excel */}
      {modal === "excel" && xl && (() => {
        const sh = xl.sheets.find(x => x.name === xl.sheet) || xl.sheets[0];
        const names = fgUniqueNames(sh.body, xl.col);
        const m = sh.meta || {};
        const hdrs = sh.headerRow || [];
        const match = m.levelNorm ? sheets.find(x => x.level === m.levelNorm && String(x.section) === String(m.section || "")) : null;
        const chip = (icon, label, val) => (
          <div style={{ flex: "1 1 130px", background: val ? "#f0fdfa" : "#f8fafc", border: `1px solid ${val ? "#99f6e4" : "#e2e8f0"}`, borderRadius: 14, padding: "8px 12px" }}>
            <div style={{ fontSize: 10.5, fontWeight: 800, color: "#64748b" }}>{icon} {label}</div>
            <div style={{ fontSize: 13.5, fontWeight: 900, color: val ? "#0f766e" : "#cbd5e1" }}>{val || "غير محدد"}</div>
          </div>
        );
        const opt = (value, title, sub) => (
          <label key={value} style={{ display: "flex", gap: 10, alignItems: "flex-start", padding: "10px 12px", borderRadius: 14, cursor: "pointer", border: `1.5px solid ${xl.target === value ? "#0d9488" : "#e2e8f0"}`, background: xl.target === value ? "#f0fdfa" : "#fff" }}>
            <input type="radio" checked={xl.target === value} onChange={() => setXl({ ...xl, target: value })} style={{ marginTop: 4, accentColor: "#0d9488" }} />
            <div><div style={{ fontWeight: 900, fontSize: 13 }}>{title}</div><div style={{ fontSize: 11, fontWeight: 700, color: "#64748b" }}>{sub}</div></div>
          </label>
        );
        return (
        <div className="fg-modal" onClick={() => setModal(null)}><div onClick={e => e.stopPropagation()}>
          <div className="flex items-center justify-between mb-3">
            <h3 className="font-black text-lg">📥 استيراد الطلاب</h3>
            <span className="fg-badge" style={{ background: names.length ? "#dcfce7" : "#fee2e2", color: names.length ? "#15803d" : "#b91c1c", fontSize: 12.5 }}>👨‍🎓 {names.length} طالب</span>
          </div>
          {sh.staff && (
            <div style={{ background: "#fef2f2", border: "1px solid #fecaca", color: "#b91c1c", borderRadius: 12, padding: "10px 12px", fontSize: 12.5, fontWeight: 800, marginBottom: 10, lineHeight: 1.8 }}>
              ⚠️ هذا الملف يبدو <u>تقرير حضور موظفين</u> وليس كشف طلاب. من نور صدّر «كشف بأسماء الطلاب» للفصل.
            </div>
          )}

          {/* ١) الفصل المكتشف */}
          <div className="fg-lbl">الفصل المكتشف من الملف</div>
          <div className="flex gap-2 flex-wrap mb-3">
            {chip("🎓", "الصف", m.levelNorm || m.level)}
            {chip("🚪", "الفصل", m.section)}
            {chip("🏫", "المدرسة", m.school)}
          </div>

          {/* ٢) الطلاب */}
          <div style={{ maxHeight: 210, overflow: "auto", border: "1px solid #e2e8f0", borderRadius: 14, marginBottom: 6 }}>
            {names.slice(0, 80).map((n, i) => <div key={i} style={{ padding: "6px 12px", borderBottom: "1px solid #f1f5f9", fontWeight: 700, fontSize: 13, background: i % 2 ? "#fafafa" : "#fff" }}><span style={{ color: "#94a3b8", marginLeft: 10, display: "inline-block", width: 20 }}>{i + 1}</span>{n}</div>)}
            {!names.length && <div style={{ padding: 20, textAlign: "center", color: "#94a3b8", fontWeight: 800, fontSize: 13 }}>لم أجد أسماء — اضغط «تغيير عمود الأسماء» أدناه</div>}
          </div>
          <button onClick={() => setXl({ ...xl, adv: !xl.adv })} style={{ background: "none", border: "none", color: "#64748b", fontWeight: 800, fontSize: 11.5, cursor: "pointer", fontFamily: "inherit", marginBottom: 8 }}>{xl.adv ? "▲ إخفاء" : "⚙ تغيير عمود الأسماء"}</button>
          {xl.adv && (
            <div className="grid gap-2 mb-3" style={{ gridTemplateColumns: xl.sheets.length > 1 ? "1fr 1fr" : "1fr" }}>
              {xl.sheets.length > 1 && <select className="fg-inp" value={xl.sheet} onChange={e => { const n = xl.sheets.find(x => x.name === e.target.value); setXl({ ...xl, sheet: n.name, col: n.col }); }}>{xl.sheets.map(x => <option key={x.name} value={x.name}>📄 {x.name}</option>)}</select>}
              <select className="fg-inp" value={xl.col} onChange={e => setXl({ ...xl, col: +e.target.value })}>
                {(sh.used || []).map(i => { const ex = String((sh.body.find(r => String(r[i] ?? "").trim()) || [])[i] ?? "").slice(0, 24); return <option key={i} value={i}>{String(hdrs[i] ?? "").trim() || "بدون عنوان"} — {ex}</option>; })}
              </select>
            </div>
          )}

          {/* ٣) الوجهة */}
          <div className="fg-lbl">أين تُضاف الأسماء؟</div>
          <div className="grid gap-2 mb-3">
            {match && opt(match.id, `سجل ${match.level} / ${match.section} الموجود`, `${match.subject || "بدون مادة"} • ${match.students.filter(x => x.name.trim()).length} طالب حالياً — تُضاف الأسماء الجديدة فقط`)}
            {opt("current", "السجل المفتوح الآن", `${sheet.subject || "بدون مادة"} • ${sheet.level} / ${sheet.section}${m.levelNorm ? " ← يُحدَّث إلى " + m.levelNorm + " / " + (m.section || "") : ""}`)}
            {opt("new", "سجل جديد لهذا الفصل", `${m.levelNorm || sheet.level} / ${m.section || sheet.section} — بنفس المادة والأعمدة`)}
          </div>

          <div className="flex gap-2 justify-between items-center flex-wrap">
            <button className="fg-btn" onClick={downloadTemplate}>⬇ نموذج فارغ</button>
            <div className="flex gap-2">
              <button className="fg-btn" onClick={() => setModal(null)}>إلغاء</button>
              <button className="fg-btn grn" disabled={!names.length} style={{ opacity: names.length ? 1 : .5 }} onClick={() => {
                if (names.length > 70 && !window.confirm(`سيتم إضافة ${names.length} اسماً — عدد كبير لفصل واحد. متابعة؟`)) return;
                importTo(xl.target, names, m); setModal(null);
              }}>✔ استيراد {names.length} طالب</button>
            </div>
          </div>
        </div></div>
        );
      })()}

      {toast && <div style={{ position: "fixed", bottom: 24, left: "50%", transform: "translateX(-50%)", zIndex: 300, background: "#0f172a", color: "#fff", padding: "12px 20px", borderRadius: 14, fontWeight: 800, fontSize: 13.5, boxShadow: "0 14px 30px -10px rgba(0,0,0,.5)" }}>{toast}</div>}

      {/* نافذة: من فصول الموقع */}
      {modal === "classes" && (
        <div className="fg-modal" onClick={() => setModal(null)}><div onClick={e => e.stopPropagation()}>
          <h3 className="font-black text-lg mb-3">🏫 استيراد من فصول الموقع</h3>
          <div className="grid gap-2">
            {classList.map(c => { const n = (c.students || []).filter(s => s.name).length; return (
              <button key={c.id} className="fg-sheet" style={{ minWidth: 0 }} onClick={() => { addStudents((c.students || []).map(s => s.name)); setModal(null); }}>
                <b>{c.name || `${c.level} / ${c.section}`}</b><small>{n} طالب {c.teacher ? "• " + c.teacher : ""}</small>
              </button>); })}
          </div>
        </div></div>
      )}

      {/* نافذة: نموذج اللائحة */}
      {modal === "model" && (
        <div className="fg-modal" onClick={() => setModal(null)}><div onClick={e => e.stopPropagation()}>
          <h3 className="font-black text-lg mb-1">📐 نموذج توزيع الدرجات</h3>
          <p className="text-xs text-gray-500 font-bold mb-3">اختيار نموذج يبني الأعمدة تلقائياً حسب مكوناته (يمكنك بعدها الإضافة والحذف)</p>
          <div className="grid gap-2">
            {typeof GA_MODELS !== "undefined" && Object.entries(GA_MODELS).map(([k, m]) => (
              <button key={k} className={`fg-sheet ${sheet.model === k ? "on" : ""}`} style={{ minWidth: 0 }} onClick={() => applyModel(k)}>
                <b>{m.name} — تقويم {m.type}</b>
                <small>{Object.entries(m.parts).map(([p, v]) => `${p} (${v})`).join(" + ")}</small>
                <small style={{ display: "block", color: "#94a3b8" }}>الدور الثاني: {m.round2}</small>
              </button>
            ))}
          </div>
        </div></div>
      )}
    </div>
  );
}

// ══════════════════════════════════════════════════════════
// التحضير الصباحي — الحصة الثانية
// الفصول: school-mroster/{ck}   التحضير: school-mattend/{YYYY-MM-DD}/{ck}   الفهرس: school-mattend-index/{date}
// ══════════════════════════════════════════════════════════
