  const auto = [...S.best.map(x => `🌟 تميز واضح في: ${x.it.t}`), ...S.need.map(x => `🎯 يحتاج تركيزاً: ${x.it.t}`), ...S.lowEv.slice(0, 3).map(x => `▫️ مشاهدة قليلة الظهور: ${x.t}`)].join("\n");
