    const mineCls = ti >= 0 ? [...new Set(Object.keys(T.C).filter(ck => T.C[ck].some(d => d.some(c => c && c[1] === ti))))].sort((a, b) => a.localeCompare(b, "en", { numeric: true })) : [];
