  const W = 680, lw = 175, top = 8, rh = 22, H = top + items.length * rh + 6, x0 = W - lw, span = x0 - 60, mx = Math.max(1, max || Math.max(...items.map(x => x.v)));
  const grid = [0, .25, .5, .75, 1].map(f => `<line x1="${x0 - f * span}" x2="${x0 - f * span}" y1="2" y2="${H - 4}" stroke="${AL_GRID}"/>`).join("");
