const CR_TXT_C = ["#0f172a", "#b91c1c", "#c2410c", "#b45309", "#15803d", "#0f766e", "#1d4ed8", "#6d28d9", "#db2777", "#64748b"];
const CR_HL_C = ["#fef08a", "#fecaca", "#bbf7d0", "#bfdbfe", "#e9d5ff", "#fed7aa", "#f1f5f9"];
