      const ck = sttClassOf(T, d, p, key); if (ck) { const [si] = T.C[ck][d][p]; return `<td style="border-top:4px solid ${sc(si)}"><b>${ptEsc(maClassName(ck))}</b><i style="color:${sc(si)}">${ptEsc(subName(si))}</i></td>`; }
