  const sk = []; if (!ok(L)) sk.push("تمييز الحروف وأصواتها", "التمييز بين الحروف المتشابهة رسماً"); if (!ok(S)) sk.push("قراءة المقاطع الصوتية", "مراعاة الحركات والضبط"); if (!ok(W)) sk.push("قراءة الكلمات"); if (!ok(P)) sk.push("قراءة الجمل القصيرة"); if (wpm != null && wpm < tg || !ok(P)) sk.push("الطلاقة (السرعة والدقة)"); if (!ok(C)) sk.push("الفهم القرائي");
