    setExc(E); setExtra({ excN: vals(ex).length, excOk: vals(ex).filter(x => x.status === "ok").length, reps: vals(pr).length, warn: vals(pr).filter(r => r.type === "warn").length, inv: vals(pr).filter(r => r.type === "invite").length });
