  // 📱 الجوال الحقيقي: الواجهة بملء الشاشة + شريط سفلي + قائمة أقسام تُفتح عند الطلب
  const [narrow, setNarrow] = useState(() => typeof window !== "undefined" && window.innerWidth < 700);
  const [mNav, setMNav] = useState(false);
  const mScrollRef = useRef(null);
  useEffect(() => { const f = () => setNarrow(window.innerWidth < 700); window.addEventListener("resize", f); return () => window.removeEventListener("resize", f); }, []);
  useEffect(() => { setMNav(false); if (mScrollRef.current) mScrollRef.current.scrollTop = 0; }, [page]);
  const [teachers, setTeachers] = useState(DEFAULT_TEACHERS);
  const [week, setWeek] = useState(DEFAULT_WEEK);
  const [attendance, setAttendance] = useState({});
  const [announcements, setAnnouncements] = useState([]);
  const [activities, setActivities] = useState(DEFAULT_ACTIVITIES);
  const [classList, setClassList] = useState([]);
  const [users] = useState(DEFAULT_USERS);
  const [siteFont, setSiteFont] = useState("'Noto Naskh Arabic', serif");
  const [messages, setMessages] = useState([]);
  const [surveys, setSurveys] = useState([]);
  const [weekArchive, setWeekArchive] = useState([]);
  useEffect(() => { try { window.__pamUser = user ? (user.name || user.username || "") : ""; } catch {} }, [user]);
  useEffect(() => { try { const t = HUB_GROUPS.flatMap(g => g.tools).find(x => x.id === page); window.__pamPageLabel = t ? t.label : page; } catch {} }, [page]);

  const [licPortal, setLicPortal] = useState(() => window.location.hash.replace("#", "") === "license");
  const [hfxPortal, setHfxPortal] = useState(() => /^#hfx=/.test(window.location.hash));
  const [circPortal, setCircPortal] = useState(() => /^#circ=/.test(window.location.hash));
  const [f9Portal, setF9Portal] = useState(() => /^#f9(=|$)/.test(window.location.hash));
  const [attPortal, setAttPortal] = useState(() => ["attend", "absence", "ghiab"].includes(window.location.hash.replace("#", "")));
  const [clsPortal, setClsPortal] = useState(() => window.location.hash.replace("#", "") === "classify");
  const [hubPortal, setHubPortal] = useState(() => { const h = window.location.hash.replace("#", ""); return ["teacher", "staff", "parent", "weekly", "late", "visits", "duty", "nafes", "treasure", "rwt", "marji"].includes(h) ? h : /^termplan(-[\w]+)?$/.test(h) ? h : ""; });
  const [directAnnId, setDirectAnnId] = useState(() => {
    const h = window.location.hash.replace("#","");
    return h.startsWith("ann-") ? h.replace("ann-","") : null;
  });

  // فتح بوابة الأعذار مباشرة عبر رابط #excuses
  const [excuseFromHash, setExcuseFromHash] = useState(() =>
    window.location.hash.replace("#","") === "excuses"
  );

  // فتح بوابة أولياء الأمور مباشرة عبر رابط #parent-{nationalId}
  const [parentStudentId, setParentStudentId] = useState(() => {
    const h = window.location.hash.replace("#","");
    return h.startsWith("parent-") ? h.replace("parent-","") : null;
  });

  // Handle ?survey=ID URL param
  useEffect(() => {
    const params = new URLSearchParams(window.location.search);
    const surveyId = params.get("survey");
    if (surveyId) {
      window.dispatchEvent(new CustomEvent("open-survey-url", { detail: Number(surveyId) }));
    }
  }, []);

  useEffect(() => {
    const h = () => {
      const hash = window.location.hash.replace("#","") || "home";
      if (hash === "excuses") { setExcuseFromHash(true); return; }
      setExcuseFromHash(false);
      if (hash.startsWith("parent-")) {
        const sid = hash.replace("parent-","");
        setParentStudentId(sid);
        setParentPortal(true);
        return;
      }
      if (hash.startsWith("hfx=")) { setHfxPortal(true); return; }
      if (hash.startsWith("circ=")) { setCircPortal(true); return; }
      if (hash === "f9" || hash.startsWith("f9=")) { setHubPortal(""); setF9Portal(true); return; }
      if (hash.startsWith("ann-")) { setDirectAnnId(hash.replace("ann-","")); return; }
      setDirectAnnId(null);
      if (["attend", "absence", "ghiab"].includes(hash)) { setAttPortal(true); return; }
      if (hash === "teacherportal") { setTeacherProfilePortal(true); return; }
      if (["home","attendance","announcements","activities","settings","students","messages","surveys","qiyas","sms","report","gradeanalysis","monthlyreport","absencestats","attendancereport","student-absence","strategies","gallery","certificates","poll","raffle","broadcast","quiz","luckywheel","timetable","honorboard","dailyquiz","aiteacher","lessonprep","lessonrecommend","meetings","committeemeeting","teachereval","assessment","studentexcuses","perfresults","teacherreports","suggestions","dailyattend","teacherperfeval","staffdisc","studentperf","periodnotes"].concat(["nafes","treasureadm","nafsbooks","liveops","audit","stlogins","duty","asmfollow","termplan","classvisits","insights","behavior","conduct","alreport","trash","ttnow","morningboard","periodfollow","admtasks","prepadm","morninglate","weeklyplan","portals","parentinbox","dplan","peerx","studentclassify","stulevels","stlogins","readweak","morningattend","attendstats","formative","prolicense","perfresults","suggestions","dailyattend","teacherreports","admin-attendance","hfx","hdisc","circulars"]).includes(hash)) { setTeacherProfilePortal(false); setPage(hash); }
    };
    window.addEventListener("hashchange", h); h();
    return () => window.removeEventListener("hashchange", h);
  }, []);

  const navigate = (p) => {
    if (p === "teacherportal") {
      setTeacherProfilePortal(true);
      window.location.hash = "teacherportal";
      setMenuOpen(false);
      return;
    }
    setTeacherProfilePortal(false);
    setPage(p); window.location.hash = p; setMenuOpen(false);
  };
  const toggleViewMode = (m) => { setViewMode(m); localStorage.setItem("school-view-mode", m); };

  useEffect(() => {
    (async () => {
      try {
        const [t, w, att, ann, act, font, clsListMeta, msgs, survs, wArch] = await Promise.all([
          DB.get("school-teachers", DEFAULT_TEACHERS),
          DB.get("school-week", DEFAULT_WEEK),
          DB.get("school-attendance", {}),
          (async () => {
            // لا تُستخدم بيانات افتراضية ولا يُكتب أي شيء على الخادم إذا تعذّر الاتصال — يُعرض المخزّن على الجهاز فقط
            const cachedList = async () => { const c = await idbKV.get("ann-cache"); let L = Object.values((c && c.items) || {}); if (!L.length) { try { L = actArr(JSON.parse(localStorage.getItem(DB_CACHE_PREFIX + "school-announcements") || "null")); } catch {} } return L.filter(x => x && x.id != null).sort((a, b) => (Number(b.id) || 0) - (Number(a.id) || 0)); };
            let metaJ; try { metaJ = await fetchJ(`${ANN_META}`, 20000); } catch { annLoadFailed = true; return cachedList(); }
            if (metaJ && typeof metaJ === "object") { const arr = await annLoadAll(); return arr.filter(x => x && x.id != null).sort((a, b) => (Number(b.id) || 0) - (Number(a.id) || 0)); }
            let items, legacy;
            try { items = await fetchJ(ANN_NODE, 60000); legacy = await fetchJ("school-announcements", 60000); } catch { annLoadFailed = true; return cachedList(); }
            const legacyArr = actArr(legacy);
            const itemsArr = items && typeof items === "object" ? Object.values(items).filter(x => x && x.id != null) : [];
            const byId = new Map(itemsArr.map(a => [String(a.id), a]));
            const toMigrate = legacyArr.filter(a => a && a.id != null && !byId.has(String(a.id)));
            toMigrate.forEach(a => { byId.set(String(a.id), a); annPut(a.id, a); });
            const outA = [...byId.values()].sort((a, b) => (Number(b.id) || 0) - (Number(a.id) || 0));
            if (itemsArr.length || toMigrate.length) annBuildMeta(outA);
            return outA;
          })(),
          actLoad(),
          DB.get("school-font", "'Noto Naskh Arabic', serif"),
          DB.get("school-class-list", []),
          DB.get("school-messages", []),
          DB.get("school-surveys", (() => { try { const c=localStorage.getItem('school_surveys_cache'); return c?JSON.parse(c):[]; } catch{return [];} })()),
          DB.get("school-week-archive", []),
        ]);

        // ── التحقق من صحة التاريخ المحفوظ ──
        // إذا كانت السنة الهجرية أكبر من 2000 فهي بيانات تالفة — نُعيد الحساب من اليوم
        const weekIsValid = (wk) => {
          if (!wk?.days?.[0]?.dateH) return false;
          const parts = wk.days[0].dateH.split('/');
          const hYear = parseInt(parts[2] || '0');
          return hYear > 1400 && hYear < 1600;
        };

        let validWeek = w;
        if (!weekIsValid(w)) {
          // إعادة حساب الأسبوع الحالي من اليوم
          const today = new Date();
          const dow = today.getDay();
          const diffToSunday = -dow; // الجمعة/السبت → أحد الأسبوع المنتهي
          const sunday = new Date(today);
          sunday.setDate(today.getDate() + diffToSunday);
          const WDAYS = ["الأحد","الاثنين","الثلاثاء","الأربعاء","الخميس"];
          const pad = n => String(n).padStart(2,'0');
          const g2h = (gy, gm, gd) => {
            const a = Math.floor((14-gm)/12), y = gy+4800-a, mo = gm+12*a-3;
            let jdn = gd + Math.floor((153*mo+2)/5) + 365*y + Math.floor(y/4) - Math.floor(y/100) + Math.floor(y/400) - 32045;
            let l = jdn-1948440+10632;
            const n2 = Math.floor((l-1)/10631);
            l = l-10631*n2+354;
            const J = Math.floor((10985-l)/5316)*Math.floor((50*l)/17719) + Math.floor(l/5670)*Math.floor((43*l)/15238);
            l = l - Math.floor((30-J)/15)*Math.floor((17719*J)/50) - Math.floor(J/16)*Math.floor((15238*J)/43) + 29;
            const hm = Math.floor((24*l)/709);
            return { d: l-Math.floor((709*hm)/24), m: hm, y: 30*n2+J-30 };
          };
          validWeek = {
            days: WDAYS.map((name,i) => {
              const d = new Date(sunday); d.setDate(sunday.getDate()+i);
              const h = g2h(d.getFullYear(), d.getMonth()+1, d.getDate());
              return {
                name,
                dateH: `${pad(h.d)}/${pad(h.m)}/${h.y}`,
                dateM: `${pad(d.getDate())}/${pad(d.getMonth()+1)}/${d.getFullYear()}`
              };
            })
          };
          // حفظ الأسبوع الصحيح في Firebase
          DB.set("school-week", validWeek);
        }

        // استخدم الكاش المحلي إذا كانت Firebase فارغة أو بطيئة
        let finalAtt = att;
        if (!att || Object.keys(att).length === 0) {
          try {
            // جرّب الكاش الجديد أولاً ثم القديم
            const c1 = JSON.parse(localStorage.getItem(DB_CACHE_PREFIX + "school-attendance") || "null");
            const c2 = JSON.parse(localStorage.getItem("attendance_cache_v1") || "null");
            const cached = (c1 && Object.keys(c1).length > 0) ? c1 : c2;
            if (cached && Object.keys(cached).length > 0) finalAtt = cached;
          } catch {}
        }
        // Firebase يحذف المصفوفات الفارغة ويحوّل المتقطعة إلى كائنات — نوحّد الشكل
        const asArr = v => Array.isArray(v) ? v.filter(x => x != null) : (v && typeof v === "object" ? Object.values(v).filter(x => x != null) : []);
        setTeachers(asArr(t)); setWeek(validWeek); setAttendance(finalAtt || {}); setAnnouncements(asArr(ann).filter(a => !annIsSample(a)));
        actLoadedRef.current = act && act.ok; actSavedRef.current = act && act.ok ? Object.fromEntries(act.list.map(a => [String(a.id), JSON.stringify(a)])) : null; setActivities(act ? act.list : []); setSiteFont(font);
        setMessages(Array.isArray(msgs) ? msgs : []);
        setSurveys(svNorm(survs));
        setWeekArchive(Array.isArray(wArch) ? wArch : []);
        // تحميل بيانات كل فصل
        const metaArr = asArr(clsListMeta).filter(m => m && m.id);
        if (metaArr.length > 0) {
          const classDataArr = await Promise.all(metaArr.map(m => DB.get(`school-cls-${m.id}`, { ...m, students: [] })));
          setClassList(classDataArr.map((d, i) => {
            const c = { ...metaArr[i], ...(d && typeof d === "object" ? d : {}) };
            return { ...c, students: asArr(c.students).map(st => ({ ...st, name: st.name || "", grades: st.grades || {} })) };
          }));
        } else {
          // أول تشغيل — حمّل الفصل المُدرج من ملف الإكسل تلقائياً
          const meta = [{ id: PRELOADED_CLASS.id, name: PRELOADED_CLASS.name, level: PRELOADED_CLASS.level, section: PRELOADED_CLASS.section, teacher: PRELOADED_CLASS.teacher, semester: PRELOADED_CLASS.semester }];
          await DB.set("school-class-list", meta);
          await DB.set(`school-cls-${PRELOADED_CLASS.id}`, PRELOADED_CLASS);
          setClassList([PRELOADED_CLASS]);
        }
      } catch (e) { console.error(e); }
      setLoading(false);
    })();
  }, []);
  // === نظام الأرشفة التلقائية اليومية والأسبوعية ===
  React.useEffect(() => {
    const runAutoBackup = async () => {
      const today = new Date().toISOString().split("T")[0];
      const dayOfWeek = new Date().getDay(); // 0=Sunday

      try {
        // --- نسخة يومية ---
        const lastDaily = localStorage.getItem("last_daily_backup");
        if (lastDaily !== today) {
          const dailyData = {
            date: today,
            attendance: await DB.get("school-attendance", {}),
            teachers:   await DB.get("school-teachers", []),
            classList:  await DB.get("school-class-list", []),
            messages:   await DB.get("school-messages", []),
            absences:   await DB.get("school-student-absences", {}),
            remedial:   await DB.get("school-remedial-plans", {}),
          };
          // احتفظ بآخر 365 يوم
          const prevDaily = await DB.get("school-backup-daily", {});
          const dates = Object.keys(prevDaily).sort();
          if (dates.length >= 365) delete prevDaily[dates[0]];
          prevDaily[today] = dailyData;
          await DB.set("school-backup-daily", prevDaily);
          localStorage.setItem("last_daily_backup", today);
        }

        // --- نسخة أسبوعية (كل أحد) ---
        if (dayOfWeek === 0) {
          const weekKey = today;
          const lastWeekly = localStorage.getItem("last_weekly_backup");
          if (lastWeekly !== weekKey) {
            const weeklyData = {
              date: today,
              attendance:     await DB.get("school-attendance", {}),
              weekArchive:    await DB.get("school-week-archive", []),
              classList:      await DB.get("school-class-list", []),
              gradeAnalysis:  await DB.get("school-grade-analysis", {}),
              remedial:       await DB.get("school-remedial-plans", {}),
              strategies:     await DB.get("school-strategies", []),
              meetings:       await DB.get("school-meetings", []),
              committeHistory:await DB.get("school-committee-history", []),
              teacherLeaves:  await DB.get("school-teacher-leaves", {}),
              studentAbsences:await DB.get("school-student-absences", {}),
              tasks:          await DB.get("school-tasks", []),
              certificates:   await DB.get("school-certificates", []),
              honorBoard:     await DB.get("school-honor-board", []),
            };
            // احتفظ بآخر 52 أسبوع
            const prevWeekly = await DB.get("school-backup-weekly", {});
            const weeks = Object.keys(prevWeekly).sort();
            if (weeks.length >= 52) delete prevWeekly[weeks[0]];
            prevWeekly[weekKey] = weeklyData;
            await DB.set("school-backup-weekly", prevWeekly);
            localStorage.setItem("last_weekly_backup", weekKey);
          }
        }
      } catch(e) {
        console.warn("[Backup]", e.message);
      }
    };

    // شغّل النسخ الاحتياطي بعد 10 ثواني من فتح الموقع
    const t = setTimeout(runAutoBackup, 10000);
    return () => clearTimeout(t);
  }, []);

  const saveTeachers = (v) => DB.set("school-teachers", v);
  const saveWeek = (v) => DB.set("school-week", v);
  const saveAttendance = (v) => {
    // نسخة احتياطية محلية فورية
    try { localStorage.setItem("attendance_cache_v1", JSON.stringify(v)); } catch {}
    // حفظ عبر DB (يتعامل مع queue + Firebase + إشعار UI)
    DB.set("school-attendance", v);
  };
  // حفظ الإعلانات: يُرفع فقط الإعلان الذي تغيّر (أو يُحذف) — سريع ولا يفشل بسبب حجم باقي الإعلانات
  const annSavedRef = useRef(null);
  const saveAnnouncements = async (v) => {
    const list = Array.isArray(v) ? v.filter(a => a && a.id != null) : [];
    if (!annSavedRef.current) annSavedRef.current = Object.fromEntries((announcements || []).filter(a => a && a.id != null).map(a => [String(a.id), JSON.stringify(a)]));
    const prev = annSavedRef.current, next = {}, jobs = [];
    list.forEach(a => { const js = JSON.stringify(a); next[String(a.id)] = js; if (prev[String(a.id)] !== js) jobs.push(annPut(a.id, a)); });
    Object.keys(prev).forEach(id => { if (!(id in next)) jobs.push(annDelete(id)); });
    annSavedRef.current = next;
    try { localStorage.setItem(DB_CACHE_PREFIX + "school-announcements", JSON.stringify(list)); } catch {}
    const res = await Promise.all(jobs);
    return res.every(Boolean);
  };
  const actSavedRef = useRef(null); const actLoadedRef = useRef(false);
  // حفظ الأنشطة: يُرفع النشاط الذي تغيّر فقط، ويُحذف المحذوف فقط — لا يمكن أن تُستبدل أنشطة الخادم بنسخة ناقصة
  const saveActivities = async (v) => {
    const list = actArr(v); const prev = actSavedRef.current || {}; const next = {}; const jobs = [];
    list.forEach(a => { const js = JSON.stringify(a); next[String(a.id)] = js; if (prev[String(a.id)] !== js) jobs.push(actPut(a)); });
    if (actSavedRef.current) Object.keys(prev).forEach(id => { if (!(id in next)) jobs.push(actDel(id)); });
    actSavedRef.current = next; idbKV.set("act-cache", list);
    const res = await Promise.all(jobs); if (res.includes("big")) return "big"; return res.every(Boolean);
  };
